/* 自动生成，请勿手工修改。来源：DSH english/eng-vocab；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"eng-vocab-1","title":"前缀构词法：un- / dis- / re- / pre- / mis- / over-","subtitle":"词根词缀 · Prefixes: un-, dis-, re-, pre-, mis-, over-","grade":"all","tags":["词根词缀"],"blocks":[{"type":"note","title":"学习要点","text":"记住六个中考高频前缀的含义，看到生词能靠「前缀 + 已学词根」推出词义，写作时也能把同根词用准。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"un- 表否定「不、非」，也可表示相反的动作。","explain":"完形填空与阅读词义猜测题常考。判断办法：把 un- 拿掉，剩下的词若学过，词义就是「不 + 原义」，如 happy 快乐 → unhappy 不快乐；lock 锁上 → unlock 打开。"},{"level":"重点","text":"dis- 表否定，还常表示「相反的动作、去掉」。","explain":"与 un- 的分工：un- 多构成「不……」的形容词，dis- 更强调「分开、去掉、取消」，如 appear 出现 → disappear 消失，agree 同意 → disagree 不同意。动词前出现否定意味时优先考虑 dis-。"},{"level":"重点","text":"re- 表「再一次、重新」，也可表「往回」。","explain":"阅读中看到 re- 开头的生词，先按「重新 + 动词」推义，如 build 建造 → rebuild 重建，use 使用 → reuse 再利用。写作里「复习」用 review，「预习」用 preview，两个词都要求会写。"},{"level":"次重点","text":"pre- 表「在……之前、预先」。","explain":"常考 preview（预习）、prepare（准备）、predict（预测）。听力或阅读中出现 pre-，可据此判断时间先后关系，这是做排序题和细节题的重要线索。"},{"level":"次重点","text":"mis- 表「错误地、不良地」。","explain":"mistake（错误）、misunderstand（误解）、misspell（拼错）都是 mis- 加已学词。完形填空考「误会别人」时选 misunderstand，不可选 understand。"},{"level":"了解","text":"over- 表「过度、超过」，也可表示位置上的「在……上方」。","explain":"overwork（过度劳累）、oversleep（睡过头）、overcoat（大衣）。这类词多作为阅读生词出现，按「超过、太……」推断即可。"}]},{"type":"table","title":"词根词缀","head":["词缀","含义","例词"],"rows":[["un-","前缀：不、非；也构成相反的动作","unhappy 不快乐的；unusual 不寻常的；unable 不能的；unknown 未知的；unlock 开锁"],["dis-","前缀：不、非；也表示相反的动作、去掉","disagree 不同意；dislike 不喜欢；disappear 消失；dishonest 不诚实的；discover 发现"],["re-","前缀：再、重新；也表往回","rewrite 重写；return 返回；归还；rebuild 重建；review 复习；评论；reuse 再利用"],["pre-","前缀：在……之前、预先","preview 预习；预览；prepare 准备；predict 预测；prevent 阻止；预防；preschool 学前的"],["mis-","前缀：错误地、不良地","mistake 错误；弄错；misunderstand 误解；misspell 拼错；mislead 误导；misuse 误用"],["over-","前缀：过度、超过；在……上方","overwork 过度劳累；oversleep 睡过头；overcoat 大衣；overeat 吃得过多；overlook 俯瞰；忽视"]]}],"questions":[{"id":"eng-vocab-1-q1","type":"choice","stem":"He ______ his homework because there were too many mistakes in it.","answer":"A","explain":"句中说的是「因为错太多而重写」，re- 表「重新」，write 的重写形式是 rewrite，且整句叙述的是过去发生的事，用过去式 rewrote。B 项 wrote 只表示「写了」，没有「重写」的意思；C 项是动词原形，不能单独作过去句的谓语；D 项是现在分词，也不能单独作谓语。","options":["rewrote","wrote","rewrite","writing"],"difficulty":1,"tags":["前缀","re-","动词时态"]},{"id":"eng-vocab-1-q2","type":"choice","stem":"The prefix \"mis-\" in \"misunderstand\" tells us that the word means ______.","answer":"A","explain":"mis- 表示「错误地」，understand 是「理解」，合起来就是「误解、理解错了」。B 项 completely 对应的是「完全」，可由 fully 一类词表示；C 项 once again 对应前缀 re-；D 项 together 对应前缀 co-，都与 mis- 无关。","options":["to understand something in a wrong way","to understand something completely","to understand something once again","to understand something together with others"],"difficulty":2,"tags":["前缀","mis-","词义猜测"]},{"id":"eng-vocab-1-q3","type":"choice","stem":"The word \"preview\" in \"Please preview the new words before class.\" means ______ in Chinese.","answer":"A","explain":"pre- 表「在……之前」，view 表「看」，上课之前先看一遍就是「预习」。B 项「复习」对应 review，指学过之后再学一遍，方向相反；C 项「浏览」只强调快速看，没有点出「课前」这一时间关系；D 项「朗读」对应 read aloud，与 view 的词根无关。","options":["预习","复习","浏览","朗读"],"difficulty":2,"tags":["前缀","pre-","词义猜测"]},{"id":"eng-vocab-1-q4","type":"choice","stem":"The young man ______ with his father about where to go for the holiday, so they stayed at home.","answer":"A","explain":"后半句说他们留在家里，说明两个人意见不同，要用 disagree（dis- 表否定）加 with sb，且整句是过去的事，故用过去式 disagreed。B 项 agreed 意为「同意」，与「留在家中没去成」的语境矛盾；C 项是原形，不能作过去句的谓语；D 项是现在分词，同样不能单独作谓语。","options":["disagreed","agreed","disagree","agreeing"],"difficulty":2,"tags":["前缀","dis-","动词时态"]},{"id":"eng-vocab-1-q5","type":"choice","stem":"Do not ______ me. I only want you to work a little harder.","answer":"A","explain":"句意是「别误解我的意思」，mis- 表「错误地」，且 Do not 后要用动词原形。B 项 understand 是「理解」，与「别……」的否定提醒相矛盾；C、D 两项分别是现在分词和过去式，都不能用在 Do not 之后。","options":["misunderstand","understand","understanding","understood"],"difficulty":1,"tags":["前缀","mis-","动词形式"]},{"id":"eng-vocab-1-q6","type":"choice","stem":"Tom was late for school this morning because he ______.","answer":"A","explain":"迟到的原因通常是「睡过头」，over- 表「过度」，sleep 加 over- 构成 oversleep，过去式为 overslept。B 项 overwork 是「过度劳累」，与早晨起不来的情形不符；C 项 overeat 是「吃得过多」，吃得多不会导致迟到；D 项 overlook 是「俯瞰、忽视」，与语境无关。","options":["overslept","overworked","overate","overlooked"],"difficulty":2,"tags":["前缀","over-","过去式"]}]},{"id":"eng-vocab-2","title":"后缀构词法：-ful / -less / -ly / -ment / -tion / -able / -er / -ist","subtitle":"词根词缀 · Suffixes: -ful, -less, -ly, -ment, -tion, -able, -er, -ist","grade":"all","tags":["词根词缀"],"blocks":[{"type":"note","title":"学习要点","text":"掌握八个高频后缀，一眼看出所填词的词性，专治「用所给词的适当形式填空」这类词形变化题。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"-ful 与 -less 是一对反义后缀：-ful 表「充满……的」，-less 表「无……的、不能……的」。","explain":"中考常在同一个句子里对比考，如 useful 与 useless、careful 与 careless。看到「老师给的有用建议」选 useful，看到「忘带钥匙」选 careless，关键是先读懂褒贬再判词缀。"},{"level":"重点","text":"-ly 加在形容词后构成副词，用来修饰动词、形容词或整个句子。","explain":"语法填空的第一步是判断所填词修饰谁：修饰动词一定用副词（listen carefully），作表语或定语一定用形容词（be careful, a careful boy）。这是最高频的失分点。"},{"level":"重点","text":"-ment 与 -tion 加在动词后构成名词，表示行为、结果或状态。","explain":"写作与语法填空要求「用所给词的适当形式填空」时必考词性转换，如 develop → development，pollute → pollution，invent → invention。判断办法：空格前有 the、a 或形容词时，填名词。"},{"level":"次重点","text":"-able 表「可……的、能够……的」，构成形容词。","explain":"常考 comfortable（舒适的）、enjoyable（令人愉快的）、valuable（有价值的）、reusable（可重复使用的）。注意 -able 前多接动词，如 enjoy + able、use + able。"},{"level":"次重点","text":"-er 与 -ist 都表示「人」，但分工不同。","explain":"-er 指做某种动作或有某种职业的人，如 teacher、worker、winner；-ist 多指从事某学科、艺术或持某种主张的人，如 scientist、artist、tourist、pianist。问「谁发明了」用 inventor，问「研究科学的人」用 scientist。"},{"level":"了解","text":"词性判断口诀：名词前用形容词，动词后用副词，冠词或介词后用名词。","explain":"这是做词形变化题最快的判断路径：a ______ boy 里填形容词，run ______ 里填副词，the ______ of 里填名词。"}]},{"type":"table","title":"词根词缀","head":["词缀","含义","例词"],"rows":[["-ful","后缀：充满……的，有……性质的（构成形容词）","useful 有用的；careful 仔细的；helpful 有帮助的；thankful 感激的；colourful 色彩丰富的"],["-less","后缀：无……的、不能……的（构成形容词）","useless 无用的；careless 粗心的；hopeless 绝望的；endless 无尽的；homeless 无家可归的"],["-ly","后缀：加在形容词后构成副词，表方式或程度","quickly 迅速地；carefully 仔细地；suddenly 突然地；finally 最后；usually 通常"],["-ment","后缀：加在动词后构成名词，表行为或结果","achievement 成就；development 发展；government 政府；movement 移动；agreement 协议；同意"],["-tion","后缀：动词变名词，表动作、状态或结果","education 教育；invention 发明；information 信息；pollution 污染；attention 注意"],["-able","后缀：可……的、能够……的（构成形容词）","comfortable 舒适的；enjoyable 令人愉快的；valuable 有价值的；possible 可能的；reusable 可重复使用的"],["-er","后缀：做……的人或物","teacher 教师；worker 工人；winner 获胜者；singer 歌手；computer 计算机"],["-ist","后缀：从事某学科、艺术或有某种主张的人","scientist 科学家；artist 艺术家；tourist 游客；pianist 钢琴家；dentist 牙医"]]}],"questions":[{"id":"eng-vocab-2-q1","type":"choice","stem":"Our English teacher gave us some ______ advice on how to remember new words.","answer":"A","explain":"空格修饰名词 advice，要用形容词；语境是老师给的「有用的」建议，故填 useful。B 项 useless 意为「无用的」，与老师认真给建议的正面语境相反；C 项 use 是名词或动词，不能作定语修饰名词；D 项 usefully 是副词，不能修饰名词。","options":["useful","useless","use","usefully"],"difficulty":1,"tags":["后缀","-ful/-less","词性判断"]},{"id":"eng-vocab-2-q2","type":"choice","stem":"He is a ______ boy. He often leaves his keys in the classroom.","answer":"A","explain":"总把钥匙落在教室里说明此人粗心，-less 表「无……的」，careless 意为「粗心的」。B 项 careful 是「细心的」，与具体事实矛盾；C 项 care 是名词或动词，不能作定语；D 项 carelessly 是副词，不能修饰名词 boy。","options":["careless","careful","care","carelessly"],"difficulty":1,"tags":["后缀","-ful/-less","词性判断"]},{"id":"eng-vocab-2-q3","type":"choice","stem":"The ______ of our city has brought many new jobs to young people.","answer":"A","explain":"空格前有 The、后有 of our city，需要名词，develop 加 -ment 构成名词 development（发展）。B 项 develop 是动词，不能作主语；C 项 developing 与 D 项 developed 都是分词形式的形容词，不能作本句主语。","options":["development","develop","developing","developed"],"difficulty":2,"tags":["后缀","-ment","词性转换"]},{"id":"eng-vocab-2-q4","type":"choice","stem":"Yuan Longping is a great ______ who helped millions of people.","answer":"A","explain":"空格前有 a great，后面用 who 引导定语从句指人，需要表示「人」的名词，science 加 -ist 构成 scientist。B 项 science 是学科名称，不能指人；C 项 scientific 是形容词；D 项 scientifically 是副词，都不能作指人的名词。","options":["scientist","science","scientific","scientifically"],"difficulty":1,"tags":["后缀","-ist","词性转换"]},{"id":"eng-vocab-2-q5","type":"choice","stem":"This glass bottle is ______, so please do not throw it away.","answer":"A","explain":"be 动词后作表语要用形容词，reuse 加 -able 构成 reusable（可重复使用的），与「别扔掉」的语境一致。B 项 reuse 是动词，不能作表语；C 项 reused 是过去分词，本句没有被动含义；D 项 reusing 是现在分词，同样不合语法。","options":["reusable","reuse","reused","reusing"],"difficulty":2,"tags":["后缀","-able","环保语境"]},{"id":"eng-vocab-2-q6","type":"choice","stem":"Please listen to the teacher ______ in class, and you will learn much more.","answer":"A","explain":"空格修饰动词 listen，要用副词，形容词 careful 加 -ly 构成 carefully。B 项 careful 是形容词，不能修饰动词；C 项 carefulness 是名词；D 项 careless 是形容词且意思相反，都不能修饰 listen。","options":["carefully","careful","carefulness","careless"],"difficulty":1,"tags":["后缀","-ly","副词修饰动词"]}]},{"id":"eng-vocab-3","title":"高频词根串记：spect / port / dict / ject / struct / vis / cred / duc","subtitle":"词根词缀 · Common roots: spect, port, dict, ject, struct, vis, cred, duc","grade":"all","tags":["词根词缀"],"blocks":[{"type":"note","title":"学习要点","text":"用八个常用词根把分散的单词串成家族，阅读中遇到生词也能按「词根含义 + 前后缀」推出大意。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"spect 与 vis 都表「看」，但常考词不同。","explain":"spect 家族：inspect（检查）、expect（期待）、respect（尊重）、suspect（怀疑）；vis 家族：visible（可见的）、vision（视力）、visit（参观）、television（电视）。阅读词义猜测题看到 spect 就先想「看」，再按前后缀定方向。"},{"level":"重点","text":"port 表「搬运、携带」，与方向前缀组合成一组高频词。","explain":"ex-（向外）+ port = export（出口），im-（向内）+ port = import（进口），trans-（跨越）+ port = transport（运输），sup-（从下面托住）+ port = support（支持）。写作中谈经济、交通话题时这四个词很有用。"},{"level":"重点","text":"dict 表「说」，靠「说」这条线索串起四个词。","explain":"dictionary（词典）、dictation（听写）、predict（预言、预测）、dictate（口述；支配）。听力与写作里「听写」是 dictation，别写成 dictation 以外的生造词。"},{"level":"次重点","text":"ject 表「投、掷」，pro- 向前，re- 往回。","explain":"pro- + ject = project（向前投出的计划，即项目、工程），re- + ject = reject（往回扔，即拒绝），sub- + ject = subject（放在下面的东西，即科目、主题），ob- + ject = object（摆在眼前的东西，即物体、宾语）。"},{"level":"次重点","text":"struct 表「建造」，构造、指导、结构都由它来。","explain":"construct（建造）、structure（结构）、instruction（指导；常用复数表示说明书）。阅读理解中 read the instructions 意为「看说明书」，是应用文高频搭配。"},{"level":"了解","text":"cred 表「相信」，duc 表「引导」。","explain":"初中阶段 cred 主要靠 incredible（难以置信的）一词带出；duc/duct 家族有 produce（生产）、introduce（介绍）、reduce（减少）、conduct（实施；举止）、education（教育）。"}]},{"type":"table","title":"词根词缀","head":["词缀","含义","例词"],"rows":[["spect","词根：看","inspect 检查，仔细查看；expect 期待，预料；respect 尊重；suspect 怀疑；spectator 观众"],["port","词根：搬运，携带","transport 运输；import 进口；export 出口；support 支持；portable 便携的"],["dict","词根：说","dictionary 词典；predict 预测；dictation 听写；dictate 口述；支配；contradict 反驳；与……矛盾"],["ject","词根：投，掷","project 项目，工程；reject 拒绝；subject 科目；主题；object 物体；反对；inject 注射"],["struct","词根：建造","structure 结构；construct 建造；instruction 指导；说明书；construction 建设，施工；instruct 指示，教导"],["vis / vid","词根：看","visible 看得见的；vision 视力；视野；visit 参观，拜访；television 电视；provide 提供"],["cred","词根：相信","incredible 难以置信的；incredibly 难以置信地；credit 信用；学分；credible 可信的"],["duc / duct","词根：引导","produce 生产；introduce 介绍；引进；reduce 减少；conduct 实施；举止；education 教育"]]}],"questions":[{"id":"eng-vocab-3-q1","type":"choice","stem":"\"Export\" is made up of \"ex-\" (out) and \"port\" (to carry). So \"export\" means ______.","answer":"A","explain":"port 表「搬运、携带」，ex- 表「向外」，合起来即「把货物运出去」，也就是出口。B 项是 import（进口），对应前缀 im-「向内」；C 项「修理」与词根含义无关；D 项「存放」也与 port 无关。","options":["to sell and carry goods out of a country","to buy and carry goods into a country","to repair goods for other countries","to keep goods in a safe place"],"difficulty":2,"tags":["词根","port","词义猜测"]},{"id":"eng-vocab-3-q2","type":"choice","stem":"The workers were asked to ______ the bridge carefully before it was used again.","answer":"A","explain":"spect 表「看」，in- 表「向内、仔细」，inspect 意为「检查、仔细查看」，与「重新使用前仔细查看桥梁」相符。B 项 expect 是「期待」，没有查看实物之意；C 项 respect 是「尊重」，多用于人对人的态度；D 项 suspect 是「怀疑」，与「认真检查」的正面语境不符。","options":["inspect","expect","respect","suspect"],"difficulty":2,"tags":["词根","spect","语境选词"]},{"id":"eng-vocab-3-q3","type":"choice","stem":"Please read the ______ carefully before you use the new machine.","answer":"A","explain":"struct 表「建造」，instruct 引申为「指导」，其名词 instruction 常用复数 instructions 表示「说明书、操作说明」。B 项 invention 是「发明」；C 项 introduction 是「介绍」；D 项 intention 是「意图」，都不能表示使用前的操作说明。","options":["instructions","inventions","introductions","intentions"],"difficulty":3,"tags":["词根","struct","应用文搭配"]},{"id":"eng-vocab-3-q4","type":"choice","stem":"The word \"incredible\" comes from the root \"cred\" (to believe). It means ______.","answer":"A","explain":"cred 表「相信」，in- 表否定，-ible 表「可……的」，合起来是「不可相信的」，即「难以置信的」。B 项 remember 对应词根 memor；C 项 see 对应词根 vis 或 spect；D 项 help 与词根无关。","options":["hard to believe","easy to remember","impossible to see","ready to help"],"difficulty":2,"tags":["词根","cred","词义猜测"]},{"id":"eng-vocab-3-q5","type":"choice","stem":"In \"a science project\", the word \"project\" most probably means ______.","answer":"A","explain":"ject 表「投、掷」，pro- 表「向前」，project 本义是「向前投出的东西」，引申为「计划、项目、作业课题」，与 science project（科学课题）相符。B 项是 transport；C 项是 inspector；D 项是 museum，都与该词在句中的意思不符。","options":["a plan or a piece of work that students carry out","a machine that carries heavy goods","a person who checks other people work","a place where old things are kept"],"difficulty":3,"tags":["词根","ject","词义猜测"]},{"id":"eng-vocab-3-q6","type":"choice","stem":"Which of the following words has the same root as \"introduce\"?","answer":"A","explain":"duc 表「引导」，introduce 是 intro-（向内）+ duc + -e，produce 是 pro-（向前）+ duc + -e，两者同为 duc 词根。B 项 protect 的词根是 tect（覆盖），与 pro- 拼写相似但词根不同；C 项 provide 的词根是 vid（看）；D 项 prepare 的词根是 par（准备）。","options":["produce","protect","provide","prepare"],"difficulty":3,"tags":["词根","duc","同根词辨析"]}]},{"id":"eng-vocab-4","title":"说与看：say / speak / tell / talk 与 look / see / watch / read","subtitle":"同义辨析 · Verbs of speaking and seeing: say, speak, tell, talk / look, see, watch, read","grade":"all","tags":["同义辨析"],"blocks":[{"type":"note","title":"学习要点","text":"八个「说」「看」动词的中文意思几乎一样，考试只考句型搭配，分清「要不要接人、接什么宾语」就不会错。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"say 与 tell 的分水岭是「后面接人还是不接人」。","explain":"tell 后面必须接人（tell sb sth, tell sb to do sth）；say 后面接说的内容，若要点明对象要用 say sth to sb。单项选择里出现 tell 后面直接跟 that 从句而没有人的情况，就是错的。"},{"level":"重点","text":"speak 强调说话的动作与语言能力，talk 强调双向交谈。","explain":"speak 后接语言（speak English）或接 to sb；talk 是不及物动词，与 to / with / about 连用（talk with sb about sth）。看到空格后直接跟 English，选 speak。"},{"level":"重点","text":"look 是动作，see 是结果。","explain":"look 是不及物动词，接宾语必须加 at（look at the blackboard）；see 是及物动词，表示「看见了」，不能说 look the blackboard。这是单项选择题最常见的搭配错误。"},{"level":"次重点","text":"watch 看的是「会动的画面」，read 看的是「文字」。","explain":"看电视、比赛、表演用 watch；看书、报、邮件用 read。但「看电影」既可从观众角度说 see a film，也可从观看过程说 watch a film，句中若有 on TV、on the playground 等提示，优先选 watch。"},{"level":"次重点","text":"listen 与 hear 也是「动作与结果」的分工。","explain":"listen 是有意识地听，接宾语要加 to（listen to the teacher）；hear 是声音传进耳朵的结果，常与 can 连用（I can hear a bird singing）。"},{"level":"了解","text":"判断口诀：先看空格后有没有宾语、宾语是人还是内容，再看句意是动作还是结果。","explain":"这一条适用于所有「同义动词」题：句型搭配比中文意思更能决定答案。"}]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["say","speak","say 后面接「说的内容」，结构是 say sth (to sb)，不能直接接人；speak 强调说话的动作或语言能力，结构是 speak to sb 或 speak + 语言。一个记内容的词，一个记动作与语言的词。","She said goodbye to me with a smile.\nCan you speak Japanese?"],["tell","talk","tell 是及物动词，必须接人，结构为 tell sb sth、tell sb to do sth；talk 主要作不及物动词，与 to / with / about 连用表示「与某人谈某事」，后面不能直接接人。","My mother told me to come back before six.\nThe two boys talked about the football match for an hour."],["look","see","look 强调「看」的动作，是不及物动词，接宾语时必须加 at；see 强调「看见」的结果，是及物动词，可直接接宾语。句意若在描述有意地看，用 look at；若在描述看到什么，用 see。","Look at the blackboard, please.\nI saw a rainbow in the sky after the rain."],["watch","read","watch 用于有画面、会动的内容，如电视、比赛、表演；read 用于文字材料，如书、报、杂志、邮件。判断依据是宾语本身是画面还是文字。","We watched a football match on TV last night.\nMy father reads the newspaper every morning."],["listen","hear","listen 表示有意识地听，是不及物动词，接宾语要用 listen to；hear 表示声音进入耳朵的结果，是及物动词，常与 can 连用，表示「听得见」。","Please listen to the teacher carefully.\nI can hear a bird singing outside the window."]]}],"questions":[{"id":"eng-vocab-4-q1","type":"choice","stem":"Please ______ me the truth. I will not be angry with you.","answer":"A","explain":"空格后直接跟人（me），再跟内容（the truth），只有 tell 能接双宾语 tell sb sth。B 项 say 只能说 say sth to sb；C 项 speak 后接语言或 to sb；D 项 talk 是不及物动词，都要借助介词，不能直接接人。","options":["tell","say","speak","talk"],"difficulty":1,"tags":["同义辨析","say/tell","句型搭配"]},{"id":"eng-vocab-4-q2","type":"choice","stem":"My father can ______ English and French, and he often uses them at work.","answer":"A","explain":"空格后是语言名称，表示「会说某种语言」用 speak。B 项 say 后面要接说的内容；C 项 tell 后面要接人；D 项 talk 要借助 to / with / about 才能带宾语，都不能直接接语言名称。","options":["speak","say","tell","talk"],"difficulty":1,"tags":["同义辨析","speak","搭配"]},{"id":"eng-vocab-4-q3","type":"choice","stem":"I ______ my old friend on the street yesterday, and we talked for a while.","answer":"A","explain":"在街上偶然遇到旧友，强调「看见」的结果，用及物动词 see，过去式为 saw。B 项 watch 指有意识地持续观看动态画面；C 项 look 是不及物动词，后面必须加 at 才能接宾语；D 项 read 用于阅读文字。","options":["saw","watched","looked","read"],"difficulty":1,"tags":["同义辨析","see/look","动词时态"]},{"id":"eng-vocab-4-q4","type":"choice","stem":"We are going to ______ the basketball match on TV this evening.","answer":"A","explain":"句中 on TV 表明是持续观看电视转播的比赛，用 watch。B 项 see 侧重「看见」的结果，不用于「持续观看电视节目」；C 项 look 后必须加 at；D 项 read 只能用于文字，不能用于球赛。","options":["watch","see","look","read"],"difficulty":2,"tags":["同义辨析","watch","语境选词"]},{"id":"eng-vocab-4-q5","type":"choice","stem":"My mother often ______ me to be careful when I cross the road.","answer":"A","explain":"tell sb to do sth 是固定结构，主语 My mother 是第三人称单数，故用 tells。B 项 say 没有 say sb to do sth 的说法；C 项 speak 不接不定式作宾补；D 项 talk 不能直接接人，都不能构成该结构。","options":["tells","says","speaks","talks"],"difficulty":2,"tags":["同义辨析","tell","固定结构"]},{"id":"eng-vocab-4-q6","type":"choice","stem":"I like to ______ English newspapers after class to improve my English.","answer":"A","explain":"报纸是文字材料，用 read。B 项 see 强调看见的结果；C 项 look 是不及物动词，要加 at 才能接宾语；D 项 watch 用于电视、比赛一类动态画面，都不能与 newspapers 搭配。","options":["read","see","look","watch"],"difficulty":1,"tags":["同义辨析","read","搭配"]}]},{"id":"eng-vocab-5","title":"花费与借还、带去带来、参加：spend / cost / take / pay，borrow / lend，join / join in / take part in","subtitle":"同义辨析 · Confusable verb groups: spend, cost, take, pay / borrow, lend / bring, take, fetch / join, take part in","grade":"all","tags":["同义辨析"],"blocks":[{"type":"note","title":"学习要点","text":"四组最容易混淆的动词，靠「主语是谁、方向朝哪边、后面接什么」三条线索定答案，是听力和单选的高频失分点。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「花费」看主语：人做主语用 spend 或 pay，物做主语用 cost，形式主语 it 用 take。","explain":"常考结构：sb spends time/money on sth 或 (in) doing sth；sth costs sb money；sb pays money for sth；It takes sb time to do sth。做题先看主语是人还是物，基本一步就能定答案。"},{"level":"重点","text":"borrow 是「借入」，lend 是「借出」，方向相反。","explain":"borrow sth from sb（从某人那里借来），lend sb sth 或 lend sth to sb（把东西借给别人）。判断办法：动作的受益者是自己还是别人，自己得到用 borrow，给别人用 lend。"},{"level":"重点","text":"join 接组织，join in 接正在进行的活动，take part in 接正式活动。","explain":"join the army / a club 强调加入团体并成为成员；join in the game 强调加入别人正在做的事情；take part in the sports meeting / a competition 强调参加活动并发挥作用，是写作中的正式表达。"},{"level":"次重点","text":"bring 是「带来」，take 是「带走」，方向由说话人位置决定。","explain":"说话人在学校说「明天把作业带到这儿来」用 bring；说话人在学校说「把书带回家」用 take。中考常通过 Here is my home 或 the teacher said 这类语境提示说话人位置。"},{"level":"次重点","text":"fetch 是「去取来」，含一去一回，等于 go and bring back。","explain":"典型语境：妈妈让你去房间把书包拿来。若句中强调「去某个地方然后拿回来」，用 fetch，也可用 go and get。"},{"level":"了解","text":"这一组词在听力第一节「听选」中出现频率很高，关键听清方向词 from、to、for、with。","explain":"听力中不必逐词听懂全句，抓住介词就能判断方向：borrow ... from 是借入，lend ... to 是借出，pay ... for 是付钱买。"}]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["spend","cost","spend 的主语必须是人，结构为 sb spends time/money on sth 或 (in) doing sth；cost 的主语是物或事，结构为 sth costs sb money，没有被动语态。主语类型是唯一的判断标准。","I spent two hours finishing my homework yesterday.\nThe new bike cost him eight hundred yuan."],["take","pay","take 用于「花费时间」，只接时间，常用形式主语结构 It takes sb some time to do sth；pay 用于「花钱」，主语是人，结构为 sb pays money for sth。一个管时间，一个管钱。","It takes me half an hour to get to school by bus.\nShe paid fifty yuan for the English dictionary."],["borrow","lend","borrow 表示「借入」，东西从别人手里到自己手里，结构是 borrow sth from sb；lend 表示「借出」，东西从自己手里给别人，结构是 lend sb sth 或 lend sth to sb。方向不同，介词也不同。","May I borrow your ruler? I left mine at home.\nCould you lend me your dictionary? I will return it tomorrow."],["bring","take","bring 表示朝说话人所在的地方「带来」（由远及近）；take 表示从说话人所在的地方「带走」（由近及远）。判断依据是说话人站在哪里，而不是东西从哪来。","Remember to bring your homework here tomorrow.\nPlease take these books home after school."],["take","fetch","take 是「拿走」，只表示单方向；fetch 是「去取来」，包含去和回两个动作，相当于 go and bring back。句中若有「先去某处，再拿回来」的意思，用 fetch。","Take your umbrella with you. It may rain.\nCould you fetch my bag from the classroom?"],["join","join in","join 后面接组织、团体或人群，表示加入并成为其中一员，如 join the army、join a club；join in 后面接正在进行的活动，表示加入进来一起做，如 join in the game、join in the singing。","Li Ming joined the army last year and now he is a soldier.\nAll the students joined in the singing at the party."],["join in","take part in","join in 多指临时加入别人正在进行的活动，比较随意；take part in 指参加某项正式活动并在其中承担任务、发挥作用，常与 sports meeting、competition、activity 等搭配。","Would you like to join in our game?\nMore than two hundred students took part in the school sports meeting."]]}],"questions":[{"id":"eng-vocab-5-q1","type":"choice","stem":"I ______ two hours doing my homework yesterday evening.","answer":"A","explain":"主语是 I（人），后面接 doing，符合 spend time (in) doing sth 的结构，且叙述过去的事，用过去式 spent。B 项 cost 的主语必须是物，结构为 sth costs sb money；C 项 take 用 It takes sb time to do sth，不接 doing；D 项 pay 的结构是 pay money for sth。","options":["spent","cost","took","paid"],"difficulty":2,"tags":["同义辨析","spend","句型结构"]},{"id":"eng-vocab-5-q2","type":"choice","stem":"The new bike ______ him eight hundred yuan, so he has little pocket money left.","answer":"A","explain":"主语是 The new bike（物），后面接人再接钱，符合 sth costs sb money 的结构。B 项 spend 的主语必须是人；C 项 take 只用于花费时间；D 项 pay 的主语是人，结构是 pay money for sth，方向正好相反。","options":["cost","spent","took","paid"],"difficulty":2,"tags":["同义辨析","cost","主语判断"]},{"id":"eng-vocab-5-q3","type":"choice","stem":"May I ______ your pen? I left mine in the classroom.","answer":"A","explain":"说话人想从对方那里把笔借来，方向是「借入」，用 borrow sth from sb。B 项 lend 是「借出」，是 lend sb sth，方向相反；C 项 bring 是「带来」；D 项 take 是「带走」，都与「借」的意思无关。","options":["borrow","lend","bring","take"],"difficulty":1,"tags":["同义辨析","borrow/lend","方向"]},{"id":"eng-vocab-5-q4","type":"choice","stem":"Could you ______ me your dictionary? I will return it tomorrow.","answer":"A","explain":"说话人请求对方把词典借给自己，方向是「借出」，用 lend sb sth。B 项 borrow 是「借入」，若用它则主语应是借东西的人而不是物主；C 项 fetch 是「去取来」；D 项 carry 只表示「搬运」，都没有借出的意思。","options":["lend","borrow","fetch","carry"],"difficulty":2,"tags":["同义辨析","lend","双宾语"]},{"id":"eng-vocab-5-q5","type":"choice","stem":"The teacher said to the class, \"Remember to ______ your homework here tomorrow.\"","answer":"A","explain":"老师在学校说话，要求学生把作业带到「这里」（说话人所在的地方），由远及近，用 bring。B 项 take 是由近及远地「带走」，与 here 矛盾；C 项 fetch 是「去取来」，含一去一回；D 项 carry 只表示搬运，不体现方向。","options":["bring","take","fetch","carry"],"difficulty":2,"tags":["同义辨析","bring/take","方向"]},{"id":"eng-vocab-5-q6","type":"choice","stem":"Li Ming ______ the army last year, and now he is a soldier.","answer":"A","explain":"the army 是组织、团体，表示加入并成为其中一员，用 join，且整句是过去的事，用过去式 joined。B 项 join in 后接正在进行的活动；C 项 take part in 后接比赛、活动一类名词，不与 the army 搭配；D 项 take 与句意无关。","options":["joined","joined in","took part in","took"],"difficulty":1,"tags":["同义辨析","join","搭配"]}]},{"id":"eng-vocab-6","title":"形容词与副词：interesting / interested，hard / hardly，too / also / either，much / very","subtitle":"同义辨析 · Adjectives and adverbs: interesting vs interested, hard vs hardly, too/also/either, much vs very","grade":"all","tags":["同义辨析"],"blocks":[{"type":"note","title":"学习要点","text":"四组「看着像、用法完全不同」的形容词与副词，用「修饰谁、放哪里」两条规则一次分清。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"-ing 形容词描述事物「令人……」，-ed 形容词描述人「感到……」。","explain":"主语是物（a story, the film）用 interesting；主语是人（I, she）用 interested。中考选择题几乎每年都在这组词上设分，判断办法就是看主语是不是人。"},{"level":"重点","text":"hard 与 hardly 意思完全不同：hard 是「努力地、猛烈地」，hardly 是「几乎不」。","explain":"hardly 本身含否定意义，不能再与 not 连用，也不能与否定句叠加。看到 hardly 就当作否定词理解：I can hardly hear you. 意为「我几乎听不见你说话」。"},{"level":"重点","text":"too 放肯定句句末，also 放肯定句句中，either 放否定句句末。","explain":"also 的位置固定在 be 动词之后、实义动词之前；too 与 either 都在句末，too 用于肯定句，either 用于否定句。选项中若把 also 放在句末，一定是错的。"},{"level":"次重点","text":"very 修饰原级，much 修饰比较级。","explain":"very interesting 正确，very more interesting 错误；much more interesting 正确。修饰比较级的还有 a lot、even、far、still，考试中这几组常一起作为干扰项出现。"},{"level":"次重点","text":"too much 后接不可数名词或动词，much too 后接形容词或副词。","explain":"too much noise（太多噪音）、talk too much（说得太多）；much too difficult（实在太难）。记忆办法：much too 的 much 修饰 too，说的是程度；too much 的 much 是中心词，说的是数量。"},{"level":"了解","text":"good 是形容词，well 是副词，但 well 作形容词时表示「身体健康的」。","explain":"He is a good player.（good 作定语）He plays well.（well 修饰动词）He is well today.（well 表身体健康）三种情况要能区分。"}]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["interesting","interested","interesting 描述事物本身「令人感兴趣的」，主语常是物；interested 描述人的感受「对……感兴趣的」，主语必须是人，且常与 in 连用（be interested in）。","The story is interesting and I want to read it again.\nI am interested in Chinese history."],["hard","hardly","hard 作副词是「努力地、猛烈地」，不含否定；hardly 是「几乎不」，本身是否定词，不能与句中的否定叠加使用。一个表示程度高，一个表示程度几乎为零。","She works hard and always gets good grades.\nIt was so noisy that I could hardly hear you."],["too","also","too 一般放在肯定句句末，前面常加逗号；also 放在句中，位于 be 动词之后、实义动词之前，不放在句末。位置是这两个词最重要的区别。","I like swimming, and my sister likes it, too.\nMy sister also likes swimming, and she goes to the pool every week."],["also","either","also 用于肯定句的句中；either 用于否定句的句末，表示「也（不）」。判断办法：句子有 not 时，句末只能用 either。","Tom is good at maths, and he is also good at English.\nTom did not come to school yesterday, and his brother did not come, either."],["much","very","much 用来修饰形容词或副词的比较级（much better, much more interesting），也可修饰动词；very 只能修饰形容词或副词的原级（very good），不能修饰比较级。","This book is much more interesting than that one.\nThis book is very interesting, so I read it twice."],["too much","much too","too much 的中心词是 much，表示「数量太多」，后接不可数名词或修饰动词；much too 的中心词是 too，表示「程度实在太」，后接形容词或副词。","There is too much noise in the street at night.\nThe question is much too difficult for me."],["good","well","good 是形容词，作定语或表语，修饰名词；well 是副词，修饰动词；well 也可作形容词，但只表示「身体健康的」，如 I am not well today，不用来修饰一般名词。","Li Hua is a good basketball player and he is popular in our class.\nLi Hua plays basketball well, so he was chosen for the school team."]]}],"questions":[{"id":"eng-vocab-6-q1","type":"choice","stem":"The story is so ______ that I want to read it a third time.","answer":"A","explain":"主语 The story 是物，说明它本身「令人感兴趣」，要用 -ing 形容词 interesting。B 项 interested 描述人的感受，主语应是人；C 项 interest 是名词或动词，不能作表语；D 项 interestingly 是副词，也不能作表语。","options":["interesting","interested","interest","interestingly"],"difficulty":1,"tags":["同义辨析","-ing/-ed 形容词","词性判断"]},{"id":"eng-vocab-6-q2","type":"choice","stem":"My brother is ______ in playing computer games, but he is trying to change.","answer":"A","explain":"主语 My brother 是人，表示「对……感兴趣」用 be interested in。B 项 interesting 形容事物本身有趣；C 项 interest 是名词或动词；D 项 interestingly 是副词，都不能与 is 和 in 构成该结构。","options":["interested","interesting","interest","interestingly"],"difficulty":1,"tags":["同义辨析","interested","固定搭配"]},{"id":"eng-vocab-6-q3","type":"choice","stem":"The rain was so heavy that we could ______ go out last night.","answer":"A","explain":"前半句说雨很大，后半句应是「我们几乎出不去」，hardly 表示否定「几乎不」。B 项 hard 作副词是「努力地、猛烈地」，写「我们可以努力出去」不合逻辑；C 项 harder 与 D 项 hardest 是比较级和最高级，本句没有比较对象。","options":["hardly","hard","harder","hardest"],"difficulty":2,"tags":["同义辨析","hard/hardly","语境选词"]},{"id":"eng-vocab-6-q4","type":"choice","stem":"I like playing basketball, and my cousin likes it, ______.","answer":"A","explain":"前面是肯定句，句末表示「也」，用 too，前面常加逗号。B 项 also 只能放在句中，不能放在句末；C 项 either 用于否定句句末；D 项 neither 表示「两者都不」，与肯定语境不符。","options":["too","also","either","neither"],"difficulty":2,"tags":["同义辨析","too/also/either","位置"]},{"id":"eng-vocab-6-q5","type":"choice","stem":"Lily is good at maths. She is ______ good at English.","answer":"A","explain":"also 用在句中，位于 be 动词之后，表示「也」。B 项 too 一般放在句末；C 项 either 用于否定句；D 项 neither 是「两者都不」，都不能放在本句这个位置。","options":["also","too","either","neither"],"difficulty":2,"tags":["同义辨析","also","位置"]},{"id":"eng-vocab-6-q6","type":"choice","stem":"This box is ______ heavier than that one, so I cannot carry it alone.","answer":"A","explain":"heavier 是比较级，修饰比较级要用 much（也可用 a lot、even、far、still）。B 项 very、C 项 too 与 D 项 so 都只能修饰形容词或副词的原级，不能修饰比较级，是本题的典型干扰项。","options":["much","very","too","so"],"difficulty":2,"tags":["同义辨析","much/very","比较级"]}]},{"id":"eng-vocab-7","title":"动词短语：take / make / get / turn / put / come / go + 介词或副词","subtitle":"高频搭配 · Phrasal verbs with take, make, get, turn, put, come and go","grade":"all","tags":["高频搭配"],"blocks":[{"type":"note","title":"学习要点","text":"把七个高频动词的搭配按「动词家族」串起来记，并掌握动副短语中代词必须放中间这条铁律。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「动词 + 副词」型短语接代词宾语时，代词必须放在中间。","explain":"turn it off、put them away、take it off 正确；turn off it、put away them 错误。中考选择题与短文改错专门在这里设坑。"},{"level":"重点","text":"take place 是「发生、举行」，不及物，没有被动语态。","explain":"主语常是 meeting、sports meeting、accident，句中不会出现 be taken place，也不说 take place the meeting。看到 these things 作主语用主动形式。"},{"level":"重点","text":"turn 家族按「方向」理解：turn on/off 是开关，turn up/down 是音量大小。","explain":"turn on 打开，turn off 关闭，turn up 调大，turn down 调小或拒绝，turn into 变成。听力中听到 The baby is sleeping 就要想到 turn down。"},{"level":"次重点","text":"put 家族的四个高频义：put on 穿上、上演，put off 推迟，put up 举起、张贴、搭建，put away 收好。","explain":"搭配对象不同：put on 接衣帽或节目，put off 接会议、比赛、计划，put up 接手、海报、帐篷，put away 接物品。按宾语类型记比按中文记更牢。"},{"level":"次重点","text":"come 家族：come true 实现，come up with 想出，come from 来自。","explain":"come true 的主语通常是 dream、wish、plan，不能用于人；come up with 后面接 idea、plan、answer；come from 相当于 be from。"},{"level":"了解","text":"get 家族：get on/along with 与……相处，get ready for 为……做准备，get used to 习惯于。","explain":"get used to 中的 to 是介词，后面接名词或 doing，如 get used to getting up early，这是初三的高频考点。"}]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["take off","脱下；起飞","接代词放中间：take it off。"],["take part in","参加（活动）","后接活动名词，强调参加并出力。"],["take care of","照顾；照料","相当于 look after。"],["take away","拿走，带走","接代词放中间：take them away。"],["take place","发生，举行","不及物，无被动语态。"],["take up","开始从事；占用（时间、空间）","take up a hobby 开始一项爱好。"],["make friends with","与……交朋友","friends 必须用复数。"],["make sure","确保，查明","后接 of sth 或 that 从句。"],["make a decision","做决定","也可说 make up one's mind。"],["make up","编造；组成；化妆","be made up of 表示「由……组成」。"],["make progress","取得进步","progress 不可数，不加 s。"],["get on / get along with","与……相处","get on well with sb 表示相处融洽。"],["get up","起床","过去式 got up。"],["get ready for","为……做准备","后接名词或动名词。"],["get lost","迷路","get + 过去分词表示状态变化。"],["get used to","习惯于","to 是介词，后接名词或 doing。"],["get together","聚会，相聚","多用于节日与家庭话题。"],["turn on","打开（电器）","接代词放中间：turn it on。"],["turn off","关闭（电器）","离开教室要 turn off the lights。"],["turn up","调大（音量）；出现","与 turn down 互为反义。"],["turn down","调小（音量）；拒绝","拒绝时常接 an invitation、a plan。"],["turn into","变成","也可说 change into。"],["put on","穿上；上演","与 take off 互为反义。"],["put off","推迟","后接会议、比赛、计划等。"],["put away","把……收起来","接代词放中间：put them away。"],["put up","举起；张贴；搭建","put up a poster 张贴海报。"],["put out","扑灭（火）","宾语常是 fire、candle。"],["come true","实现","主语常是 dream、wish、plan。"],["come up with","想出（主意、办法）","后接 idea、plan、answer。"],["come from","来自","相当于 be from。"],["come on","加油；快点","口语中常用于鼓励。"],["go on","继续","go on doing 与 go on to do 意思不同。"],["go over","复习；检查","考试前 go over the notes。"],["go out","出去；（灯）熄灭","主语是灯时表示熄灭。"],["go through","经历；仔细检查","后接 difficulties、papers 等。"]]},{"type":"list","title":"应试策略","items":["做完形填空与选择题时，先看空格后的宾语类型：出现 it 或 them 时，把代词放到动词和副词中间（put it away），这是最常见的干扰项设置方式。","take place、come true 这类不及物短语没有被动语态，看到 be taken place、be come true 一律排除。","记忆一词多义的短语按搭配对象归类：put on 搭配衣帽或节目，put off 搭配会议、比赛、计划，比死记中文解释更有效。"]}],"questions":[{"id":"eng-vocab-7-q1","type":"choice","stem":"It is cold outside. Do not ______ your coat.","answer":"A","explain":"前面说外面冷，后面应是提醒「别脱外套」，take off 意为「脱下」（也指飞机起飞）。B 项 put on 是「穿上」，与天冷时别脱衣的提醒正相反；C 项 put off 是「推迟」；D 项 turn off 是「关闭电器」，都与 coat 搭配不当。","options":["take off","put on","put off","turn off"],"difficulty":1,"tags":["高频搭配","take off","语境选词"]},{"id":"eng-vocab-7-q2","type":"choice","stem":"Our school sports meeting will ______ next Friday if it does not rain.","answer":"A","explain":"take place 意为「举行、发生」，是不及物短语，主语是运动会，正好符合。B 项 take part 必须加 in 才能接宾语，不能单独使用；C 项 take care 是「当心」；D 项 take away 是「拿走」，都与运动会举行的意思无关。","options":["take place","take part","take care","take away"],"difficulty":2,"tags":["高频搭配","take place","不及物短语"]},{"id":"eng-vocab-7-q3","type":"choice","stem":"Can you ______ a good idea to help the old man in our neighbourhood?","answer":"A","explain":"come up with 表示「想出（主意、办法）」，后面接 idea 正合适。B 项 come on 是「加油、快点」；C 项 come true 是「实现」，主语常是梦想或愿望，不能接 idea 作宾语；D 项 come from 是「来自」，与句意不符。","options":["come up with","come on","come true","come from"],"difficulty":2,"tags":["高频搭配","come up with","搭配"]},{"id":"eng-vocab-7-q4","type":"choice","stem":"The baby is sleeping. Please ______ the TV a little.","answer":"A","explain":"宝宝在睡觉，应把电视音量「调小」，用 turn down。B 项 turn up 是「调大」，方向相反；C 项 turn on 是「打开」，电视本来就在开着；D 项 turn over 是「翻转」，与音量无关。","options":["turn down","turn up","turn on","turn over"],"difficulty":1,"tags":["高频搭配","turn 家族","语境选词"]},{"id":"eng-vocab-7-q5","type":"choice","stem":"The meeting was ______ because of the heavy rain yesterday.","answer":"A","explain":"会议因大雨「推迟」，用 put off。B 项 put on 是「穿上、上演」；C 项 put up 是「举起、张贴、搭建」；D 项 put away 是「收起来」，都不能与 meeting 搭配表示推迟。","options":["put off","put on","put up","put away"],"difficulty":2,"tags":["高频搭配","put off","搭配对象"]},{"id":"eng-vocab-7-q6","type":"choice","stem":"Your books are all over the desk. Please ______ before you leave.","answer":"A","explain":"put away 是「动词 + 副词」型短语，代词宾语必须放在动词和副词中间，所以是 put them away，不能说 put away them。B 项语序错误；C 项 put on 意为「穿上」，与书本不符；D 项既语序错误又搭配不当。","options":["put them away","put away them","put them on","put on them"],"difficulty":3,"tags":["高频搭配","代词位置","语序"]}]},{"id":"eng-vocab-8","title":"拼写易错词与形近词：quite / quiet，through / thought，weather / whether，advice / advise，affect / effect","subtitle":"拼写易错 · Commonly misspelled and look-alike words","grade":"all","tags":["拼写易错"],"blocks":[{"type":"note","title":"学习要点","text":"把「只差一两个字母、意思完全不同」的高频词成对整理，专治拼写填空、完成句子与短文改错失分。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"quite 与 quiet 字母相同、顺序不同，词性与意思完全不同。","explain":"quite 是副词「相当、十分」，修饰形容词（quite good）；quiet 是形容词「安静的」（keep quiet）。判断时先看空格修饰谁：修饰形容词用 quite，作表语或定语用 quiet。"},{"level":"重点","text":"advice 是名词，advise 是动词。","explain":"advice 不可数，没有复数形式，与 some、much、a piece of 连用；advise 是动词，常用 advise sb to do sth。这是「用所给词的适当形式填空」最爱考的一对。"},{"level":"重点","text":"affect 是动词「影响」，effect 是名词「影响、效果」。","explain":"句中有 have 且空格前有 a / an / the 时用 effect（have an effect on）；句子缺谓语动词时用 affect。两个词读音相近，写作文时最容易写错。"},{"level":"次重点","text":"through、thought、though 三个词只差尾字母。","explain":"through 是介词「穿过」；thought 是 think 的过去式，也可作名词「想法」；though 是连词「虽然」，口语中还可放句末表示「不过」。按词性判断：接名词用 through，作谓语用 thought。"},{"level":"次重点","text":"weather 与 whether 读音相近，一个是名词一个是连词。","explain":"weather 是「天气」（不可数）；whether 是「是否」，引导宾语从句，常与 or not 连用。句中需要「是否」的意思时必须用 whether，不能用 weather。"},{"level":"了解","text":"accept 与 except、abroad 与 aboard、lose 与 loose 也是常见形近词。","explain":"accept 是动词「接受」，except 是介词「除……之外」；abroad 是副词「在国外」，aboard 是「在船（飞机）上」；lose 是动词「丢失」，loose 是形容词「松的」。"}]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["quite","quiet","quite 是副词，意为「相当、十分」，用于修饰形容词或副词；quiet 是形容词，意为「安静的」，可作定语或表语。两词由同样的字母组成，只是字母 e 与 t 的位置不同，看词性最快。","The film is quite interesting, so I watched it twice.\nPlease keep quiet in the reading room."],["through","thought","through 是介词或副词，表示「穿过、通过」，指从某物内部穿过，后面接名词；thought 是 think 的过去式和过去分词，也可作名词表示「想法」。一个不能作谓语，一个常作谓语或主语。","The train went through six tunnels on the way to Guangzhou.\nI thought hard but could not find the answer."],["weather","whether","weather 是不可数名词「天气」，可作主语或宾语；whether 是连词「是否」，用来引导宾语从句或主语从句，常与 or not 连用。句中若已有主语和谓语、缺的是连接词，就用 whether。","The weather in Guangzhou is warm and wet in spring.\nI do not know whether he will come to the party or not."],["advice","advise","advice 是不可数名词，意为「建议」，前面可用 some、much、a piece of；advise 是动词，意为「建议」，常用 advise sb to do sth。判断办法：空格前有 some 或 a piece of 用 advice，空格后接人再接不定式用 advise。","My teacher gave me some good advice on how to improve my English.\nThe doctor advised me to take more exercise every day."],["affect","effect","affect 是动词「影响」，句中作谓语，后面直接接宾语；effect 是名词「影响、效果」，常构成 have an effect on sth。缺谓语用 affect，作 have 的宾语用 effect。","Staying up late will affect your health.\nThe noise had a bad effect on my study."],["accept","except","accept 是动词「接受」，表示主观上愿意收下；except 是介词「除……之外」，常与 all、everyone、everything 等连用。句中需要谓语就用 accept，需要表示「除了」就用 except。","I am happy to accept your invitation to the English corner.\nAll the students went to the museum except Tom, who was ill."]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["He is quiet good at English.","He is quite good at English.","修饰形容词 good 要用副词 quite（相当），quiet 是形容词「安静的」，两词只差字母 e 与 t 的位置。"],["I walked thought the park after school.","I walked through the park after school.","这里需要介词「穿过」，用 through；thought 是 think 的过去式或名词「想法」，不能作介词接宾语。"],["I do not know weather he will come or not.","I do not know whether he will come or not.","whether 是连词「是否」，常与 or not 连用；weather 是名词「天气」，不能引导从句。"],["My teacher gave me some good advices.","My teacher gave me some good advice.","advice 是不可数名词，没有复数形式，也不能用 a、an 修饰；要计数时用 a piece of advice。"],["Smoking will effect your health.","Smoking will affect your health.","句中缺谓语动词，表示「影响」要用动词 affect；effect 是名词，若要用它必须改写成 have an effect on your health。"],["The noise had a bad affect on my study.","The noise had a bad effect on my study.","have an effect on 是固定搭配，这里需要名词 effect；affect 是动词，不能作 had 的宾语。"],["I am glad to except your invitation.","I am glad to accept your invitation.","这里表示「接受邀请」，应用动词 accept；except 是介词「除……之外」，不能用在 to 后面作动词。"],["Please give me some advise on learning English.","Please give me some advice on learning English.","some 后面需要名词，用 advice；advise 是动词，不能作 give 的直接宾语。"],["I am very interesting in Chinese history.","I am very interested in Chinese history.","主语是人，表示「对……感兴趣」要用 -ed 形容词 interested；interesting 用于描述事物本身令人感兴趣。"],["Be careful. Do not loose your key again.","Be careful. Do not lose your key again.","lose 是动词「丢失」；loose 是形容词「松的」，cannot loose 这样的说法不成立。"],["My cousin is going aboard to study next month.","My cousin is going abroad to study next month.","abroad 是副词「在国外、到国外」；aboard 意为「在船、飞机、车上」，两词只差一个字母，意思完全不同。"]]},{"type":"list","title":"应试策略","items":["拼写题的干扰项常常只差一两个字母（quite / quiet、through / thought），判断顺序是先定词性，再定词义。","遇到 advice 与 advise、affect 与 effect 这类「一名一动」的词，看句子缺什么成分：缺谓语用动词，作主语、宾语或介词宾语用名词。"]}],"questions":[{"id":"eng-vocab-8-q1","type":"choice","stem":"Be ______! The baby is sleeping in the next room.","answer":"A","explain":"句意是「保持安静」，Be 后作表语要用形容词 quiet。B 项 quite 是副词「相当」，修饰形容词而非作表语；C 项 quit 是动词「放弃、离开」；D 项 quietly 是副词，不能作 Be 的表语。","options":["quiet","quite","quit","quietly"],"difficulty":1,"tags":["拼写易错","quite/quiet","词性判断"]},{"id":"eng-vocab-8-q2","type":"choice","stem":"The high-speed train went ______ the mountain and arrived in time.","answer":"A","explain":"through 是介词「穿过」，指从某物内部穿过，后面接 the mountain。B 项 thought 是 think 的过去式或名词「想法」；C 项 though 是连词「虽然」；D 项 throw 是动词「扔」，都不能作介词接宾语。","options":["through","thought","though","throw"],"difficulty":1,"tags":["拼写易错","through/thought","词性判断"]},{"id":"eng-vocab-8-q3","type":"choice","stem":"I am not sure ______ the plan will work or not.","answer":"A","explain":"空格后是完整的从句，需要连词「是否」，whether 与 or not 连用是固定搭配。B 项 weather 是名词「天气」，不能引导从句；C 项 that 不能与 or not 连用；D 项 what 在从句中要充当成分，本句成分完整。","options":["whether","weather","that","what"],"difficulty":2,"tags":["拼写易错","whether/weather","从句连词"]},{"id":"eng-vocab-8-q4","type":"choice","stem":"My father often gives me some good ______ on how to learn English well.","answer":"A","explain":"some good 后面需要不可数名词，advice 是「建议」且不可数。B 项 advise 是动词，不能作 give 的直接宾语；C 项 advices 是错误复数形式；D 项 advises 是动词第三人称单数，同样不能作宾语。","options":["advice","advise","advices","advises"],"difficulty":2,"tags":["拼写易错","advice/advise","不可数名词"]},{"id":"eng-vocab-8-q5","type":"choice","stem":"The doctor ______ me to take more exercise and eat less meat last week.","answer":"A","explain":"advise sb to do sth 是固定结构，句中描述上周发生的事，用过去式 advised。B 项 advice 是名词，不能带宾语；C 项 advices 拼写错误；D 项 advising 是现在分词，不能单独作谓语。","options":["advised","advice","advices","advising"],"difficulty":2,"tags":["拼写易错","advise","固定结构"]},{"id":"eng-vocab-8-q6","type":"choice","stem":"Staying up late every night will ______ your health.","answer":"A","explain":"句中缺谓语动词，表示「影响」用动词 affect，后面接宾语 your health。B 项 effect 是名词，用它的结构应是 have an effect on；C 项 effort 是「努力」；D 项 afford 是「负担得起」，与句意不符。","options":["affect","effect","effort","afford"],"difficulty":2,"tags":["拼写易错","affect/effect","词性判断"]}]},{"id":"eng-vocab-9","title":"话题词汇串记：校园生活、环保、健康、科技网络、传统节日与文化交流","subtitle":"话题词汇 · Topic vocabulary: school life, environment, health, technology, festivals and cultural exchange","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"按中考写作五大话题成组记词块，写作文时直接调用整块表达，避免逐词翻译造成的搭配错误。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"校园生活话题的词块要整块记：take notes、hand in、after-school activities、get on well with。","explain":"书面表达写「我的学校生活」时，这些词块可以连成句子直接使用。注意 hand in 是「上交」，与 hand out（分发）方向相反。"},{"level":"重点","text":"环保话题围绕「三个动作」展开：protect、recycle、save。","explain":"protect the environment、recycle waste、save energy、reduce pollution、live a low-carbon life。写作中提出建议时用 We should ...，紧接着接这些动词短语，句子自然且得分高。"},{"level":"重点","text":"健康话题的重点是「吃、动、睡」三件事的表达。","explain":"keep a balanced diet、do exercise regularly、stay up late、junk food、mental health。写作建议类文章里，这三方面各写一句就是完整的主体段。"},{"level":"次重点","text":"科技网络话题要注意「网上做某事」的搭配。","explain":"search for information online、take online lessons、protect personal information、spend too much time on screens。注意 search the Internet for information 中 search 直接接地点宾语，for 接要找的东西。"},{"level":"次重点","text":"传统节日与文化交流话题要能准确写出四个节日的英文名称。","explain":"the Spring Festival（春节）、the Lantern Festival（元宵节）、the Dragon Boat Festival（端午节）、the Mid-Autumn Festival（中秋节），前面都要加 the，且首字母大写。"},{"level":"了解","text":"话题词汇按「名词 + 搭配动词」成对记，比单独背单词更有效。","explain":"例如 festival 与 celebrate 搭配，custom 与 follow 搭配，environment 与 protect 搭配。写作时先想动词，再补名词，句子不容易出错。"}]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["festival","holiday","festival 指有固定日期、有特定庆祝活动的节日，如 the Spring Festival、the Mid-Autumn Festival；holiday 泛指不上学、不上班的假日或假期，如 summer holiday、a public holiday。写「春节」时用 festival，写「暑假」时用 holiday。","During the Spring Festival, families get together and have a big dinner.\nWe are going to visit Beijing during the summer holiday."],["custom","habit","custom 指一个民族、地区长期形成并共同遵守的风俗习惯，是社会性的；habit 指个人长期重复形成的生活习惯，是个人的。判断办法：主语若是「人们、一个地方」用 custom，若是「某人」用 habit。","Eating mooncakes at the Mid-Autumn Festival is an old Chinese custom.\nReading before sleeping is a good habit."],["learn","study","learn 强调「学会、学到」的结果，结构有 learn sth、learn to do sth、learn about sth；study 强调「学习、钻研」的过程，也可指在校学习。表示「向某人学习」只能用 learn from sb，不能用 study from sb。","We can learn a lot about different cultures from this project.\nHe studies hard and often reviews his notes after class."]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["take notes","记笔记","上课场景高频，notes 用复数。"],["hand in","上交（作业等）","与 hand out（分发）方向相反。"],["after-school activities","课外活动","写作中常与 take part in 连用。"],["get on well with classmates","与同学相处融洽","也可说 get along well with。"],["protect the environment","保护环境","environment 前必须加 the。"],["recycle waste","回收废物","waste 作名词不可数。"],["save energy","节约能源","energy 不可数。"],["reduce pollution","减少污染","pollution 不可数，不加 s。"],["live a low-carbon life","过低碳生活","life 前用 a。"],["stop using plastic bags","停止使用塑料袋","stop doing 表示停止正在做的事。"],["keep a balanced diet","保持均衡饮食","balanced 是形容词，修饰 diet。"],["do exercise regularly","经常锻炼","exercise 表示锻炼时不可数。"],["stay up late","熬夜","主语是人，不说 stay up late the homework。"],["junk food","垃圾食品","不可数，不能说 a junk food。"],["mental health","心理健康","写作中谈压力话题常用。"],["search for information online","在网上搜索信息","也可说 search the Internet for information。"],["take online lessons","上网课","lesson 用复数表示课程。"],["protect personal information","保护个人信息","information 不可数。"],["spend too much time on screens","在屏幕前花太多时间","on 后接名词或动名词。"],["the Spring Festival","春节","节日前必须加 the，首字母大写。"],["the Lantern Festival","元宵节","与 eat tangyuan 连用。"],["the Dragon Boat Festival","端午节","与 dragon boat races 连用。"],["the Mid-Autumn Festival","中秋节","与 eat mooncakes 连用。"],["cultural exchange","文化交流","写作中常作主语，后接 helps us ...。"],["follow traditional customs","遵循传统习俗","custom 指社会风俗，habit 指个人习惯。"],["celebrate a festival","庆祝节日","celebrate 后直接接节日名称。"]]},{"type":"list","title":"应试策略","items":["写话题作文时先列三到五个词块，再连词成句，比先想中文再逐词翻译更不容易出搭配错误。","环保、健康类建议文常用 We should ... / It is important for us to ... 开头，后面直接接上话题词块，句式稳定、得分有保障。"]}],"questions":[{"id":"eng-vocab-9-q1","type":"choice","stem":"We should ______ the environment and stop using plastic bags.","answer":"A","explain":"protect the environment 是「保护环境」的固定搭配。B 项 produce 是「生产」，生产与保护环境相矛盾；C 项 provide 是「提供」，常用 provide sb with sth；D 项 prevent 是「阻止」，常用 prevent sb from doing sth，都不能直接与 the environment 构成「保护」的意思。","options":["protect","produce","provide","prevent"],"difficulty":1,"tags":["话题词汇","环保","固定搭配"]},{"id":"eng-vocab-9-q2","type":"choice","stem":"To protect the environment, we can ______ waste paper and glass bottles.","answer":"A","explain":"recycle 意为「回收利用」，正是环保行为。B 项 throw 要与 away 连用才表示「扔掉」，且扔掉废纸并不环保；C 项 produce 是「产生」，产生更多垃圾与环保相反；D 项 burn 是「焚烧」，会污染空气。","options":["recycle","throw","produce","burn"],"difficulty":1,"tags":["话题词汇","环保","语境选词"]},{"id":"eng-vocab-9-q3","type":"choice","stem":"If you want to keep healthy, you should eat a ______ diet and do exercise every day.","answer":"A","explain":"a balanced diet 是「均衡饮食」的固定搭配，balanced 是形容词修饰 diet。B 项 balance 是名词或动词，不能作定语；C 项 balancing 是分词形式；D 项 unbalanced 意为「失衡的」，与「保持健康」的语境相反。","options":["balanced","balance","balancing","unbalanced"],"difficulty":2,"tags":["话题词汇","健康","词性判断"]},{"id":"eng-vocab-9-q4","type":"choice","stem":"During the Mid-Autumn Festival, Chinese families get together and eat ______.","answer":"A","explain":"中秋节的传统食物是月饼 mooncakes。B 项 dumplings 是春节常见的饺子；C 项 zongzi 是端午节的粽子；D 项 noodles 是生日或日常食物，与中秋节不对应。","options":["mooncakes","dumplings","zongzi","noodles"],"difficulty":1,"tags":["话题词汇","传统节日","文化常识"]},{"id":"eng-vocab-9-q5","type":"choice","stem":"You can ______ the Internet for information about the science museum.","answer":"A","explain":"search 后可以直接接地点或范围作宾语，构成 search the Internet for information（在网上搜索信息）。B 项 look 是不及物动词，不能说 look the Internet；C 项 find 强调「找到」的结果，find ... for 的结构不成立；D 项 watch 是「观看」，与查找信息无关。","options":["search","look","find","watch"],"difficulty":3,"tags":["话题词汇","科技网络","搭配"]},{"id":"eng-vocab-9-q6","type":"choice","stem":"Cultural exchange helps us learn more about ______ customs and festivals in other countries.","answer":"A","explain":"空格修饰名词 customs，需要形容词 traditional（传统的）。B 项 tradition 是名词；C 项 traditionally 是副词，不能修饰名词；D 项 traditions 是名词复数，同样不能作定语修饰 customs。","options":["traditional","tradition","traditionally","traditions"],"difficulty":2,"tags":["话题词汇","文化交流","词性转换"]}]},{"id":"eng-vocab-exam-1","title":"中考词汇考点·不规则动词表","subtitle":"中考词汇考点 · Irregular Verbs: A-A-A, A-B-B, A-B-A, A-B-C","grade":"all","tags":["中考词汇考点"],"blocks":[{"type":"note","title":"学习要点","text":"把初中 98 个不规则动词按五种变化类型分成六组，记住「哪一类怎么变」，现在完成时与被动语态就不会写错三态。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"不规则动词的三态主要考现在完成时与被动语态两处","explain":"看到 have/has/had 或 be 动词，就要用过去分词。现在完成时 have done、被动语态 be done 两处都写过去分词；一般过去时才用过去式。选择题与语篇填空都从这里失分最多，判断顺序是「先看空格前的助动词，再想三态里的第几个形式」。"},{"level":"重点","text":"A-B-C 型三个形式都不相同，是混用的重灾区","explain":"write-wrote-written、break-broke-broken、choose-chose-chosen 这类词，出题人常把 wrote 放在 have 后面当干扰项。只要空格前是 have/has/had/be，一律选第三个形式（过去分词）。"},{"level":"重点","text":"三态同形的词不要加 -ed","explain":"cut、put、hit、cost、hurt、let、set、read 属于 A-A-A 型，学生最容易写 cutted、putted。另外 read 的过去式与过去分词仍拼作 read，但读 /red/，朗读与听力题会考读音。"},{"level":"次重点","text":"-ought / -aught 家族成串记，一次记六个","explain":"buy-bought、bring-brought、think-thought、fight-fought 写 -ought；catch-caught、teach-taught 写 -aught。两组常在同一道题的选项里一起出现，按「买拿想打 -ought，抓住教学 -aught」的口诀整串记。"},{"level":"次重点","text":"hang、lie、lay 是「一词两义、两套变化」的高危词","explain":"hang 表「悬挂」是 hung-hung，表「绞死」是 hanged-hanged；lie 表「躺」是 lay-lain，表「撒谎」是 lied-lied；lay 表「放置」是 laid-laid。判断依据永远是句意，不是拼写。"},{"level":"了解","text":"瞬间动词不能与 for / since 引导的延续时间连用","explain":"buy、borrow、begin、die、leave 都是瞬间动词，语篇填空常写成 He has had the bike for three years. 的形式，考的就是把 buy 换成 have had、borrow 换成 have kept。"}]},{"type":"table","title":"A-A-A 型：原形、过去式、过去分词同形","head":["单词","词性/音标","释义","考点"],"rows":[["cut-cut-cut","v.","切；剪；削减","三态同形，别写 cutted；cut down 砍倒，cut up 切碎。"],["put-put-put","v.","放；放置","put on 穿上，put off 推迟，put away 收起来。"],["let-let-let","v.","让；允许","let sb do sth，后面不加 to。"],["hit-hit-hit","v.","打；撞击","hit sb on the head 打某人的头，注意介词 on。"],["cost-cost-cost","v.","花费（钱）","主语是物：The book cost me ten yuan.；过去式仍写 cost。"],["hurt-hurt-hurt","v.","使受伤；疼","三态同形，别双写 t；My leg hurts. 用主动表被动。"],["shut-shut-shut","v.","关上","shut down 关闭（工厂、机器）；注意双写 t 只在原形里。"],["set-set-set","v.","设置；摆放","set up 建立，set off 出发。"],["read-read-read","v.","读；阅读","三态拼写相同，但过去式与过去分词读 /red/，听力朗读常考。"],["spread-spread-spread","v.","传播；展开","不加 -ed；spread the news 传播消息。"],["quit-quit-quit","v.","放弃；离职","quit doing sth 停止做某事。"],["burst-burst-burst","v.","爆裂；突然发作","burst into tears 突然哭起来。"],["cast-cast-cast","v.","投；掷；投射","cast a shadow 投下影子，cast a vote 投票。"],["split-split-split","v.","分开；裂开","split up 分开；注意双写 t 只在原形。"]]},{"type":"table","title":"A-B-A 型与元音 i-a-u 变化型（过去分词回到原形 / 元音顺次变化）","head":["单词","词性/音标","释义","考点"],"rows":[["come-came-come","v.","来；到来","come true 实现，主语常是 dream、wish。"],["become-became-become","v.","变成；成为","后接名词或形容词：become a teacher。"],["overcome-overcame-overcome","v.","克服；战胜","overcome difficulties 克服困难。"],["run-ran-run","v.","跑；经营","run out of 用完；过去式 ran 不双写 n。"],["beat-beat-beaten","v.","打；打败","过去式仍写 beat，过去分词才是 beaten，属 A-A-B 型特例。"],["begin-began-begun","v.","开始","begin to do 与 begin doing 都可以；注意 beginning 双写 n。"],["drink-drank-drunk","v.","喝；饮","drink to sb 为某人干杯。"],["sing-sang-sung","v.","唱；唱歌","过去分词 sung，被动语态 The song was sung by her."],["swim-swam-swum","v.","游泳","没有 swimmed；go swimming 去游泳。"],["ring-rang-rung","v.","打电话；（铃）响","ring up 打电话；名词 ring 是「戒指」。"],["sink-sank-sunk","v.","下沉；沉没","拓展词，阅读中常与船、石头搭配。"],["shrink-shrank-shrunk","v.","收缩；缩小","拓展词，注意不要与 sink 混。"]]},{"type":"table","title":"A-B-B 型（一）：过去式以 -ought / -aught 或 -t 结尾","head":["单词","词性/音标","释义","考点"],"rows":[["buy-bought-bought","v.","买","buy sb sth = buy sth for sb；注意介词是 for。"],["bring-brought-brought","v.","带来；拿来","bring 是「带来」，take 是「带走」，方向相反。"],["think-thought-thought","v.","想；认为","thought 也是名词「想法」：a good thought。"],["catch-caught-caught","v.","抓住；赶上","catch up with 赶上，catch a cold 感冒。"],["teach-taught-taught","v.","教","teach sb sth；teach oneself 自学。"],["fight-fought-fought","v.","打架；战斗","fight against 与……作斗争。"],["build-built-built","v.","建造；建设","被动语态 was built；build up 增强。"],["lend-lent-lent","v.","借出","lend sth to sb 把某物借给某人，与 borrow from 方向相反。"],["send-sent-sent","v.","寄；派","send for sb 派人去请。"],["spend-spent-spent","v.","花费（时间、钱）","spend ... on sth / (in) doing sth。"],["lose-lost-lost","v.","丢失；输掉","与形容词 loose（松的）形近，别混。"],["feel-felt-felt","v.","感觉；觉得","feel like doing sth 想要做某事。"],["keep-kept-kept","v.","保持；保存","keep doing sth；keep in touch 保持联系。"],["sleep-slept-slept","v.","睡觉","sleep late 睡到很晚才起；sleepy 是形容词「困的」。"],["sweep-swept-swept","v.","扫；打扫","sweep the floor 扫地。"],["meet-met-met","v.","遇见；满足","meet one's needs 满足需要；meeting 是名词。"],["lead-led-led","v.","带领；导致","lead to 导致，to 是介词，后接名词或 doing。"],["leave-left-left","v.","离开；留下","leave sth at home 把某物落在家里。"],["mean-meant-meant","v.","意思是；意味着","mean to do 打算做，mean doing 意味着做。"],["hear-heard-heard","v.","听见","hear from sb 收到某人来信，hear of 听说。"]]},{"type":"table","title":"A-B-B 型（二）：过去式以 -d / -ung / -old / -ood / -ot 等结尾","head":["单词","词性/音标","释义","考点"],"rows":[["find-found-found","v.","找到；发现","find out 查明；find it hard to do 觉得做某事难。"],["hold-held-held","v.","举行；握住","hold on 别挂电话；hold a meeting 开会。"],["make-made-made","v.","制作；使得","be made of 看得出材料，be made from 看不出。"],["pay-paid-paid","v.","付钱；支付","pay for sth 为某物付钱；pay attention to 注意。"],["say-said-said","v.","说","say 强调说的内容，tell 后接人，speak 强调说语言。"],["sell-sold-sold","v.","卖；出售","sell out 卖完；被动 be sold。"],["tell-told-told","v.","告诉；讲述","tell sb sth，tell sb to do sth。"],["stand-stood-stood","v.","站；忍受","cannot stand doing sth 无法忍受做某事。"],["understand-understood-understood","v.","理解；懂","过去式与过去分词都写 understood，注意中间是 oo。"],["sit-sat-sat","v.","坐","sit down 坐下；现在是 sitting，双写 t。"],["win-won-won","v.","赢；获胜","过去式 won，不是 winned；win the first prize 得一等奖。"],["get-got-got","v.","得到；到达","get used to 习惯于；美式过去分词可写 gotten。"],["have-had-had","v.","有；吃；使","had better do sth 最好做某事；have sth done 让别人做某事。"],["dig-dug-dug","v.","挖；掘","dig a hole 挖个洞。"],["stick-stuck-stuck","v.","粘；卡住","stick to 坚持，to 是介词。"],["hang-hung-hung","v.","悬挂；挂起","表「悬挂」用 hung；表「绞死」用 hanged，两套变化按句意选。"],["shine-shone-shone","v.","照耀；发光","The sun shone brightly.；名词 shine 是「光泽」。"],["shoot-shot-shot","v.","射击；投篮","shoot at 朝……射击；注意 oo 变 o。"],["lay-laid-laid","v.","放置；下（蛋）","lay 是及物动词，必须带宾语；与 lie（躺）区分。"],["feed-fed-fed","v.","喂养；饲养","feed sth to sb / feed sb on sth。"]]},{"type":"table","title":"A-B-C 型（一）：过去分词以 -en / -n 结尾","head":["单词","词性/音标","释义","考点"],"rows":[["be-was/were-been","v.","是；存在","现在完成时 I have been to 去过，have gone to 去了（未回）。"],["eat-ate-eaten","v.","吃","Ate 不双写 t；被动 be eaten。"],["give-gave-given","v.","给","give sth to sb；被动 be given。"],["take-took-taken","v.","拿；花费；乘坐","It takes sb some time to do sth；被动 be taken。"],["write-wrote-written","v.","写","过去分词 written 双写 t，是最高频的拼写点。"],["speak-spoke-spoken","v.","说（语言）","English is spoken in many countries."],["break-broke-broken","v.","打破；损坏","被动 be broken；broken 也可作形容词「坏的」。"],["choose-chose-chosen","v.","选择","choose to do sth；名词 choice。"],["drive-drove-driven","v.","驾驶；驱使","过去分词 driven；名词 driver。"],["ride-rode-ridden","v.","骑；乘","过去分词 ridden 双写 d。"],["rise-rose-risen","v.","上升；升起","不及物动词，没有被动语态；与 raise（及物）区分。"],["wake-woke-woken","v.","醒来；唤醒","wake up 醒来；三态是 wake-woke-woken，别按规则动词写成 waked。"],["forget-forgot-forgotten","v.","忘记","过去分词双写 t；forget to do 忘记要做，forget doing 忘记做过。"],["hide-hid-hidden","v.","躲藏；隐藏","hide from sb 躲避某人；过去分词 hidden。"],["know-knew-known","v.","知道；认识","be known for 以……闻名；注意 kn 中 k 不发音。"],["throw-threw-thrown","v.","扔；投","throw away 扔掉；过去分词 thrown。"],["blow-blew-blown","v.","吹；刮","The wind blew hard.；blow out 吹灭。"],["grow-grew-grown","v.","生长；种植","grow up 长大；grow into 长成。"],["fly-flew-flown","v.","飞；乘飞机","过去分 flown；fly to Beijing 飞往北京。"],["draw-drew-drawn","v.","画；拉","过去分词 drawn；名词 drawing 图画。"]]},{"type":"table","title":"A-B-C 型（二）：-ore / -orn、-ook / -aken、-ore / -olen 等其他变化","head":["单词","词性/音标","释义","考点"],"rows":[["go-went-gone","v.","去；走","have gone to 去了（人不在），have been to 去过（人已回）。"],["do-did-done","v.","做；干","被动 be done；do well in 在……方面做得好。"],["see-saw-seen","v.","看见；明白","被动 be seen；see sb do sth 看见某人做某事。"],["wear-wore-worn","v.","穿；戴","过去分词 worn；wear out 穿坏。"],["tear-tore-torn","v.","撕；扯破","过去分词 torn；名词 tear 是「眼泪」。"],["fall-fell-fallen","v.","落下；跌倒","fall asleep 入睡；与 feel（感觉）的过去式 felt 区分。"],["shake-shook-shaken","v.","摇动；发抖","shake hands with sb 与某人握手。"],["steal-stole-stolen","v.","偷；窃取","被动 be stolen；与 steel（钢）形近。"],["freeze-froze-frozen","v.","结冰；冻住","frozen 也可作形容词「冷冻的」。"],["mistake-mistook-mistaken","v.","误解；弄错","by mistake 错误地；mistake A for B 把 A 误认为 B。"],["show-showed-shown","v.","出示；表明","过去分词 shown 也可写 showed，被动语态用 shown 更稳。"],["lie-lay-lain","v.","躺；位于","表「躺」用 lay-lain，表「撒谎」用 lied-lied，务必按句意判断。"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["grow up","长大","例：He wants to be a doctor when he grows up."],["fall asleep","入睡","例：He fell asleep while he was reading."],["lose one's way","迷路","例：We lost our way in the old town."],["catch a cold","感冒","例：She caught a cold and stayed at home."],["take a rest","休息一下","例：Let us take a rest under the big tree."],["write down","写下，记下","例：Please write down the new words in your notebook."],["get married","结婚","例：They got married last autumn."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["现在完成时：have / has + 过去分词","主语 + have/has + 过去分词（already、yet、ever、never、just、since、for 是信号词）","I have already written the report.","我已经写好报告了。\n写动词前先看空格前有没有 have/has，有就用过去分词；never 后面的动词同样用过去分词。"],["被动语态：be + 过去分词","主语 + be + 过去分词 + (by ...)","The bridge was built by the workers in 2010.","这座桥是工人们 2010 年建成的。\n被动语态只用过去分词，不能用过去式，was broke 一定是错的。"],["一般过去时只说明过去发生的事，与现在没有联系","主语 + 过去式（yesterday、last week、three days ago、in 2010 等时间状语）","He lost his key yesterday.","他昨天把钥匙丢了。\n有明确过去时间就用过去式；要说「钥匙丢了所以现在进不了门」，才用 has lost。"],["-ought / -aught 家族的变化规律","buy/bring/think/fight → -ought；catch/teach → -aught","My father taught me how to ride a bike.","爸爸教过我骑自行车。\n两组一起背：bought、brought、thought、fought、caught、taught 六个词一次记牢。"],["一个动词有两种意思，就有两套变化","hang-hung-hung（悬挂）／hang-hanged-hanged（绞死）；lie-lay-lain（躺）／lie-lied-lied（撒谎）；lay-laid-laid（放置）","The girl lay on the grass and looked at the sky.","那个女孩躺在草地上看天空。\n先定句意再定形式：描述「挂在墙上」用 hung，描述「躺着」用 lay。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["I have cutted the paper into two pieces.","I have cut the paper into two pieces.","cut 三态同形，没有 cutted 这个形式；put、hit、cost、let 同样不加 -ed。"],["He has wrote three letters to his friend.","He has written three letters to his friend.","现在完成时用过去分词 written，wrote 是过去式，只能用在一般过去时里。"],["The window was broke by the strong wind last night.","The window was broken by the strong wind last night.","被动语态是 be + 过去分词，broken 才是过去分词；broke 是过去式。"],["My mother hanged the picture on the wall yesterday.","My mother hung the picture on the wall yesterday.","hang 表「悬挂」时过去式是 hung；hanged 只表示「绞死」。"],["The cat lied on the sofa all the afternoon.","The cat lay on the sofa all the afternoon.","lie 表「躺」的过去式是 lay、过去分词是 lain；lied 是「撒谎」的过去式。"],["I have bought this bike for three years.","I have had this bike for three years.","buy 是瞬间动词，不能与 for 引导的延续时间连用，要说「拥有」就得用 have had。"]]}],"questions":[{"id":"eng-vocab-exam-1-q1","type":"choice","stem":"I have ______ this book twice, and I want to read it again.","answer":"A","explain":"have 后面要接过去分词，read 的过去分词仍是 read（三态同形），此处读 /red/。B 项 reads 是第三人称单数；C 项 reading 不能作完成时的分词；D 项 readed 这个拼写根本不存在。","options":["read","reads","reading","readed"],"difficulty":2,"tags":["不规则动词","现在完成时","三态同形"]},{"id":"eng-vocab-exam-1-q2","type":"choice","stem":"The window ______ by the strong wind last night.","answer":"A","explain":"主语 the window 是动作的承受者，用被动语态 be + 过去分词，break 的过去分词是 broken。B 项 broke 是过去式，被动语态里不能用；C 项是主动语态，窗户不能自己打破自己；D 项与 last night 的过去时间不符。","options":["was broken","was broke","broke","has broken"],"difficulty":2,"tags":["不规则动词","被动语态","过去分词"]},{"id":"eng-vocab-exam-1-q3","type":"choice","stem":"My father ______ the picture on the wall and then went out.","answer":"A","explain":"句意是把画「挂」在墙上，hang 表「悬挂」时过去式与过去分词都是 hung。B 项 hanged 只表示「绞死」；C 项是原形，与后面的 went 时态不一致；D 项不能单独作谓语。","options":["hung","hanged","hang","hanging"],"difficulty":2,"tags":["不规则动词","hang","一词两义"]},{"id":"eng-vocab-exam-1-q4","type":"fill","stem":"用所给动词的适当形式填空。\nHe has never ______ (see) such a big fish before.","answer":"seen","explain":"has never 后面要接过去分词，see 的过去分词是 seen。注意 see-saw-seen 三态各不相同，不能填 saw。","difficulty":1,"tags":["不规则动词","现在完成时","A-B-C 型"]},{"id":"eng-vocab-exam-1-q5","type":"fill","stem":"用所给动词的适当形式填空。\nThe old bridge ______ (build) in 1930 and is still in use today.","answer":"was built","explain":"桥是「被建造」的，用被动语态 be + 过去分词；事情发生在 1930 年，be 用过去式 was，build 的过去分词是 built，所以填 was built。","difficulty":2,"tags":["不规则动词","被动语态","A-B-B 型"]},{"id":"eng-vocab-exam-1-q6","type":"fill","stem":"用所给动词的适当形式填空。\nThe dog ______ (lie) on the floor quietly a moment ago.","answer":"lay","explain":"a moment ago 说明用一般过去时；lie 表「躺」的过去式是 lay。若填 lied 就变成「撒谎」，若填 laid 则用了 lay（放置）的过去式，都与句意不符。","difficulty":3,"tags":["不规则动词","lie/lay","一般过去时"]}]},{"id":"eng-vocab-exam-2","title":"中考词汇考点·词形转换（一）：名词↔形容词、形容词↔副词","subtitle":"中考词汇考点 · Word Formation (1): Noun - Adjective - Adverb","grade":"all","tags":["中考词汇考点"],"blocks":[{"type":"note","title":"学习要点","text":"按后缀把名词变形容词、形容词变副词串成转换链（如 health → healthy → healthily），解决语篇填空里「给名词要填副词」这类送分题。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"词形转换是语篇填空的固定题型，一般 10 空里占 3 至 5 空","explain":"这类题给出提示词，要求按句子成分换成另一词性。第一步永远是看空格在句中的位置：作表语或定语要形容词，修饰动词、形容词或另一个副词要副词，作主语或宾语要名词。"},{"level":"重点","text":"名词变形容词看后缀，形容词变副词看拼写规则","explain":"-ful / -less / -y / -ous / -al / -ive 是名词转形容词的主力后缀；形容词变副词多在词尾加 -ly，但 happy → happily、true → truly、possible → possibly 有拼写变化，正是扣分点。"},{"level":"重点","text":"-ly 结尾的词不一定是副词","explain":"friendly、lovely、lonely、likely 都是形容词，不能修饰动词。中考常考 Our teacher is friendly to us.，若写成 friendlily 就错了；要表达「以友好的方式」得用 in a friendly way。"},{"level":"次重点","text":"同根词按「名词—形容词—副词」三格一起背","explain":"health-healthy-healthily、care-careful-carefully、luck-lucky-luckily。成串记住以后，无论考场上要哪一格都能立刻取出，比单独记「healthy 是健康的」有效得多。"},{"level":"次重点","text":"副词的位置也是考点","explain":"方式副词一般放在动词或宾语之后：He speaks English fluently.；频度副词 usually、often、always 放在行为动词之前、be 动词与助动词之后。写作中位置放错同样扣分。"},{"level":"了解","text":"系动词后面必须用形容词，不能用副词","explain":"be、look、sound、taste、smell、feel、become、get 是系动词，后面接形容词作表语。The soup tastes good. 不能说 tastes well，这是语法填空的高频陷阱。"}]},{"type":"table","title":"名词 → 形容词：-ful / -less","head":["单词","词性/音标","释义","考点"],"rows":[["care → careful / careless","n. → adj.","小心 → 仔细的／粗心的","副词是 carefully；careless 的副词 carelessly，三个词一起记。"],["use → useful / useless","n. → adj.","使用 → 有用的／无用的","be useful to sb 对某人有帮助。"],["help → helpful / helpless","n. → adj.","帮助 → 有帮助的／无助的","be helpful to sb；helpless 表示「无法自救的」。"],["hope → hopeful / hopeless","n. → adj.","希望 → 有希望的／无望的","be hopeful about sth 对某事抱希望。"],["harm → harmful / harmless","n. → adj.","伤害 → 有害的／无害的","be harmful to 对……有害，介词固定用 to。"],["thank → thankful","n. → adj.","感谢 → 感激的","be thankful to sb for sth 因某事感激某人。"],["wonder → wonderful","n. → adj.","惊奇 → 精彩的","口语中 Wonderful! 表示「太棒了」。"],["beauty → beautiful","n. → adj.","美 → 美丽的","beauty 改 y 为 i 再加 -ful，副词 beautifully。"],["colour → colourful","n. → adj.","颜色 → 色彩鲜艳的","作文写节日、风景时常用。"],["success → successful","n. → adj.","成功 → 成功的","副词 successfully；be successful in doing sth。"],["peace → peaceful","n. → adj.","和平 → 和平的；宁静的","a peaceful village 宁静的村庄。"],["power → powerful","n. → adj.","力量 → 强大的","作文写科技、团队时可用。"],["meaning → meaningful","n. → adj.","意义 → 有意义的","a meaningful activity 一次有意义的活动。"],["cheer → cheerful","n. → adj.","欢呼 → 兴高采烈的","描述人物性格时可用。"]]},{"type":"table","title":"名词 → 形容词：-y / -ous / -ive / -ly（注意 -ly 也构成形容词）","head":["单词","词性/音标","释义","考点"],"rows":[["health → healthy → healthily","n. → adj. → adv.","健康 → 健康的 → 健康地","三格连环考；keep healthy 不能说 keep health。"],["wind → windy","n. → adj.","风 → 有风的","天气话题必备；It is windy today."],["rain → rainy","n. → adj.","雨 → 下雨的","a rainy day 阴雨天；注意 rain 作动词是「下雨」。"],["snow → snowy","n. → adj.","雪 → 下雪的","同类还有 cloudy、sunny、foggy。"],["sun → sunny","n. → adj.","太阳 → 晴朗的","双写 n 再加 y，别写 suny。"],["cloud → cloudy","n. → adj.","云 → 多云的","天气报告常用 It will be cloudy."],["fog → foggy","n. → adj.","雾 → 有雾的","双写 g 再加 y。"],["luck → lucky → luckily","n. → adj. → adv.","运气 → 幸运的 → 幸运地","Luckily, nobody was hurt. 句首副词用逗号隔开。"],["noise → noisy → noisily","n. → adj. → adv.","噪音 → 吵闹的 → 吵闹地","noise 去 e 加 y；It is too noisy here."],["fun → funny","n. → adj.","乐趣 → 滑稽的；有趣的","fun 也可直接作形容词：a fun day。"],["danger → dangerous","n. → adj.","危险 → 危险的","It is dangerous to swim in the river."],["fame → famous","n. → adj.","名声 → 著名的","be famous for 以……闻名，be famous as 作为……而闻名。"],["humour → humorous","n. → adj.","幽默 → 幽默的","拼写有 or，别写 humerous。"],["friend → friendly","n. → adj.","朋友 → 友好的","-ly 结尾但仍是形容词，be friendly to sb。"],["love → lovely","n. → adj.","爱 → 可爱的","同样是 -ly 结尾的形容词，不能说 lovelily。"]]},{"type":"table","title":"名词 → 形容词：-al / -ant / -ent / -t","head":["单词","词性/音标","释义","考点"],"rows":[["nature → natural","n. → adj.","自然 → 自然的","副词 naturally；natural resources 自然资源。"],["nation → national","n. → adj.","国家 → 国家的","National Day 国庆节。"],["tradition → traditional","n. → adj.","传统 → 传统的","traditional festivals 传统节日，作文高频。"],["person → personal","n. → adj.","个人 → 个人的","personal information 个人信息。"],["music → musical","n. → adj.","音乐 → 音乐的","musical instrument 乐器。"],["medicine → medical","n. → adj.","药；医学 → 医学的","medical care 医疗护理。"],["education → educational","n. → adj.","教育 → 有教育意义的","an educational film 一部有教育意义的影片。"],["culture → cultural","n. → adj.","文化 → 文化的","cultural differences 文化差异。"],["environment → environmental","n. → adj.","环境 → 环境的","environmental protection 环境保护。"],["importance → important","n. → adj.","重要性 → 重要的","It is important for sb to do sth。"],["difference → different","n. → adj.","不同 → 不同的","be different from 与……不同。"],["silence → silent","n. → adj.","沉默 → 沉默的","keep silent 保持沉默。"],["patience → patient","n. → adj.","耐心 → 耐心的","be patient with sb 对某人有耐心；patient 也是名词「病人」。"],["confidence → confident","n. → adj.","信心 → 自信的","be confident of / about sth。"],["independence → independent","n. → adj.","独立 → 独立的","be independent of 不依赖……。"]]},{"type":"table","title":"形容词 → 副词：直接加 -ly","head":["单词","词性/音标","释义","考点"],"rows":[["quick → quickly","adj. → adv.","快的 → 快速地","注意不是 quikly；修饰动词放句末。"],["slow → slowly","adj. → adv.","慢的 → 缓慢地","Please drive slowly. 驾驶类句子常用。"],["clear → clearly","adj. → adv.","清楚的 → 清楚地","speak clearly 说清楚。"],["careful → carefully","adj. → adv.","仔细的 → 仔细地","listen carefully 仔细听；与 careful 的分工是必考。"],["usual → usually","adj. → adv.","通常的 → 通常","频度副词，放在行为动词前、be 动词后。"],["safe → safely","adj. → adv.","安全的 → 安全地","arrive safely 安全到达；名词 safety。"],["quiet → quietly","adj. → adv.","安静的 → 安静地","He came in quietly. 与 quite（相当）别混。"],["sudden → suddenly","adj. → adv.","突然的 → 突然","Suddenly, it began to rain. 常用于记叙文。"],["bad → badly","adj. → adv.","坏的 → 严重地；差","be badly hurt 伤得很重，不是「坏地」。"],["polite → politely","adj. → adv.","有礼貌的 → 有礼貌地","speak to sb politely。"],["recent → recently","adj. → adv.","最近的 → 最近","常与现在完成时连用：I have recently read a book."],["final → finally","adj. → adv.","最后的 → 最后；终于","作文里表示过程结尾的首选词。"],["real → really","adj. → adv.","真的 → 真正地；确实","real + ly 有两个 l，别写 realy。"],["serious → seriously","adj. → adv.","严肃的；严重的 → 严重地","be seriously ill 病得很重。"],["proud → proudly","adj. → adv.","自豪的 → 自豪地","be proud of 为……自豪。"]]},{"type":"table","title":"形容词 → 副词：拼写有变化（y→i、去 e、特殊）","head":["单词","词性/音标","释义","考点"],"rows":[["happy → happily","adj. → adv.","快乐的 → 快乐地","改 y 为 i 再加 ly，写 happyly 是典型错。"],["easy → easily","adj. → adv.","容易的 → 容易地","同上；注意不是 easilly。"],["heavy → heavily","adj. → adv.","重的 → 大量地；沉重地","It rained heavily last night. 雨下得很大。"],["angry → angrily","adj. → adv.","生气的 → 生气地","改 y 为 i；angry with sb 生某人的气。"],["busy → busily","adj. → adv.","忙的 → 忙碌地","be busy doing sth 忙于做某事。"],["lucky → luckily","adj. → adv.","幸运的 → 幸运的是","Luckily 放句首时后面加逗号。"],["noisy → noisily","adj. → adv.","吵闹的 → 吵闹地","注意 noisy 变副词也改 y 为 i。"],["healthy → healthily","adj. → adv.","健康的 → 健康地","eat healthily 吃得健康，写作加分表达。"],["early → early","adj. → adv.","早的 → 早","形式相同：get up early 早起。"],["late → late / lately","adj. → adv.","迟的 → 迟／最近","lately 意思是「最近」，不是「迟」，常与完成时连用。"],["hard → hard / hardly","adj. → adv.","硬的；困难的 → 努力地／几乎不","hardly 是「几乎不」，意思与 hard 无关，是高频陷阱。"],["true → truly","adj. → adv.","真的 → 真正地","去 e 加 ly；Yours truly 用于书信结尾。"],["possible → possibly","adj. → adv.","可能的 → 可能地","去 e 加 y，别写成 possiblely；Possibly 也可放句首。"],["full → fully","adj. → adv.","满的 → 完全地","两个 l 加 ly；be full of 充满。"],["high → high / highly","adj. → adv.","高的 → 高高地／高度地","jump high 跳得高；highly 多修饰形容词，如 highly possible。"]]},{"type":"table","title":"形容词 → 名词：-ness / -th / -ty / -ce","head":["单词","词性/音标","释义","考点"],"rows":[["kind → kindness","adj. → n.","善良的 → 善良","Thank you for your kindness. 感谢信常用。"],["dark → darkness","adj. → n.","黑暗的 → 黑暗","in the darkness 在黑暗中。"],["ill → illness","adj. → n.","生病的 → 疾病","ill 只作表语；作定语用 sick。"],["weak → weakness","adj. → n.","虚弱的 → 弱点","作文谈「我的不足」可用。"],["sad → sadness","adj. → n.","悲伤的 → 悲伤","不可数名词，不加 s。"],["careless → carelessness","adj. → n.","粗心的 → 粗心","Because of his carelessness … 是常见句式。"],["busy → business","adj. → n.","忙的 → 生意；事务","拼写与词义都变了，需单独记；on business 出差。"],["true → truth","adj. → n.","真的 → 真相","tell the truth 说实话。"],["strong → strength","adj. → n.","强壮的 → 力量","拼写变化较大，元音变 e，末尾加 gth。"],["long → length","adj. → n.","长的 → 长度","the length of the room 房间的长度。"],["wide → width","adj. → n.","宽的 → 宽度","与 length、height、depth 一起记。"],["high → height","adj. → n.","高的 → 高度","拼写为 height，不是 hight。"],["young → youth","adj. → n.","年轻的 → 青年；青春","拓展词，阅读中常见。"],["safe → safety","adj. → n.","安全的 → 安全","traffic safety 交通安全。"],["important → importance","adj. → n.","重要的 → 重要性","the importance of doing sth 做某事的重要性。"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["keep healthy","保持健康","例：Doing exercise every day helps us keep healthy. 这里不能用 health。"],["be careful with","小心对待","例：Be careful with the hot water. 介词固定用 with。"],["be helpful to","对……有帮助","例：Reading English stories is helpful to your writing."],["speak English fluently","流利地说英语","例：She can speak English fluently. 修饰动词用副词。"],["feel lonely","感到孤独","例：He felt lonely when he first came to the city. lonely 是形容词。"],["live a happy life","过着幸福的生活","例：The old couple live a happy life in the countryside."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["名词 + -ful / -less 构成形容词，表示「有……的／无……的」","care → careful / careless；use → useful / useless；hope → hopeful / hopeless","Be careful with the hot water.","小心热水。\n-ful 只有一个 l，别写成 full；-less 表「没有」，如 hopeless 无望的、homeless 无家可归的。"],["形容词 + -ly 构成方式副词","quick → quickly；careful → carefully；clear → clearly","She answered the question quickly and correctly.","她快速而正确地回答了问题。\n副词修饰动词、形容词或另一个副词，放在被修饰的动词之后最稳。"],["以「辅音字母 + y」结尾的形容词变副词，改 y 为 i 再加 -ly","happy → happily；easy → easily；heavy → heavily；lucky → luckily","The children played happily in the park.","孩子们在公园里玩得很开心。\n先改 y 为 i 再加 ly，把 happily 写成 happyly 是语篇填空最常见的拼写错。"],["以 -le 结尾的形容词变副词，去 e 加 y","possible → possibly；simple → simply；terrible → terribly；comfortable → comfortably","He explained the rule simply and clearly.","他简单清楚地讲解了这个规则。\n这类词是「去 e 加 y」，不是直接加 ly；whole → wholly 更是特殊，要单独记。"],["系动词后接形容词，不接副词","be / look / sound / taste / smell / feel / become / get + 形容词","The music sounds beautiful.","这音乐听起来很美。\n看到这些系动词，先排除所有 -ly 副词选项；well 只在表示「身体好」时才是形容词。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["He is very carefuly when he crosses the road.","He is very careful when he crosses the road.","is 后面作表语要用形容词 careful；carefully 是副词，只能修饰动词。"],["My sister can sing beautiful.","My sister can sing beautifully.","修饰动词 sing 要用副词 beautifully，beautiful 是形容词，不能修饰动词。"],["The soup tastes well.","The soup tastes good.","taste 是系动词，后面接形容词作表语；well 多作副词「好地」，不表示「味道好」。"],["He is a friendlily boy and everyone likes him.","He is a friendly boy and everyone likes him.","friendly 本身就是形容词，没有 friendlily 这种副词形式。"],["Because of his careless, he lost the match.","Because of his carelessness, he lost the match.","介词 of 后面要接名词，careless 是形容词，应换成名词 carelessness。"],["The two brothers are very difference in character.","The two brothers are very different in character.","are 后面要用形容词 different；difference 是名词，不能作表语。"]]}],"questions":[{"id":"eng-vocab-exam-2-q1","type":"fill","stem":"用括号中单词的适当形式填空。\nEating more vegetables is good for your ______ (healthy).","answer":"health","explain":"形容词性物主代词 your 后面要接名词，所以把形容词 healthy 变回名词 health。要表达「保持健康」则用 keep healthy，那里才用形容词。","difficulty":1,"tags":["词形转换","名↔形","语篇填空"]},{"id":"eng-vocab-exam-2-q2","type":"choice","stem":"The girl danced ______ at the party last night.","answer":"A","explain":"修饰动词 danced 要用副词，beautiful 的副词是 beautifully。B 项是形容词，不能修饰动词；C 项是名词；D 项是动词「美化」。","options":["beautifully","beautiful","beauty","beautify"],"difficulty":1,"tags":["词形转换","形↔副","副词修饰动词"]},{"id":"eng-vocab-exam-2-q3","type":"choice","stem":"You must be ______ with your spelling, or you will lose marks in the writing task.","answer":"A","explain":"be 动词后面作表语要用形容词，句意是提醒「要细心」，所以用 careful。B 项是副词，不能作表语；C 项是名词；D 项 careless 表示「粗心的」，与句意相反。","options":["careful","carefully","care","careless"],"difficulty":2,"tags":["词形转换","系动词","形容词作表语"]},{"id":"eng-vocab-exam-2-q4","type":"fill","stem":"用括号中单词的适当形式填空。\nHe failed the exam because of his ______ (careless).","answer":"carelessness","explain":"介词 of 后面要接名词，careless 是形容词，先变名词 carelessness（careless + ness）。注意这个词不可数，不加 s。","difficulty":2,"tags":["词形转换","形→名","-ness"]},{"id":"eng-vocab-exam-2-q5","type":"choice","stem":"Our new neighbour is very ______ to us.","answer":"A","explain":"be 后面作表语用形容词，friendly 虽然以 -ly 结尾，却是形容词，表示「友好的」。B 项 friendlily 这个词不存在；C 项是名词；D 项也是名词「友好」。","options":["friendly","friendlily","friend","friendliness"],"difficulty":3,"tags":["词形转换","-ly 形容词","易错拼写"]},{"id":"eng-vocab-exam-2-q6","type":"fill","stem":"用括号中单词的适当形式填空。\nThe children sang and danced ______ (happy) at the party.","answer":"happily","explain":"修饰动词 sang and danced 要用副词。happy 以「辅音字母 + y」结尾，变副词时先改 y 为 i，再加 -ly，所以是 happily。","difficulty":1,"tags":["词形转换","形↔副","y→i"]}]},{"id":"eng-vocab-exam-3","title":"中考词汇考点·词形转换（二）：动词↔名词、动词↔形容词","subtitle":"中考词汇考点 · Word Formation (2): Verb - Noun and Verb - Adjective","grade":"all","tags":["中考词汇考点"],"blocks":[{"type":"note","title":"学习要点","text":"按 -tion / -sion / -ment / -ed / -ing / -able 等后缀把动词变成名词或形容词，专治语篇填空里「给动词不知道怎么变」的题。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"动词变名词是语篇填空与语法选择的高频考点，-tion / -sion / -ment 覆盖大半","explain":"空格前有 a、an、the、my 这类限定词，或者空格作主语，通常要填名词。看到提示词是动词，先想 -tion（invent → invention）、-sion（decide → decision）、-ment（develop → development）三条路。"},{"level":"重点","text":"动词变形容词主要考两类：分词形容词与 -ful / -ive / -able","explain":"空格作定语或表语时要形容词。表示人的感受用 -ed（I am interested），表示事物本身令人如何用 -ing（The film is interesting）；enjoyable、comfortable、creative、active 都是必会拼写。"},{"level":"重点","text":"-tion 与 -sion 的选择有规律可循","explain":"动词以 -de 结尾多变成 -sion（decide → decision，conclude → conclusion）；以 -ss 结尾用 -ssion（discuss → discussion，express → expression）；其余多为 -tion（invent → invention，educate → education）。"},{"level":"次重点","text":"有些词形变化带来拼写变化，必须单独记","explain":"argue → argument（去 e）、equip → equipment（不可数）、true → truth、strong → strength。这四个是初中阶段最常考的例外，抄写时按音节读，边读边写。"},{"level":"次重点","text":"不可数的抽象名词不要加 -s","explain":"information、advice、progress、knowledge、equipment 都是不可数名词，语篇填空与书面表达里加 -s 就扣分；要计数用 a piece of information 这样的量词结构。"},{"level":"了解","text":"动词变名词也能表示「人」或「物」","explain":"teach → teacher、invent → inventor、visit → visitor 表示人；build → building、mean → meaning、feel → feeling 表示物或抽象概念。句意谈「人」就优先选 -er / -or。"}]},{"type":"table","title":"动词 → 名词：-tion / -sion / -ation","head":["单词","词性/音标","释义","考点"],"rows":[["decide → decision","v. → n.","决定 → 决定","-de 结尾变 -sion，拼写是 decision，不是 decidion。"],["invent → invention","v. → n.","发明 → 发明（物）","the invention of paper 纸的发明；发明者是 inventor。"],["discuss → discussion","v. → n.","讨论 → 讨论","-ss 结尾变 -ssion，双写 s；have a discussion about。"],["educate → education","v. → n.","教育 → 教育","get a good education 接受良好教育。"],["celebrate → celebration","v. → n.","庆祝 → 庆祝活动","hold a celebration 举行庆祝活动。"],["invite → invitation","v. → n.","邀请 → 邀请（函）","accept an invitation 接受邀请。"],["express → expression","v. → n.","表达 → 表达；表情","-ss 结尾用 -ssion；a useful expression 有用的表达。"],["protect → protection","v. → n.","保护 → 保护","environmental protection 环境保护。"],["pollute → pollution","v. → n.","污染 → 污染","air pollution 空气污染，不可数。"],["introduce → introduction","v. → n.","介绍 → 介绍","the introduction of the book 书的引言。"],["produce → production","v. → n.","生产 → 生产；产量","与 product（产品）区分。"],["communicate → communication","v. → n.","交流 → 交流","communication skills 沟通技巧。"],["organize → organization","v. → n.","组织 → 组织；机构","拼写为 -ization，注意 z。"],["prepare → preparation","v. → n.","准备 → 准备（工作）","make preparations for 为……做准备。"],["inform → information","v. → n.","告知 → 信息","不可数名词，没有 informations 这种写法。"]]},{"type":"table","title":"动词 → 名词：-ment / -ance / -ence / -er / -or / -ing","head":["单词","词性/音标","释义","考点"],"rows":[["develop → development","v. → n.","发展 → 发展","with the development of 随着……的发展。"],["achieve → achievement","v. → n.","实现 → 成就","a great achievement 一项伟大成就。"],["agree → agreement","v. → n.","同意 → 协议；同意","reach an agreement 达成协议。"],["argue → argument","v. → n.","争辩 → 争论","去 e 再加 -ment，写成 argument。"],["improve → improvement","v. → n.","改进 → 改进","There is much room for improvement. 还有很大改进空间。"],["treat → treatment","v. → n.","治疗 → 治疗","get medical treatment 接受治疗。"],["enjoy → enjoyment","v. → n.","享受 → 乐趣","for enjoyment 为了娱乐。"],["manage → management","v. → n.","管理 → 管理","business management 企业管理。"],["equip → equipment","v. → n.","装备 → 设备","不可数名词：a piece of equipment。"],["appear → appearance","v. → n.","出现 → 外貌；出现","care about one's appearance 在意自己的外貌。"],["perform → performance","v. → n.","表演 → 表演；表现","give a performance 表演一场。"],["differ → difference","v. → n.","不同 → 差别","make a difference 起作用、有影响。"],["visit → visitor","v. → n.","参观 → 参观者","-or 表「人」；同类还有 inventor、actor。"],["mean → meaning","v. → n.","意味着 → 意思","the meaning of the word 这个词的意思。"],["feel → feeling","v. → n.","感觉 → 感受","I know your feelings. 我理解你的感受。"]]},{"type":"table","title":"动词 → 形容词：-ed / -ing 分词形容词（人用 -ed，物用 -ing）","head":["单词","词性/音标","释义","考点"],"rows":[["interest → interested / interesting","v. → adj.","使感兴趣 → 感兴趣的／有趣的","be interested in doing sth；an interesting book。"],["excite → excited / exciting","v. → adj.","使激动 → 激动的／令人激动的","be excited about sth 对某事感到兴奋。"],["surprise → surprised / surprising","v. → adj.","使惊讶 → 惊讶的／令人惊讶的","be surprised at 对……感到惊讶。"],["bore → bored / boring","v. → adj.","使厌烦 → 厌烦的／乏味的","I am bored.／The film is boring.，主语决定用哪个。"],["amaze → amazed / amazing","v. → adj.","使惊奇 → 惊奇的／令人惊奇的","What an amazing idea! 写作常用。"],["relax → relaxed / relaxing","v. → adj.","放松 → 放松的／令人放松的","a relaxing weekend 令人放松的周末。"],["frighten → frightened / frightening","v. → adj.","使害怕 → 害怕的／吓人的","be frightened of 害怕。"],["disappoint → disappointed / disappointing","v. → adj.","使失望 → 失望的／令人失望的","be disappointed with / at。"],["satisfy → satisfied / satisfying","v. → adj.","使满意 → 满意的／令人满意的","be satisfied with 对……满意。"],["please → pleased / pleasing","v. → adj.","使高兴 → 高兴的／令人愉快的","be pleased with/to do；pleasant 也表「令人愉快的」。"],["confuse → confused / confusing","v. → adj.","使困惑 → 困惑的／令人困惑的","I am confused about the rule."],["worry → worried / worrying","v. → adj.","使担心 → 担心的／令人担心的","be worried about 担心。"],["tire → tired / tiring","v. → adj.","使疲劳 → 疲劳的／累人的","be tired of 厌倦。"],["touch → touched / touching","v. → adj.","感动 → 感动的／感人的","a touching story 一个感人的故事。"],["encourage → encouraged / encouraging","v. → adj.","鼓励 → 受鼓舞的／令人鼓舞的","encourage sb to do sth 是动词用法。"]]},{"type":"table","title":"动词 → 形容词：-ful / -ive / -able / -ous / -ant","head":["单词","词性/音标","释义","考点"],"rows":[["depend → dependent","v. → adj.","依赖 → 依赖的","be dependent on 依赖……。"],["create → creative","v. → adj.","创造 → 有创造力的","a creative student 有创造力的学生。"],["attract → attractive","v. → adj.","吸引 → 有吸引力的","an attractive city 一座有吸引力的城市。"],["act → active","v. → adj.","行动 → 积极的；活跃的","take an active part in 积极参加；名词是 action。"],["protect → protective","v. → adj.","保护 → 保护性的","与名词 protection 成串记。"],["produce → productive","v. → adj.","生产 → 多产的；高效的","a productive day 高效的一天。"],["differ → different","v. → adj.","不同 → 不同的","名词是 difference；be different from 与……不同。"],["imagine → imaginative","v. → adj.","想象 → 富有想象力的","名词 imagination。"],["enjoy → enjoyable","v. → adj.","享受 → 令人愉快的","an enjoyable trip 愉快的旅行。"],["comfort → comfortable","v. → adj.","安慰 → 舒适的","拼写 com-fort-able；反义词 uncomfortable。"],["suit → suitable","v. → adj.","适合 → 合适的","be suitable for 适合……。"],["accept → acceptable","v. → adj.","接受 → 可接受的","It is acceptable to do sth。"],["believe → believable","v. → adj.","相信 → 可信的","反义词 unbelievable 难以置信的。"],["forget → forgettable / unforgettable","v. → adj.","忘记 → 容易被忘的／难忘的","unforgettable 是写作高分词。"],["value → valuable","v. → adj.","重视 → 宝贵的","valuable advice 宝贵的建议。"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["come to a conclusion","得出结论","例：We finally came to a conclusion after the discussion."],["give a performance","表演","例：The students gave a wonderful performance at the party."],["make an agreement","达成协议","例：The two sides made an agreement at last."],["show great interest in","对……表现出浓厚兴趣","例：He shows great interest in science. interest 用作名词。"],["be deeply moved","深受感动","例：We were deeply moved by the old man's story."],["take an active part in","积极参加","例：She takes an active part in class activities. active 是形容词。"],["have a discussion about","就……进行讨论","例：We had a discussion about how to save water."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["动词 + -tion / -ation 构成抽象名词","educate → education；invent → invention；invite → invitation；communicate → communication","The invention of the telephone changed our lives.","电话的发明改变了我们的生活。\n空格前是 the 或 a、提示词是动词时，先试 -tion；information 不可数，不加 s。"],["以 -de、-ss、-mit 结尾的动词多构成 -sion / -ssion 名词","decide → decision；conclude → conclusion；discuss → discussion；permit → permission","We had a long discussion about the plan.","我们就这个计划讨论了很长时间。\ndiscussion 双写 s，decision 只有一个 s，两处拼写都是扣分点。"],["-ed / -ing 分词形容词：人用 -ed，物用 -ing","interest → interested（人）／interesting（物）；excite → excited／exciting","I am interested in science, and the science show is really interesting.","我对科学感兴趣，这个科学节目真的很有趣。\n主语是人一般选 -ed；主语是 it、the book、the film 等，一般选 -ing。"],["动词 + -ful / -able / -ive 构成形容词","enjoy → enjoyable；comfort → comfortable；create → creative；act → active","We had an enjoyable trip to the museum.","我们去博物馆的旅行很愉快。\ncomfortable 的拼写是 com-fort-able，别漏掉 or；unforgettable 表示「难忘的」。"],["动词 + -ment 构成名词，多为不可数","develop → development；equip → equipment；improve → improvement；agree → agreement","Reading widely helps the development of your language skills.","广泛阅读有助于你语言能力的发展。\nequipment 不可数，不能说 equipments；argue 变名词要去 e 写 argument。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["We had a heated discuss about the plan.","We had a heated discussion about the plan.","discuss 是动词，have a discussion 才正确；同理 decide 的名词是 decision。"],["His invent of the machine surprised us all.","His invention of the machine surprised us all.","形容词性物主代词 his 后面要接名词，所以用 invention。"],["I am very boring with this book.","I am very bored with this book.","人作主语表示感受用 -ed 形容词 bored；boring 表示事物本身令人乏味。"],["The teacher gave us many informations about the trip.","The teacher gave us much information about the trip.","information 不可数，没有复数形式，也不能与 many 连用。"],["The PE equipment in our school are new.","The PE equipment in our school is new.","equipment 是不可数名词，谓语要用单数 is。"],["His argue made the meeting much longer.","His argument made the meeting much longer.","argue 变名词要先去 e 再加 -ment，写成 argument。"]]}],"questions":[{"id":"eng-vocab-exam-3-q1","type":"fill","stem":"用括号中单词的适当形式填空。\nThe doctor made a quick ______ (decide) to save the boy.","answer":"decision","explain":"a quick 后面需要名词，decide 的名词是 decision，属于 -de 变 -sion 的一类。注意拼写只有一个 s。","difficulty":2,"tags":["词形转换","动→名","-sion"]},{"id":"eng-vocab-exam-3-q2","type":"fill","stem":"用括号中单词的适当形式填空。\nThe ______ (invent) of paper is one of China's greatest contributions to the world.","answer":"invention","explain":"句子的主语位置需要名词，invent 的名词是 invention（-tion 后缀）。要表示「发明家」才用 inventor。","difficulty":1,"tags":["词形转换","动→名","-tion"]},{"id":"eng-vocab-exam-3-q3","type":"choice","stem":"I am ______ in the story because it is really ______.","answer":"A","explain":"第一空主语是 I（人），表示「感到有兴趣」用 -ed 形容词 interested；第二空主语是 it（物），表示「本身有趣」用 -ing 形容词 interesting。","options":["interested; interesting","interesting; interested","interested; interested","interesting; interesting"],"difficulty":2,"tags":["词形转换","分词形容词","动→形"]},{"id":"eng-vocab-exam-3-q4","type":"fill","stem":"用括号中单词的适当形式填空。\nDoing sports every day is ______ (enjoy) and healthy.","answer":"enjoyable","explain":"is 后面作表语要用形容词，enjoy 加 -able 构成 enjoyable「令人愉快的」，与后面的 healthy 并列。","difficulty":2,"tags":["词形转换","动→形","-able"]},{"id":"eng-vocab-exam-3-q5","type":"choice","stem":"The students had a long ______ about how to protect the environment.","answer":"A","explain":"a long 后面需要名词，discuss 的名词是 discussion，且 -ss 结尾要写成 -ssion（双写 s）。B 项是动词，C、D 项是分词形式，都不能作 had 的宾语。","options":["discussion","discuss","discussing","discussed"],"difficulty":2,"tags":["词形转换","动→名","-ssion"]},{"id":"eng-vocab-exam-3-q6","type":"fill","stem":"用括号中单词的适当形式填空。\nThe man who invented the new machine is a famous ______ (invent) in our country.","answer":"inventor","explain":"句意是「他是一个著名的发明家」，指人要用 -or 后缀，所以填 inventor。若填 invention 就变成「发明物」，与 a famous 搭配讲不通。","difficulty":3,"tags":["词形转换","动→名","表人的后缀"]}]},{"id":"eng-vocab-exam-4","title":"中考词汇考点·高频短语动词与固定搭配","subtitle":"中考词汇考点 · Phrasal Verbs and Fixed Collocations","grade":"all","tags":["中考词汇考点"],"blocks":[{"type":"note","title":"学习要点","text":"把 take / make / get / turn / put / come / go / look / give / keep 十个高频动词的搭配与 be + 形容词 + 介词成套整理，解决选择、完形与完成句子的搭配题。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"短语动词是选择题与完形填空的必考点，判断第一步是看宾语","explain":"先看空格后接名词还是接 doing：give up doing、look forward to doing、be used to doing 都只能接动名词；再看代词放哪里：「动词 + 副词」型短语代词必须放中间。这两点决定大部分题的答案。"},{"level":"重点","text":"同一动词配不同介词或副词，意思完全不同","explain":"take off（脱下）、take up（开始从事）、take place（举行）、take after（长得像）意思各不相同。答题时先按句意确定「动作方向」，再核对搭配，不要凭「见过这个词」就选。"},{"level":"重点","text":"不及物短语动词没有被动语态","explain":"take place、come true、happen、break out 都不及物，看到 be taken place、be come true、was happened 一律排除。判断办法很简单：短语后面不需要宾语，就不可能变成被动句。"},{"level":"次重点","text":"be + 形容词 + 介词是固定搭配题的主战场，介词不能换","explain":"be good at（擅长）、be good for（对……有益）、be good with（善于与……相处）三个搭配含义不同；be interested in、be proud of、be strict with、be angry with 都要连介词一起背。"},{"level":"次重点","text":"代词宾语的位置是常见干扰项","explain":"「动词 + 副词」型短语（put away、turn on、give up）接代词时必须放中间：put it away；「动词 + 介词」型短语（look after、wait for）代词只能放后面：look after them。"},{"level":"了解","text":"一词多义的短语按「搭配对象」归类记忆","explain":"put on 搭配衣帽或节目，put off 搭配会议、比赛、计划，put up 搭配海报、帐篷，put out 搭配火。按搭配对象归类，比按中文解释死记牢得多。"}]},{"type":"table","title":"take / make 家族","head":["单词","词性/音标","释义","考点"],"rows":[["take off","phr.","脱下；（飞机）起飞","例：Take it off, please. 代词放中间。"],["take part in","phr.","参加（活动）","例：Many students took part in the singing competition. 必须带 in。"],["take care of","phr.","照顾；照料","例：She takes care of her little brother. 相当于 look after。"],["take away","phr.","拿走；带走","例：Please take the cups away. 代词放中间：take them away。"],["take place","phr.","发生；举行","例：The meeting will take place in the hall. 不及物，无被动。"],["take up","phr.","开始从事；占用（时间、空间）","例：He took up swimming last year."],["take after","phr.","（外貌或性格）像","例：She takes after her mother."],["take medicine","phr.","吃药","动词用 take，不能用 eat 或 drink。"],["take a photo","phr.","拍照","复数 take photos；为某人拍照用 take a photo of sb。"],["take notes","phr.","做笔记","例：Please take notes while listening."],["take one's time","phr.","慢慢来，别着急","例：Take your time. There is no hurry."],["make friends with","phr.","与……交朋友","例：He soon made friends with his classmates. friends 用复数。"],["make sure","phr.","确保；查明","后接 of sth 或 that 从句：make sure that the door is locked。"],["make a decision","phr.","做决定","例：You should make a decision by yourself. 也可说 make up one's mind。"],["make up","phr.","编造；组成；化妆","例：be made up of 由……组成。"],["make progress","phr.","取得进步","progress 不可数，不加 s：make great progress。"],["make a difference","phr.","有影响；起作用","例：Your help made a big difference to me. 作文可用。"],["make sense","phr.","讲得通；有道理","例：His explanation makes sense."]]},{"type":"table","title":"get / turn / put 家族","head":["单词","词性/音标","释义","考点"],"rows":[["get up","phr.","起床；起身","过去式 got up；get up early 早起。"],["get on / get along with","phr.","与……相处","例：He gets on well with his new classmates."],["get ready for","phr.","为……做准备","后接名词或动名词：get ready for the exam。"],["get lost","phr.","迷路","get + 过去分词表示状态变化。"],["get used to","phr.","习惯于","to 是介词，后接名词或 doing：get used to getting up early。"],["get together","phr.","聚会；相聚","例：We get together every Spring Festival."],["get off","phr.","下（车、飞机）","与 get on（上车）互为反义。"],["get rid of","phr.","摆脱；除掉","例：It is hard to get rid of a bad habit."],["turn on","phr.","打开（电器）","例：Turn it on, please. 代词放中间。"],["turn off","phr.","关闭（电器）","例：Remember to turn off the lights."],["turn up","phr.","调大（音量）；出现","与 turn down 互为反义。"],["turn down","phr.","调小（音量）；拒绝","例：He turned down the invitation. 拒绝邀请。"],["turn into","phr.","变成","例：Water turns into ice in winter. 相当于 change into。"],["turn to","phr.","求助于；翻到","例：You can turn to your teacher for help."],["put on","phr.","穿上；上演","例：Put on your coat. It is cold outside. 与 take off 反义。"],["put off","phr.","推迟","宾语常是 meeting、match、plan。"],["put away","phr.","把……收起来","例：Put them away before dinner. 代词放中间。"],["put up","phr.","举起；张贴；搭建","例：put up a poster 张贴海报，put up a tent 搭帐篷。"],["put out","phr.","扑灭（火）","宾语常是 fire、candle。"]]},{"type":"table","title":"come / go / look 家族","head":["单词","词性/音标","释义","考点"],"rows":[["come true","phr.","实现","主语常是 dream、wish、plan，无被动语态。"],["come up with","phr.","想出（主意、办法）","后接 idea、plan、answer。"],["come from","phr.","来自；出生于","相当于 be from。"],["come on","phr.","加油；快点","口语中用于鼓励或催促。"],["come in","phr.","进来","例：May I come in?。"],["come back","phr.","回来","例：He came back from Beijing last week."],["come out","phr.","出版；开花；（太阳）出来","例：The flowers come out in spring."],["come across","phr.","偶然遇到；偶然发现","例：I came across an old friend in the street."],["go on","phr.","继续；（事情）发生","go on doing 继续做同一件事，go on to do 接着做另一件事。"],["go over","phr.","复习；检查","例：Go over your notes before the exam."],["go out","phr.","出去；（灯）熄灭","主语是灯时表示熄灭。"],["go through","phr.","经历；仔细检查","后接 difficulties、papers 等。"],["go away","phr.","走开；离开","例：The pain will go away soon."],["look after","phr.","照顾；照料","例：look after him 代词放介词后。"],["look for","phr.","寻找","强调动作过程，与 find（找到）区分。"],["look up","phr.","查阅；抬头看","例：look up the word in the dictionary；代词放中间：look it up。"],["look forward to","phr.","盼望；期待","to 是介词，后接名词或 doing。"],["look out","phr.","小心；当心","例：Look out! The car is coming."]]},{"type":"table","title":"give / keep / run / hand / bring 等家族","head":["单词","词性/音标","释义","考点"],"rows":[["give up","phr.","放弃；戒掉","后接动名词：give up smoking；代词放中间：give it up。"],["give out","phr.","分发；发出","例：The teacher gave out the test papers."],["give away","phr.","赠送；泄露（秘密）","例：He gave away his old books to the children."],["give back","phr.","归还","例：Please give back the book to me. 相当于 return。"],["give in","phr.","让步；屈服","不及物：He never gives in to difficulties."],["keep on","phr.","继续（做）","后接 doing：keep on working。"],["keep away from","phr.","远离","例：Keep away from the fire."],["keep in touch","phr.","保持联系","例：We keep in touch by email. 与 with sb 连用。"],["keep up with","phr.","跟上；赶上","例：He runs fast and I cannot keep up with him."],["keep doing sth","phr.","一直做某事","强调持续不断；与 keep on doing 意思相近。"],["run out of","phr.","用完；耗尽","例：We ran out of water in the desert. 主语是人。"],["run after","phr.","追赶；追求","例：The dog ran after the ball."],["run away","phr.","逃跑；跑开","例：The little boy ran away from home."],["hand in","phr.","上交；提交","例：Hand in your homework tomorrow morning."],["hand out","phr.","分发","与 give out 意思相近。"],["bring up","phr.","抚养；提出（话题）","被动常用：He was brought up by his grandparents."],["bring back","phr.","归还；使想起","例：The song brought back my childhood memories."],["call up","phr.","打电话给……","例：I will call you up this evening. 代词放中间。"]]},{"type":"table","title":"be + 形容词 + 介词 固定搭配","head":["单词","词性/音标","释义","考点"],"rows":[["be good at","phr.","擅长","后接名词或 doing：be good at swimming。"],["be good for","phr.","对……有益","例：Vegetables are good for your health."],["be good with","phr.","善于应付（人、物）","例：She is good with children."],["be interested in","phr.","对……感兴趣","后接名词或 doing；主语是人。"],["be afraid of","phr.","害怕","后接名词或 doing：be afraid of making mistakes。"],["be proud of","phr.","为……感到自豪","例：We are proud of our school team."],["be full of","phr.","充满","例：The hall was full of students. 相当于 be filled with。"],["be famous for","phr.","以……而闻名","例：Guangzhou is famous for its food."],["be famous as","phr.","作为……而闻名","例：He is famous as a writer."],["be angry with sb","phr.","生某人的气","例：My mother was angry with me."],["be angry about sth","phr.","因某事生气","例：He was angry about the noise."],["be strict with sb","phr.","对某人严格","对人用 with，对事用 in：be strict in his work。"],["be worried about","phr.","担心","例：She is worried about her son's study."],["be busy with","phr.","忙于","也可说 be busy doing sth。"],["be late for","phr.","迟到","例：Do not be late for class again."],["be ready for","phr.","为……做好准备","例：We are ready for the sports meeting."],["be different from","phr.","与……不同","例：My hobby is different from yours."],["be surprised at","phr.","对……感到惊讶","例：We were surprised at the news."]]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["take off","put off","take off 是「脱下」或「起飞」，put off 是「推迟」；两个短语只差一个动词，考试常同时出现在选项里。","It is warm inside, so you can take off your coat.\nThe class meeting was put off until next Monday."],["look for","find","look for 强调「寻找」这个动作与过程，find 强调「找到」的结果；过程用 look for，结果用 find。","I am looking for my English notebook everywhere.\nAt last I found my notebook under the desk."],["be used to","get used to","be used to 表示「习惯于」的状态，get used to 表示「渐渐习惯」的变化过程；两者 to 都是介词，后面接名词或 doing。","He is used to getting up early every day.\nYou will get used to the life here soon."],["take place","happen","take place 多指按计划举行的活动，happen 多指偶然发生的事；两者都是不及物动词，都没有被动语态。","The school sports meeting will take place next Friday.\nThe traffic accident happened at seven this morning."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["「动词 + 副词」型短语接代词时，代词放中间","put away / turn on / give up / pick up + it/them → put it away","Your books are everywhere. Please put them away.","你的书到处都是，请把它们收起来。\n看到空格里是 it、them，就去找「动词 + 代词 + 副词」的语序；接名词则两种语序都可以。"],["「动词 + 介词」型短语的宾语（含代词）只能放在介词后面","look after sb / wait for sb / listen to sb / laugh at sb","The old man needs someone to look after him.","这位老人需要有人照顾他。\n不能说 look him after；介词后面接代词用宾格。"],["be + 形容词 + 介词是固定搭配，介词随形容词而定","be good at / be interested in / be proud of / be strict with sb / be full of","Our teacher is strict with us, but she is also kind.","我们老师对我们很严格，但也很和蔼。\n背搭配时连介词一起背；只背 good、interested 等于没背。"],["不及物短语动词没有被动语态","take place、come true、happen、break out 只用主动形式","The sports meeting will take place next Friday.","运动会将于下周五举行。\n短语后面不带宾语，就不可能变成被动句，be taken place 一定是错的。"],["to 后面接 doing 的固定短语","look forward to doing；be used to doing；pay attention to doing；get used to doing","I am looking forward to hearing from you soon.","我盼望着尽快收到你的来信。\n这里的 to 是介词，不是不定式符号，后面必须接动词 -ing 形式。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["Please turn on it. The room is very dark.","Please turn it on. The room is very dark.","turn on 是「动词 + 副词」型短语，代词宾语必须放在动词和副词中间。"],["The traffic accident was happened near our school last night.","The traffic accident happened near our school last night.","happen 是不及物动词，没有被动语态，直接用作谓语即可。"],["I am looking forward to see you at the party.","I am looking forward to seeing you at the party.","look forward to 里的 to 是介词，后面接动词 -ing 形式。"],["Eating too much sugar is bad to your teeth.","Eating too much sugar is bad for your teeth.","be bad for 是固定搭配，意为「对……有害」，介词不能用 to。"],["He is very good in maths and he often helps others.","He is very good at maths and he often helps others.","be good at 表示「擅长」，介词固定用 at。"],["My mother gave up to smoke last year.","My mother gave up smoking last year.","give up 后面接动名词，不能接不定式。"]]}],"questions":[{"id":"eng-vocab-exam-4-q1","type":"choice","stem":"Your clothes are all over the bed. Please ______ before you go out.","answer":"A","explain":"put away 是「动词 + 副词」型短语，代词宾语必须放在中间，所以是 put them away。B 项语序错误；C 项语序错误且 put on 是「穿上」；D 项 put them on 意为「穿上它们」，与收拾衣物的句意不符。","options":["put them away","put away them","put on them","put them on"],"difficulty":3,"tags":["短语动词","代词位置","put 家族"]},{"id":"eng-vocab-exam-4-q2","type":"choice","stem":"Our school sports meeting will ______ next Friday if it does not rain.","answer":"A","explain":"take place 意为「举行」，是不及物短语，主语是运动会，正好符合。B 项 take place 没有被动语态，be taken place 是错的；C 项 take part 必须加 in 才能接宾语；D 项 happen 同样是不及物动词，不能用被动。","options":["take place","be taken place","take part","be happened"],"difficulty":2,"tags":["短语动词","不及物短语","被动语态"]},{"id":"eng-vocab-exam-4-q3","type":"choice","stem":"I am looking forward to ______ from you soon.","answer":"A","explain":"look forward to 中的 to 是介词，后面要接动名词 hearing。B 项是不定式，只有在 to 作不定式符号时才用；C、D 项形式与搭配都不成立。","options":["hearing","hear","heard","be heard"],"difficulty":2,"tags":["短语动词","to 作介词","look 家族"]},{"id":"eng-vocab-exam-4-q4","type":"choice","stem":"Vegetables are good ______ your health, and Tom is good ______ cooking.","answer":"A","explain":"be good for 表示「对……有益」，第一空配 health；be good at 表示「擅长」，第二空配 cooking。其余组合都不符合两个固定搭配。","options":["for; at","at; for","to; in","for; with"],"difficulty":2,"tags":["固定搭配","be good for/at","介词"]},{"id":"eng-vocab-exam-4-q5","type":"fill","stem":"根据中文提示补全句子，每空一词。\n我不喜欢早起，但我已经习惯了。\nI do not like getting up early, but I have ______ ______ ______ it.","answer":"got used to|gotten used to","explain":"get used to 表示「习惯于」，to 是介词，后面接代词 it。前面有 have，所以用 get 的过去分词 got（美式也可写 gotten），三空依次是 got / gotten、used、to。","difficulty":3,"tags":["短语动词","get used to","现在完成时"]},{"id":"eng-vocab-exam-4-q6","type":"fill","stem":"用所给词的适当形式填空。\nThe old man ______ (look) after by his neighbours when he was ill.","answer":"looked","explain":"老人是「被照顾」的，用被动语态；look after 是「动词 + 介词」型短语，变被动时介词 after 必须保留，所以只把 look 变成过去分词 looked，构成 was looked after。","difficulty":3,"tags":["短语动词","被动语态","look after"]}]},{"id":"eng-vocab-exam-5","title":"中考词汇考点·易错拼写与形近词","subtitle":"中考词汇考点 · Common Spelling Mistakes and Confusable Words","grade":"all","tags":["中考词汇考点"],"blocks":[{"type":"note","title":"学习要点","text":"按双写辅音、ie/ei、-ful/-full、-tion/-sion、形近词五类整理易错拼写，把作文与语篇填空里那些「会读不会写、写了就写错」的词一次清理干净。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"形近词判断第一步定词性，第二步才定词义","explain":"advice/advise、affect/effect、breath/breathe 都是「名词与动词」配对。空格缺谓语就用动词，缺主语或宾语、或前面有 a、the、my 就用名词。先看成分再看意思，比凭感觉选准确得多。"},{"level":"重点","text":"双写辅音与 ie/ei 是拼写题的固定考法","explain":"重读闭音节加 -ing/-ed 要双写末尾辅音（begin → beginning，stop → stopped）；ie 一般写在 ei 前面，但 c 后面写 ei（receive、ceiling）。作文与语篇填空里拼错一个字母就直接丢分。"},{"level":"重点","text":"-ful 只有一个 l，-ly 的加法要看词尾","explain":"careful、useful、beautiful 都只有一个 l；real + ly 是 really（两个 l），final + ly 是 finally，happy 要先改 y 为 i 再加 ly。这三条覆盖了后缀拼写题的大部分失分点。"},{"level":"次重点","text":"-tion 与 -sion 的选择由动词词尾决定","explain":"decide → decision、conclude → conclusion 用 -sion；discuss → discussion、express → expression 用 -ssion；其余多与 -tion（education、information、attention）。"},{"level":"次重点","text":"同音或近音的词要靠句意与搭配区分","explain":"there/their、its/it's、whose/who's、than/then 在听力与完形中常被设成干扰项。判断办法是把缩写还原成完整形式（it is、who is），还原后通顺才用带撇号的那个。"},{"level":"了解","text":"拼写错误集中在「多一个字母、少一个字母、写错字母顺序」三类","explain":"becuase、freind、tommorrow、quie 都是真实高频错写。抄写时按音节读，边读边写，比一遍遍抄整词有效；听写后一定要回头核对字母顺序。"}]},{"type":"table","title":"双写辅音：加 -ing / -ed / -er 时的高频易错词","head":["单词","词性/音标","释义","考点"],"rows":[["beginning","n.","开始；开端","begin 双写 n；at the beginning of 在……之初，别写 begining。"],["running","v.-ing","跑（现在分词）","run 是「辅 + 元 + 辅」结尾，双写 n；go running 去跑步。"],["sitting","v.-ing","坐（现在分词）","sit 双写 t；sit down 的进行式是 sitting down。"],["getting","v.-ing","得到（现在分词）","get 双写 t，别写 geting。"],["putting","v.-ing","放（现在分词）","put 双写 t；putting 与 puting 只差一个字母，常错。"],["swimming","v.-ing","游泳（现在分词）","swim 双写 m；go swimming 去游泳。"],["planning","v.-ing","计划（现在分词）","plan 双写 n；planning 也作名词「规划」。"],["stopped","v.-ed","停止（过去式）","stop 双写 p；stop doing sth 停止做某事。"],["planned","v.-ed","计划（过去式）","plan 双写 n 再加 ed。"],["biggest","adj.","最大的","big 是「辅 + 元 + 辅」结尾，比较级与最高级都双写 g。"],["hotter","adj.","更热的","hot 双写 t；最高级 hottest。"],["thinner","adj.","更瘦的","thin 双写 n；比较级 thinner，最高级 thinnest。"],["preferred","v.-ed","更喜欢（过去式）","prefer 重音在最后，双写 r 再加 ed。"],["forgotten","v.-pp.","忘记（过去分词）","forget 双写 t；forgotten 是过去分词，过去式是 forgot。"],["winning","v.-ing","赢（现在分词）","win 双写 n；the winning team 获胜的队伍。"]]},{"type":"table","title":"ie / ei 与字母顺序易错词","head":["单词","词性/音标","释义","考点"],"rows":[["believe","v.","相信","ie 顺序；I believe in you. 常见错写 beileve。"],["receive","v.","收到；接待","c 后写 ei；最常错写成 recieve。"],["achieve","v.","实现；达到","ie 顺序；achieve one's dream 实现梦想。"],["field","n.","田野；领域","ie 顺序；注意与 filled 区分。"],["piece","n.","一块；一片","ie 顺序；a piece of paper 一张纸。"],["thief","n.","小偷","ie 顺序；复数 thieves 改 f 为 v。"],["friend","n.","朋友","读音是 /frend/，但拼写是 ie；make friends with 与……交朋友。"],["science","n.","科学","ie 顺序；形容词 scientific，注意拼写变化大。"],["quiet","adj.","安静的","e 在 t 前；keep quiet 保持安静。"],["quite","adv.","相当；十分","e 在 t 后；修饰形容词：quite good。"],["foreign","adj.","外国的","ei 顺序且 g 不发音；a foreign language 外语。"],["height","n.","高度；身高","ei 顺序，结尾是 ht；what is your height。"],["weight","n.","重量；体重","ei 顺序，与 wait 同音不同义。"],["ceiling","n.","天花板","c 后写 ei；同类还有 receive。"],["neither","pron./adv.","两者都不","ei 顺序；neither of them 他们俩都不。"]]},{"type":"table","title":"后缀拼写：-ful / -full 与 -ly / -ally","head":["单词","词性/音标","释义","考点"],"rows":[["careful","adj.","仔细的；小心的","care + ful，只有一个 l；be careful with。"],["beautiful","adj.","美丽的","beauty 改 y 为 i 再加 ful；副词 beautifully。"],["useful","adj.","有用的","一个 l；be useful to sb。"],["helpful","adj.","有帮助的","一个 l；反义词 helpless。"],["wonderful","adj.","精彩的；极好的","一个 l；口语中 Wonderful! 表示赞叹。"],["successful","adj.","成功的","双写 s 再加 ful；副词 successfully。"],["cheerful","adj.","兴高采烈的","一个 l；描述人物性格可用。"],["thankful","adj.","感激的","一个 l；be thankful to sb for sth。"],["finally","adv.","最后；终于","final + ly；作文表示过程结尾的首选词。"],["really","adv.","真正地；确实","real + ly 有两个 l；常用于加强语气。"],["usually","adv.","通常","usual + ly；频度副词放在行为动词前、be 动词后。"],["happily","adv.","快乐地","happy 改 y 为 i 再加 ly；写 happyly 是典型错。"],["easily","adv.","容易地","easy 改 y 为 i；注意不是 easilly。"],["actually","adv.","事实上；实际上","actual + ly，注意 -ally；口语与作文都常用。"],["especially","adv.","尤其；特别是","注意 -ally；especially 后接被强调的成分。"]]},{"type":"table","title":"名词后缀拼写：-tion / -sion / -cian","head":["单词","词性/音标","释义","考点"],"rows":[["decision","n.","决定","decide → decision，一个 s；make a decision。"],["discussion","n.","讨论","discuss → discussion，双写 s；have a discussion about。"],["conclusion","n.","结论","conclude → conclusion；come to a conclusion 得出结论。"],["permission","n.","许可","permit → permission；ask for permission 请求许可。"],["expression","n.","表达；表情","express → expression，双写 s。"],["impression","n.","印象","impress → impression；leave a good impression on sb。"],["television","n.","电视","-sion 结尾；watch television 看电视。"],["education","n.","教育","educate → education，-tion 结尾；不可数。"],["information","n.","信息","不可数，没有 informations；a piece of information。"],["attention","n.","注意；关注","pay attention to 注意，to 是介词。"],["question","n.","问题","-tion 结尾，注意 qu 的拼写；ask a question。"],["suggestion","n.","建议","suggest → suggestion，双写 g；名词是可数的，这一点与 advice 不同。"],["competition","n.","比赛；竞赛","compete → competition；take part in a competition。"],["invitation","n.","邀请（函）","invite → invitation；accept an invitation。"],["musician","n.","音乐家","-cian 表示人；同类还有 politician、Australian。"]]},{"type":"table","title":"形近词（一）：一名一动、词性不同","head":["单词","词性/音标","释义","考点"],"rows":[["advice / advise","n. / v.","建议（名词）／建议（动词）","缺谓语用 advise，作宾语用不可数名词 advice。"],["affect / effect","v. / n.","影响（动词）／影响（名词）","have an effect on 是固定搭配。"],["practice / practise","n. / v.","练习（名词）／练习（动词）","英式分清名动，美式都用 practice；Practice makes perfect."],["breath / breathe","n. / v.","呼吸（名词）／呼吸（动词）","take a deep breath 深吸一口气；breathe 结尾有 e。"],["safe / save","adj. / v.","安全的／拯救；节省","be safe 是形容词；save water 节约用水。"],["belief / believe","n. / v.","信念／相信","belief 是名词，believe 是动词，结尾字母不同。"],["choice / choose","n. / v.","选择（名词）／选择（动词）","make a choice，choose to do sth。"],["lose / loose","v. / adj.","丢失／松的","lose 是动词，loose 是形容词；别写 loose your key。"],["rise / raise","v. / v.","上升（不及物）／举起、提高（及物）","rise 没有宾语，raise 必须带宾语：raise your hand。"],["lie / lay","v. / v.","躺；撒谎／放置","lie on the bed 躺；lay the book on the desk 放。"],["steal / steel","v. / n.","偷／钢","steal 过去式 stole；steel 是名词，注意读音相同。"],["accept / except","v. / prep.","接受／除……之外","句中需要谓语用 accept，表示「除了」用 except。"],["beside / besides","prep. / prep.","在……旁边／除……之外（还有）","besides 表示追加，常放句首加逗号。"],["through / thought / though","prep. / n. / conj.","穿过／想法／虽然","介词用 through，名词「想法」是 thought，连词「虽然」是 though。"],["weather / whether","n. / conj.","天气／是否","whether 引导从句，常与 or not 连用。"]]},{"type":"table","title":"形近词（二）：读音相近、拼写相近","head":["单词","词性/音标","释义","考点"],"rows":[["there / their","adv. / pron.","那里／他们的","over there 在那边；their books 他们的书。"],["its / it's","pron. / 缩写","它的／它是","it's = it is 或 it has，还原后通顺才用撇号。"],["whose / who's","pron. / 缩写","谁的／谁是","who's = who is；Whose bag is this?。"],["than / then","conj. / adv.","比／然后","比较级后用 than；表示时间顺序用 then。"],["of / off","prep. / adv.","……的／离开、关掉","off 多一个 f；turn off、take off 都用 off。"],["form / from","n. / prep.","形式；表格／从……","be from 来自；fill in a form 填表。"],["desert / dessert","n. / n.","沙漠／甜点","甜点多一个 s，可以记成「甜点要两份（两个 s）」。"],["price / prize","n. / n.","价格／奖品","the price of 价格；win the first prize 得一等奖。"],["hard / hardly","adv. / adv.","努力地／几乎不","hardly 与 hard 意思无关：He hardly spoke. 他几乎没说话。"],["alone / lonely","adv. / adj.","独自／孤独的","live alone 独自生活；feel lonely 感到孤独。"],["hear / here","v. / adv.","听见／这里","hear from sb 收到某人来信；Come here."],["wear / where","v. / adv.","穿／在哪里","wear a coat 穿外套；Where are you from?。"],["whole / hole","adj. / n.","整个的／洞","the whole day 一整天；dig a hole 挖个洞。"],["weak / week","adj. / n.","虚弱的／星期","be weak in 在……方面弱；last week 上周。"],["through / threw","prep. / v.-ed","穿过／扔掉（过去式）","threw 是 throw 的过去式，读音相同但词性不同。"]]},{"type":"table","title":"近义辨析","head":["词语 A","词语 B","区别","例句"],"rows":[["advice","advise","advice 是不可数名词「建议」，advise 是动词「建议」，句型是 advise sb to do sth。看句子缺什么成分：缺谓语用动词，作宾语用名词。","My teacher gave me some useful advice on reading.\nMy teacher advised me to read more English books."],["affect","effect","affect 是动词「影响」，effect 是名词「影响、效果」，固定搭配是 have an effect on sth。","The bad weather affected our trip to the island.\nThe noise had a bad effect on my study."],["quiet","quite","quiet 是形容词「安静的」，quite 是副词「相当」，修饰形容词或副词；两词只差字母 e 与 t 的位置。","Please keep quiet in the reading room.\nThe film we saw yesterday was quite interesting."],["beside","besides","beside 是介词「在……旁边」；besides 是介词或副词「除……之外（还有）」，表示追加。","She sat beside her mother all the time.\nBesides English, he also learns French."],["through","thought","through 是介词「穿过」，指从内部穿过；thought 是 think 的过去式，也可作名词「想法」。","The train went through a long tunnel.\nI thought about the question for a while."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["重读闭音节结尾的动词，加 -ing / -ed 时双写末尾辅音","「辅音 + 元音 + 辅音」结尾 → 双写：begin → beginning；stop → stopped；plan → planned","The film is beginning, so please be quiet.","电影要开始了，请安静。\n先看是不是「辅 + 元 + 辅」结尾，再看重音是否落在最后一个音节，两个条件都满足才双写；visit 就不是重读闭音节，所以写 visiting。"],["ie 与 ei 的拼写规律：i 在 e 前，c 后写 ei","believe、field、piece、achieve 用 ie；receive、ceiling 用 ei","I received a letter from my pen friend last week.","上周我收到了笔友的一封信。\nreceive、ceiling 是 c 后写 ei 的典型词，其余多数写 ie；recieve 是最常见的拼写错。"],["-ful 后缀只有一个 l，-ly 的加法要看形容词词尾","care + ful → careful；real + ly → really；final + ly → finally；happy → happily","Be careful, and you will finally get it right.","细心一点，你最终会做对的。\n-ful 与 full 不同：作后缀时只写一个 l，full 单独作形容词时才写两个 l。"],["名词后缀 -tion / -sion / -ssion 由动词词尾决定","invent → invention；decide → decision；discuss → discussion","The students had a discussion about the decision.","学生们就这个决定进行了讨论。\n-de 结尾用 -sion，-ss 结尾用 -ssion，其余多半用 -tion。"],["同音异形词靠句意与搭配区分","there（那里）／their（他们的）；its（它的）／it's（它是）；whose（谁的）／who's（谁在）","Their school is over there, and it is very big.","他们的学校在那边，规模很大。\n看到撇号先想「是不是 is/has 的缩写」，把它还原成完整形式，句子通顺才用它。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["We will have a class meeting at the begining of next week.","We will have a class meeting at the beginning of next week.","begin 加 -ing 要双写 n，正确写法是 beginning，只写一个 n 是典型拼写错。"],["My teacher gave me some useful advices about writing.","My teacher gave me some useful advice about writing.","advice 是不可数名词，没有复数形式，要计数用 a piece of advice。"],["The noise had a bad affect on my study.","The noise had a bad effect on my study.","have an effect on 是固定搭配，这里需要名词 effect；affect 是动词，不能作 had 的宾语。"],["He is quiet good at maths.","He is quite good at maths.","修饰形容词 good 要用副词 quite（相当）；quiet 是形容词「安静的」，两词字母顺序不同。"],["I recieved a letter from my pen friend yesterday.","I received a letter from my pen friend yesterday.","receive 的拼写是 c 后写 ei，写成 recieve 是最常见的拼写错。"],["Walks in the park is good for our healthy.","Walking in the park is good for our health.","动名词作主语用 walking；介词 for 后面要接名词 health，不能接形容词 healthy。"]]}],"questions":[{"id":"eng-vocab-exam-5-q1","type":"choice","stem":"The heavy rain had a bad ______ on the traffic in our city.","answer":"A","explain":"have a bad effect on 是固定搭配，a bad 后面需要名词，所以用 effect。B 项 affect 是动词；C 项是形容词；D 项是动词的第三人称单数形式，都不能作 had 的宾语。","options":["effect","affect","effective","affects"],"difficulty":2,"tags":["形近词","affect/effect","固定搭配"]},{"id":"eng-vocab-exam-5-q2","type":"fill","stem":"用括号中单词的适当形式填空。\nThe film is ______ (begin) at eight o'clock, so we must hurry.","answer":"beginning","explain":"is 后面接现在分词构成现在进行时，表示按计划即将发生的事。begin 是「辅音 + 元音 + 辅音」结尾的重读闭音节，要双写 n 再加 -ing，写成 beginning。","difficulty":2,"tags":["易错拼写","双写辅音","现在进行时"]},{"id":"eng-vocab-exam-5-q3","type":"choice","stem":"My uncle ______ a letter from his old friend last week.","answer":"A","explain":"last week 说明用一般过去时，要用 receive 的过去式；拼写上 c 后面写 ei，正确形式是 received。B 项字母顺序写错，C 项是原形，D 项是现在分词。","options":["received","recieved","receive","receiving"],"difficulty":2,"tags":["易错拼写","ie/ei","一般过去时"]},{"id":"eng-vocab-exam-5-q4","type":"choice","stem":"Their school is over ______, and ______ very big.","answer":"A","explain":"第一空表示「在那边」，用副词 there；第二空意为「它是」，用 it's（it is 的缩写）。B、D 项的 their 是「他们的」，不能表示地点；C 项 its 是「它的」，与后面的形容词 big 搭配不成立。","options":["there; it's","their; its","there; its","their; it's"],"difficulty":2,"tags":["形近词","同音词","缩写"]},{"id":"eng-vocab-exam-5-q5","type":"fill","stem":"根据中文提示补全句子，每空一词。\n吸烟对你的健康有害。\nSmoking is harmful to your ______.","answer":"health","explain":"形容词性物主代词 your 后面要接名词，所以把形容词 healthy 换成名词 health；harmful to 表示「对……有害」，是固定搭配。","difficulty":1,"tags":["易错拼写","名↔形","固定搭配"]},{"id":"eng-vocab-exam-5-q6","type":"fill","stem":"根据中文提示补全句子，每空一词。\n他的粗心导致了这场事故。\nHis ______ led to the accident.","answer":"carelessness","explain":"his 后面要接名词，careless 的名词是 carelessness（careless + ness）。注意这个词不可数，不加 s；led 是 lead 的过去式，读题时别误当成「导致」的现在式。","difficulty":3,"tags":["易错拼写","-ness","形→名"]}]},{"id":"eng-vocab-pos-1","title":"词性索引·名词（一）：可数性与复数变化","subtitle":"词性索引 · Nouns (1): Countability and Plural Forms","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把名词先分「可数、不可数」再谈复数，一次解决 -es / -ies / fe→ves 与不规则复数的拼写，语法选择和写作填空里的名词题基本不再丢分。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"名词的第一步不是背复数，而是判断可数不可数：可数名词前可用 a/an、many、few，不可数名词前只能 much、little、a lot of。","explain":"语法选择的固定设错方式是把不可数名词当可数用，如 many informations、a good news。快速判断：空格前有 a/an 或 many/few/these，名词必须可数且用复数；出现 much/little/a bit of，后面只能是不可数名词。"},{"level":"重点","text":"以 -s、-x、-ch、-sh 结尾的可数名词加 -es，不能只加 -s。","explain":"写作第一节填空题最爱考这一类拼写：bus→buses、box→boxes、watch→watches、brush→brushes。判断口诀：结尾音是「嘶、嘘」声就加 -es，bus 的复数是 buses，不能直接在词尾加 ’s。"},{"level":"重点","text":"辅音字母 + y 结尾变 y 为 i 加 -es，元音字母 + y 结尾直接加 -s；-f / -fe 结尾多把 f 变 v 加 -es，但有例外。","explain":"这两条是拼写题的分水岭：city→cities 但 boy→boys；leaf→leaves、knife→knives、wife→wives，而 roof→roofs、chief→chiefs、belief→beliefs 是只加 -s 的例外。中考只考课标词，把课标里的例外词单独记成一小串即可。"},{"level":"次重点","text":"不规则复数要整词记：man→men、woman→women、child→children、foot→feet、tooth→teeth、mouse→mice。","explain":"完形与语法选择里一旦出现 two / three 加名词，就要立刻想到这些词。注意 German→Germans 是规则变化，而 Chinese、Japanese、sheep、deer、fish 单复数同形，不加 -s。"},{"level":"次重点","text":"people 本身是复数，person 才是单数；police 也按复数处理。","explain":"There are many people in the park.（谓语用 are）；a young person 一个人。police 作主语时谓语用复数：The police are looking for the missing dog. 这是阅读细节题与语法题的常见考点。"},{"level":"了解","text":"「数词 + 名词」作定语修饰另一个名词时，这个名词不加 -s。","explain":"a ten-year-old boy、a two-hour ride、two hundred students。写作里写「一个八岁的女孩」错成 an eight-years-old girl 很常见，记住中间用连字符时名词用单数。"}]},{"type":"table","title":"规则复数：直接加 -s 的可数名词","head":["单词","词性/音标","释义","考点"],"rows":[["student","n.","学生","复数 students；a student of Grade Nine"],["teacher","n.","教师",""],["book","n.","书；预订","作动词时 book a ticket 订票"],["pen","n.","钢笔",""],["school","n.","学校","at school 在校上学；at the school 在学校这个地方"],["day","n.","天；白天","复数 days；day by day 一天天"],["week","n.","周",""],["boy","n.","男孩","元音字母 o 前是辅音字母 b，但 oy 属元音字母组合，复数 boys 不加 -es"],["girl","n.","女孩",""],["tree","n.","树",""],["cat","n.","猫",""],["apple","n.","苹果","an apple；a piece of fruit 才表「一份水果」"],["cup","n.","杯子；奖杯",""],["map","n.","地图","复数 maps，读音 /s/"],["bag","n.","袋子；书包",""],["key","n.","钥匙；答案；关键","复数 keys；the key to the door 用 to 不用 of"]]},{"type":"table","title":"以 -s / -x / -ch / -sh 结尾：加 -es","head":["单词","词性/音标","释义","考点"],"rows":[["bus","n.","公共汽车","复数 buses；by bus 乘公交"],["box","n.","盒子",""],["watch","n.","手表；观看","复数 watches；作动词时 watch sb do sth"],["brush","n.","刷子；刷","复数 brushes；a toothbrush 牙刷"],["class","n.","班级；课","复数 classes；集合名词，班集体作整体用单数"],["glass","n.","玻璃；玻璃杯","作材料不可数（a piece of glass），作杯子可数（two glasses）"],["dish","n.","盘子；菜肴","复数 dishes；do the dishes 洗碗"],["dress","n.","连衣裙；穿衣","复数 dresses"],["beach","n.","海滩","复数 beaches；on the beach 在海滩上"],["match","n.","比赛；火柴；相配","复数 matches；a football match"],["fox","n.","狐狸",""],["sandwich","n.","三明治","复数 sandwiches"],["wish","n.","愿望；祝愿","复数 wishes；Best wishes! 常用于书信结尾"],["church","n.","教堂",""]]},{"type":"table","title":"辅音字母 + y 与 -f / -fe 结尾的变化","head":["单词","词性/音标","释义","考点"],"rows":[["city","n.","城市","复数 cities；「辅音字母 + y」变 y 为 i 加 -es"],["country","n.","国家；乡村","复数 countries"],["family","n.","家庭","复数 families；作整体讲谓语用单数：My family is a big one."],["story","n.","故事","复数 stories；tell a story 讲故事"],["baby","n.","婴儿","复数 babies"],["party","n.","聚会；政党","复数 parties；have a party 举行聚会"],["factory","n.","工厂","复数 factories"],["library","n.","图书馆","复数 libraries；borrow books from the library"],["dictionary","n.","词典","复数 dictionaries；look up a word in the dictionary"],["study","n.","书房；学习","作名词复数 studies；作动词第三人称单数 studies"],["leaf","n.","叶子","复数 leaves；例外：roof→roofs、chief→chiefs、belief→beliefs 只加 -s"],["life","n.","生活；生命","复数 lives；lose one’s life 丧生"],["knife","n.","小刀","复数 knives；a knife and fork 一副刀叉"],["wife","n.","妻子","复数 wives"],["shelf","n.","架子","复数 shelves；on the shelf 在架子上"],["half","n.","一半","复数 halves；half an hour 半小时"]]},{"type":"table","title":"不规则复数与单复数同形","head":["单词","词性/音标","释义","考点"],"rows":[["man","n.","男人；人类","复数 men；作定语也用 man：a man doctor 男医生，复数是 men doctors"],["woman","n.","女人","复数 women 读 /ˈwɪmɪn/，与单数读音不同，听力里容易混"],["child","n.","孩子","复数 children；Children’s Day 儿童节"],["foot","n.","脚；英尺","复数 feet；on foot 步行"],["tooth","n.","牙齿","复数 teeth；brush one’s teeth 刷牙"],["mouse","n.","老鼠；鼠标","复数 mice"],["goose","n.","鹅","复数 geese"],["sheep","n.","绵羊","单复数同形：two sheep，不写 sheeps"],["deer","n.","鹿","单复数同形"],["fish","n.","鱼；鱼肉","指条数单复数同形（two fish）；指种类可写 fishes；作鱼肉不可数"],["Chinese","n.","中国人；汉语","单复数同形；a Chinese 一个中国人，the Chinese 中国人（全体）"],["Japanese","n.","日本人；日语","单复数同形"],["police","n.","警察（总称）","本身是复数：The police are coming. 一个警察是 a policeman"],["people","n.","人；人们；民族","作「人们」是复数；作「民族」可数：a great people 一个伟大的民族"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["可数名词的一般复数在词尾加 -s；以 -s、-x、-ch、-sh 结尾加 -es。","名词 + s / es","There are three buses and two boxes in front of the shop.","校门口停着三辆公交车和两个箱子。\n只考拼写：buses、boxes、watches、brushes 都是中考填空题的常客。"],["辅音字母 + y 结尾变 y 为 i 再加 -es；元音字母 + y 结尾直接加 -s。","city → cities，boy → boys","The two cities are famous for their old libraries.","这两座城市因古老的图书馆而闻名。\n先看 y 前面的字母：a、e、i、o、u 是元音字母，此时只加 -s。"],["-f / -fe 结尾一般把 f 变成 v 再加 -es，少数词只加 -s。","knife → knives，roof → roofs","The knives on the shelf are new, but the roofs of the old houses are broken.","架子上的刀是新的，但那些老房子的屋顶破了。\n课标里的例外只有 roof、chief、belief 这几个，考试遇到按「只有 -s」选。"],["不规则复数必须整词记；单复数同形的名词不加 -s。","man → men；sheep → sheep","Two men and three children were waiting for the sheep to come back.","两个男人和三个孩子在等羊群回来。\n句子里出现 two / three / many 时先想「这个词的复数长什么样」。"],["不可数名词不用 a/an，也没有复数；要计量时用「量词 + of + 不可数名词」，复数体现在量词上。","a piece of paper → two pieces of paper","I need two pieces of paper to write down the information.","我需要两张纸把这则信息记下来。\n把 -s 加在 piece、glass、bottle 上，绝不加在 paper、water、information 上。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["There are many sheeps and deers on the hill.","There are many sheep and deer on the hill.","sheep 与 deer 单复数同形，加 -s 是典型错误；同类还有 fish（指条数时）。"],["The teacher gave us some useful informations.","The teacher gave us some useful information.","information 是不可数名词，没有复数形式；要表示「一条信息」用 a piece of information。"],["The police is looking for the man in black.","The police are looking for the man in black.","police 是集合名词，本身表示复数概念，谓语用复数；单个警察是 a policeman。"],["He is an eight-years-old boy.","He is an eight-year-old boy.","「数词 + 名词 + 形容词」用连字符作定语时，中间的名词用单数，不加 -s。"]]}],"questions":[{"id":"eng-vocab-pos-1-q1","type":"choice","stem":"There are two ______ and three ______ in our school.","answer":"A","explain":"library 是「辅音字母 r + y」结尾，变 y 为 i 加 -es，复数是 libraries；gym 是普通名词，直接加 -s。B、D 两项没有把 y 变 i；C 项把 gym 也当成 y 结尾的词来变，但 gym 结尾的 m 不是 y，直接加 -s。","options":["libraries; gyms","librarys; gyms","libraries; gymes","libraryes; gyms"],"difficulty":1,"tags":["名词","复数","-ies"]},{"id":"eng-vocab-pos-1-q2","type":"choice","stem":"The cook needs three ______ and two ______ to cut the meat.","answer":"A","explain":"knife 是 -fe 结尾，变 f 为 v 加 -es，复数是 knives；fork 是普通名词，复数是 forks。B、D 两项没有把 f 变 v；C 项误把 fork 也加 -es，只有以 s、x、ch、sh 结尾的词才加 -es。","options":["knives; forks","knifes; forks","knives; forkes","knifs; forks"],"difficulty":2,"tags":["名词","复数","fe→ves"]},{"id":"eng-vocab-pos-1-q3","type":"choice","stem":"My uncle took a lot of ______ of the West Lake last summer.","answer":"A","explain":"photo 虽以 o 结尾，但它是 photograph 的缩略形式，复数只加 -s，即 photos。B、D 两项拼写不存在；C 项是单数，与 a lot of 后接可数名词复数的要求不符。同类只加 -s 的还有 piano→pianos、radio→radios；而 tomato、potato 以 o 结尾要加 -es。","options":["photos","photoes","photo","photose"],"difficulty":2,"tags":["名词","复数","拼写易错"]},{"id":"eng-vocab-pos-1-q4","type":"choice","stem":"I found some useful ______ about the trip on the Internet.","answer":"A","explain":"information 是不可数名词，不能加 -s，也不能用 a/an 修饰，some 后直接用原形即可。B、D 两项错在把不可数名词变复数；C 项错在加了不定冠词，要表示「一条信息」应说 a piece of information。","options":["information","informations","an information","informationes"],"difficulty":1,"tags":["名词","不可数名词","语法选择"]},{"id":"eng-vocab-pos-1-q5","type":"fill","stem":"There are many ______ (child) playing games on the playground.","answer":"children","explain":"many 后接可数名词复数，child 是不规则复数，复数为 children，不加 -s 也不是 childs。它的所有格是 children’s，如 Children’s Day。","difficulty":1,"tags":["名词","不规则复数","词形变化"]},{"id":"eng-vocab-pos-1-q6","type":"choice","stem":"______ of the students in our class come from Guangzhou, and the rest ______ from other cities.","answer":"A","explain":"most of the students 表示「大多数学生」，students 是复数，谓语用 come；the rest 指剩下的学生，同样视为复数，用 come。B、D 两项误用第三人称单数；C 项 most 前不加 the（the most 是最高级用法）。这一题同时考「名词的数决定谓语」。","options":["Most; come","Most; comes","The most; come","Most of; comes"],"difficulty":3,"tags":["名词","主谓一致","复数"]}]},{"id":"eng-vocab-pos-2","title":"词性索引·名词（二）：不可数名词、量词与集合名词","subtitle":"词性索引 · Nouns (2): Uncountable Nouns, Quantifiers and Collective Nouns","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把「一条建议、两杯牛奶、三张纸」这类量词搭配背成词块，并弄清 family、class 这类集合名词谓语用单数还是复数，名词题就能一次做对。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"不可数名词三不：不加 a/an、不加 -s、不用 many / few 修饰；要计数只能靠量词。","explain":"语法选择的设错点就是 a good advice、many informations 这类。判断办法：先看空格前有没有 a/an 或 many/few，有就是可数名词；看到 much、little、a bit of、a piece of 就一定填不可数名词。"},{"level":"重点","text":"量词搭配是写作填空的高频考点，复数要加在量词上，不加在不可数名词上。","explain":"a glass of milk → two glasses of milk；a pair of shoes → three pairs of shoes。中考常见的是给出 piece、glass、pair、bottle 中的首字母提示，让学生补全量词或变复数，两步都要对。"},{"level":"重点","text":"集合名词作主语时，谓语看「强调整体还是强调成员」：作整体用单数，强调成员可用复数。","explain":"My family is a big one.（一个家庭，单数）；My family are all watching TV.（家里各个成员，复数）。广州中考里 family、class、team、group 若没有明确提示成员，按整体用单数更稳。"},{"level":"次重点","text":"「一条消息、一条建议、一片面包」的固定说法要背下来：a piece of news / advice / bread。","explain":"news、advice、information 都有「一条」的概念，一律用 a piece of，绝不写 a news、an advice。阅读简答题里写「一条建议」常被学生写成 an advice，直接丢分。"},{"level":"次重点","text":"既可数又不可数的词，靠语境判断：paper、glass、chicken、fish、work、time、room。","explain":"Would you like some chicken?（鸡肉，不可数）与 The farmer keeps fifty chickens.（小鸡，可数）。语法题只要出现具体数字或 a/an，就选可数义；出现 much、some 加物质意义，就选不可数义。"},{"level":"了解","text":"不可数名词作主语时谓语用单数，there be 句型用 There is。","explain":"The news is exciting. / There is some milk in the fridge. 学生最容易在 there be 上错：离 be 动词最近的名词决定形式，The news 视为单数。"}]},{"type":"table","title":"常用不可数名词：抽象与状态","head":["单词","词性/音标","释义","考点"],"rows":[["information","n.","信息；资料","不可数：a piece of information；search for information 查资料"],["advice","n.","建议","不可数：a piece of advice；ask sb for advice 向某人征求意见"],["news","n.","消息；新闻","不可数，谓语用单数：The news is good.；a piece of news 一条消息"],["homework","n.","作业","不可数：much homework，不写 homeworks；do one’s homework"],["work","n.","工作；作品","作「工作」不可数；作「作品」可数：the works of Mo Yan"],["progress","n.","进步","不可数：make great progress 取得很大进步，不加 a 也不用 progresses"],["fun","n.","乐趣","不可数：have fun 玩得开心；fun 也可作形容词「有趣的」"],["luck","n.","运气","不可数：Good luck! 祝你好运；形容词是 lucky"],["health","n.","健康","不可数：be in good health；形容词 healthy"],["help","n.","帮助","不可数：ask for help 求助；with the help of 在……的帮助下"],["knowledge","n.","知识","不可数：a lot of knowledge；k 不发音"],["weather","n.","天气","不可数：What fine weather! 不加 a"],["traffic","n.","交通","不可数：heavy traffic 交通拥堵；traffic lights 红绿灯"],["music","n.","音乐","不可数：listen to music；a piece of music 一首乐曲"]]},{"type":"table","title":"常用不可数名词：物质","head":["单词","词性/音标","释义","考点"],"rows":[["water","n.","水","不可数：a glass of water"],["milk","n.","牛奶","不可数：two bottles of milk"],["tea","n.","茶","不可数：a cup of tea"],["juice","n.","果汁","不可数：a glass of orange juice"],["coffee","n.","咖啡","不可数：a cup of coffee"],["bread","n.","面包","不可数：a piece of bread / a loaf of bread 一条面包"],["rice","n.","米饭；大米","不可数：a bowl of rice；rice 无复数"],["meat","n.","肉","不可数：some meat；吃素是 eat no meat"],["sugar","n.","糖","不可数：two spoons of sugar"],["salt","n.","盐","不可数：add some salt to the soup"],["cheese","n.","奶酪","不可数：a piece of cheese"],["paper","n.","纸；报纸；论文","作「纸」不可数（a piece of paper）；作「报纸、论文」可数（a paper）"],["wood","n.","木头；树林","作材料不可数；a wood 一片小树林"],["soup","n.","汤","不可数：a bowl of soup；喝汤用 eat / have soup"]]},{"type":"table","title":"量词搭配：a ... of","head":["单词","词性/音标","释义","考点"],"rows":[["a piece of","phr.","一块（片、张、条）；一条（建议、消息）","复数 two pieces of；搭配 advice、news、paper、bread、music"],["a glass of","phr.","一玻璃杯（的）","复数 two glasses of；搭配 water、milk、juice"],["a cup of","phr.","一杯（的）","复数 two cups of；搭配 tea、coffee"],["a bottle of","phr.","一瓶（的）","复数 two bottles of；搭配 water、milk、orange juice"],["a bowl of","phr.","一碗（的）","复数 two bowls of；搭配 rice、noodles、soup"],["a slice of","phr.","一片（的）","搭配 bread、meat、ham；two slices of bread 两片面包"],["a loaf of","phr.","一条（面包）","复数 two loaves of bread"],["a bar of","phr.","一块（条）","搭配 chocolate、soap"],["a kilo of","phr.","一千克（的）","复数 two kilos of；购物话题常用"],["a packet of","phr.","一包（的）","搭配 salt、sugar、biscuits"],["a pair of","phr.","一双（条、副）","复数 two pairs of；搭配 shoes、socks、trousers、glasses、chopsticks"],["a group of","phr.","一群（的）","a group of students 后面谓语可用单数或复数，考试优先单数"],["a team of","phr.","一队（的）","搭配 doctors、players；team 本身是集合名词"],["a couple of","phr.","两个；几个","约数，等于 a few；a couple of days 两三天"],["a bit of","phr.","一点儿","只接不可数名词：a bit of water；修饰形容词时用 a bit tired"],["a drop of","phr.","一滴（的）","搭配 water、rain；环保话题可用"],["a can of","phr.","一罐（的）","搭配 coke、cola"],["a bag of","phr.","一袋（的）","搭配 rice、apples；two bags of rice"]]},{"type":"table","title":"集合名词","head":["单词","词性/音标","释义","考点"],"rows":[["family","n.","家庭；家人","作整体用单数：My family is big.；强调成员可用复数：My family are all here."],["class","n.","班级；全班同学","The class is small. 班小人少；The class are reading. 全班同学在读书"],["team","n.","队；队伍","our school team 校队；作整体用单数"],["group","n.","组；群","a group of 后接可数名词复数"],["audience","n.","观众；听众","强调整体时谓语用单数"],["public","n.","公众","the public 公众；作主语谓语常用单数"],["government","n.","政府","常作整体，谓语用单数"],["police","n.","警方；警察（总称）","本身是复数：The police are searching the area."],["crowd","n.","人群","a crowd of people；谓语多用单数"],["company","n.","公司；陪伴","a company 一家公司；keep sb company 陪伴某人"],["society","n.","社会","常作整体，谓语用单数；in modern society 在现代社会"],["army","n.","军队","an army of 大批的；作整体用单数"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["不可数名词不能加 a/an、不能加 -s，也不能用 many / few 修饰。","much / little / a lot of + 不可数名词","There is not much milk in the bottle, so we need to buy some.","瓶里的牛奶不多了，我们得去买一些。\n先看空格前是 many 还是 much，这是判断可数不可数最快的一步。"],["计量不可数名词用「量词 + of」结构，复数变化在量词上。","a piece of → two pieces of","I would like two pieces of bread and a glass of milk for breakfast.","我早餐想吃两片面包和一杯牛奶。\n写出复数后回读一遍：pieces 有 -s，bread 不能有 -s。"],["集合名词视为整体时谓语用单数，强调成员时可用复数。","My family is / are ...","My family is not big, but my family are all interested in sports.","我家不大，但家里人都对运动感兴趣。\n考试里没有明确提示成员时，按整体单数更稳；主语是 the police 时一律用复数。"],["同一名词可数不可数常有两义，要以语境定。","chicken 鸡肉（不可数）/ 小鸡（可数）","We had some chicken for lunch, and my grandpa keeps twenty chickens on his farm.","我们午饭吃了些鸡肉，我爷爷在农场养了二十只鸡。\n出现具体数字、a/an、many 就是可数义；出现 much、a piece of、some 加物质义就是不可数义。"],["不可数名词作主语，谓语用单数；there be 句型看紧跟 be 的那个名词。","The news is ... / There is some ...","The news about the football match is exciting, and there is still some time to buy tickets.","这场足球赛的消息令人激动，而且还有时间买票。\nnews、information、advice 结尾有 s，但都是单数，千万别被 -s 骗了。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["My father gave me a good advice about studying English.","My father gave me a piece of good advice about studying English.","advice 不可数，不能直接用 a 修饰；「一条建议」说 a piece of advice，也可用 some advice。"],["I bought two breads and three milks for breakfast.","I bought two pieces of bread and three bottles of milk for breakfast.","bread 与 milk 都不可数，需要靠量词计数，复数加在 piece、bottle 上。"],["The news about our school are very good.","The news about our school is very good.","news 是不可数名词，虽以 -s 结尾但按单数处理，谓语用 is。"],["There are much water in the bottle.","There is much water in the bottle.","water 不可数，there be 句型的 be 用单数；much 也只能修饰不可数名词。"]]}],"questions":[{"id":"eng-vocab-pos-2-q1","type":"choice","stem":"I would like two ______ of milk, please.","answer":"A","explain":"milk 不可数，计数要用「量词 + of」，复数加在量词上，two 后接 glasses。B 项是单数，与 two 不一致；C 项拼写错误，以 s 结尾的名词复数加 -es 即 glasses；D 项用了所有格，不能表示数量。","options":["glasses","glass","glasss","glass’s"],"difficulty":1,"tags":["名词","不可数名词","量词"]},{"id":"eng-vocab-pos-2-q2","type":"choice","stem":"Here is ______ for you: you should read English aloud every morning.","answer":"A","explain":"「一条建议」的固定说法是 a piece of advice。B 项错在 advice 不可数，不能用 an；C 项错在 advice 没有复数形式；D 项语序和结构都不成立。如果要表达「一些建议」，用 some advice 也可以，但没有 some advices 这种形式。","options":["a piece of advice","an advice","some advices","advice of a piece"],"difficulty":2,"tags":["名词","不可数名词","固定搭配"]},{"id":"eng-vocab-pos-2-q3","type":"choice","stem":"My grandfather keeps more than fifty ______ on his farm.","answer":"A","explain":"此处指「五十多只小鸡」，是可数名词，复数 chickens。B 项 chicken 作「鸡肉」讲时不可数，与 fifty 不搭配；C 项拼写错误，chicken 直接加 -s；D 项 chick 虽也指小鸡，但句中已说 fifty，仍要用复数形式。","options":["chickens","chicken","chickenes","chick"],"difficulty":2,"tags":["名词","可数与不可数","语境判断"]},{"id":"eng-vocab-pos-2-q4","type":"choice","stem":"The news about the school trip ______ exciting, and every student ______ looking forward to it.","answer":"A","explain":"news 是不可数名词，按单数处理，谓语用 is；every student 是单数概念，谓语也用 is。B、C 两项把 news 当复数，是被词尾的 -s 误导；D 项把 every student 当复数，实际 every、each 修饰的名词都按单数。","options":["is; is","are; are","is; are","are; is"],"difficulty":2,"tags":["名词","主谓一致","不可数名词"]},{"id":"eng-vocab-pos-2-q5","type":"fill","stem":"I am thirsty. Please give me a ______ of water.（填一个量词名词，用单数）","answer":"glass|cup|bottle","explain":"water 不可数，「一杯水、一瓶水」用 a glass of water / a cup of water / a bottle of water，量词用单数，因为前面有 a。注意 water 本身不加 -s。","difficulty":1,"tags":["名词","量词","不可数名词"]},{"id":"eng-vocab-pos-2-q6","type":"choice","stem":"My family ______ all fond of Guangzhou food, and my family ______ a happy one.","answer":"A","explain":"第一空强调家里每个人，谓语用复数 are；第二空把家看作一个整体，用单数 is。B 项正好相反；C、D 两项没有区分整体与成员两种用法。记住考点：集合名词作主语时，看句子是在说「一群人」还是「一个单位」。","options":["are; is","is; are","are; are","is; is"],"difficulty":3,"tags":["名词","集合名词","主谓一致"]}]},{"id":"eng-vocab-pos-3","title":"词性索引·动词：及物性、动词短语与四类万能搭配","subtitle":"词性索引 · Verbs: Transitive, Intransitive and Verb Phrases","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"记住「哪些动词必须带宾语、哪些不能有被动、哪些介词固定」，再把 make / do / take / have 四类搭配成块背下，语法选择里的动词题就有依据可判。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"及物动词后必须带宾语，不及物动词不能直接跟宾语，要加介词。","explain":"语法选择常把介词设成考点：listen 后必须有 to，wait 后必须有 for，arrive 后必须有 at/in。判断办法：把这个动词的常用搭配当作一个整体词块来记，不要单独记动词。"},{"level":"重点","text":"不及物动词没有被动语态，happen、take place、appear、rise、come true 都是重灾区。","explain":"被动语态题的设错方式就是写 was happened、was taken place。判断办法：想一想这个动作能不能「被某人做」——事故只能自己发生，不能被发生。"},{"level":"重点","text":"make / do / take / have 的搭配分工：make 造出结果，do 做事情，take 取时间与动作名词，have 有或进行某项活动。","explain":"这是语法选择与写作填空的高频区：make a mistake、do one’s best、take care of、have fun 都是固定词块。判断办法：把名词与动词配成对背，如 mistake 只跟 make、homework 只跟 do。"},{"level":"次重点","text":"短语动词的宾语位置：名词可前可后，代词必须放中间。","explain":"pick up the pen = pick the pen up，但只能说 pick it up，不能说 pick up it。同理 turn on/off、put on、take off、wake up、look up。被动语态里代词位置也要注意。"},{"level":"次重点","text":"只接动名词作宾语的常见动词：enjoy、finish、mind、keep、practise、suggest。","explain":"语法选择里出现 enjoy do 就错，必须 enjoy doing。反面提醒：want、hope、decide、plan、would like 后接 to do，两种动词不要混。"},{"level":"了解","text":"make 表「使、让」时用 make sb do sth，变被动后要补回 to。","explain":"The teacher made us read aloud. 变被动为 We were made to read aloud. 这是被动语态与使役动词结合的常考点，也是学生最容易漏 to 的地方。"}]},{"type":"table","title":"常见及物动词（必须带宾语）","head":["单词","词性/音标","释义","考点"],"rows":[["enjoy","v.","享受；喜欢","接动名词：enjoy reading；enjoy oneself 玩得开心"],["finish","v.","完成","接动名词：finish doing sth；finish 后不接 to do"],["need","v.","需要","need to do（人作主语）；need doing（物作主语，表被动）"],["want","v.","想要","want to do sth；want sb to do sth"],["borrow","v.","借入","borrow sth from sb；与 lend sth to sb 方向相反"],["lend","v.","借出","lend sb sth = lend sth to sb"],["bring","v.","带来","bring sth to sb；与 take（带走）方向相反"],["invite","v.","邀请","invite sb to do sth；invite sb to a party"],["remember","v.","记得","remember to do 记得去做；remember doing 记得做过"],["forget","v.","忘记","forget to do 忘了去做；forget doing 忘了做过"],["teach","v.","教","teach sb sth；teach sb to do sth；过去式 taught"],["choose","v.","选择","choose to do sth；过去式 chose，过去分词 chosen"],["discuss","v.","讨论","及物，直接接宾语：discuss the plan，不加 about"],["reach","v.","到达；伸手够到","reach 后直接接地点，不加 at/in：reach Guangzhou"],["prefer","v.","更喜欢","prefer A to B；prefer doing to doing"],["practise","v.","练习","英式拼写 practise（动词），美式为 practice；practise doing sth"]]},{"type":"table","title":"常见不及物动词（不直接接宾语）","head":["单词","词性/音标","释义","考点"],"rows":[["arrive","v.","到达","arrive in + 大地点，arrive at + 小地点；不与 reach 混用"],["happen","v.","发生","无被动；sth happens to sb 某事发生在某人身上"],["listen","v.","听","listen to sb/sth；listen 单独用表示「听着」"],["look","v.","看；看起来","look at 看；look like 看起来像；look after 照顾"],["wait","v.","等待","wait for sb/sth；can’t wait to do 迫不及待做某事"],["rise","v.","上升；升起","不及物，无被动；The sun rises in the east."],["come","v.","来","come from 来自；come true 实现（无被动）"],["go","v.","去","go swimming 去做某事；have gone to 去了（还没回）"],["sleep","v.","睡觉","sleep well 睡得好；go to sleep 入睡"],["stay","v.","停留；保持","stay at home；stay healthy 保持健康"],["laugh","v.","笑","laugh at sb 嘲笑某人；laugh 后不直接接宾语"],["sit","v.","坐","sit down；现在分词 sitting（双写 t）"],["stand","v.","站；忍受","stand up 起立；can’t stand doing 受不了做某事"],["fall","v.","落下；跌倒","fall asleep 入睡；fall ill 生病；过去式 fell"]]},{"type":"table","title":"高频 v. + prep. 搭配","head":["单词","词性/音标","释义","考点"],"rows":[["look after","phr.","照顾","= take care of；宾语是代词时放 after 后：look after them"],["look for","phr.","寻找","强调动作；find 强调结果"],["look forward to","phr.","盼望","to 是介词，后接名词或动名词：look forward to seeing you"],["listen to","phr.","听","listen 是不及物动词，必须有 to"],["wait for","phr.","等待","wait for sb to do sth"],["arrive at / in","phr.","到达","小地点用 at，大地点（城市、国家）用 in"],["laugh at","phr.","嘲笑","被动：be laughed at 被人嘲笑"],["talk about","phr.","谈论","talk about sth with sb"],["think about","phr.","考虑","think about doing sth；think of 想起、认为"],["depend on","phr.","依靠；取决于","depend on sb to do sth；口语常作 It depends."],["belong to","phr.","属于","无被动语态：The book belongs to me."],["get on with","phr.","与……相处","get on well with sb 与某人相处得好"],["come from","phr.","来自","= be from；Where do you come from?"],["agree with","phr.","同意（某人、意见）","同意某人用 agree with sb；同意计划用 agree to the plan"],["ask for","phr.","请求；要求","ask sb for help 向某人求助"],["hear from","phr.","收到……的来信","与 hear of（听说）区分"],["worry about","phr.","担心","be worried about 也表示担心，两式都对"],["take part in","phr.","参加（活动）","指参加活动；join 指加入组织、团体"]]},{"type":"table","title":"make 与 do 的固定搭配","head":["单词","词性/音标","释义","考点"],"rows":[["make friends","phr.","交朋友","make friends with sb；friend 要用复数"],["make a decision","phr.","做决定","= decide；也可说 make up one’s mind"],["make sure","phr.","确保","make sure that ...；后接从句用一般现在时表将来"],["make progress","phr.","取得进步","progress 不可数，不加 a 也不加 -s"],["make a mistake","phr.","犯错误","mistake 跟 make，不跟 do"],["make a noise","phr.","发出噪声","也可说 make noises；Don’t make a noise."],["make up","phr.","编造；组成；化妆","be made up of 由……组成"],["make fun of","phr.","取笑","后接人：make fun of others"],["make it","phr.","成功；赶到","口语高频：I believe you can make it."],["be made of / from","phr.","由……制成","看得出材料用 of，看不出用 from"],["do homework","phr.","做作业","homework 不可数，不能说 do homeworks"],["do sports","phr.","做运动","= play sports；sports 恒用复数"],["do the dishes","phr.","洗碗","也可说 wash the dishes；dish 用复数"],["do one’s best","phr.","尽最大努力","do one’s best to do sth"],["do well in","phr.","在……方面做得好","= be good at；主语是人时用 do well in"],["do some shopping","phr.","购物","go shopping 更常用；同类 do some cleaning 打扫"],["do harm to","phr.","对……有害","= be harmful to；环保话题常用"],["do sb a favour","phr.","帮某人一个忙","= give sb a hand；更常用 help sb"]]},{"type":"table","title":"take 与 have 的固定搭配","head":["单词","词性/音标","释义","考点"],"rows":[["take a walk","phr.","散步","= go for a walk"],["take a rest","phr.","休息一下","= have a rest"],["take photos","phr.","拍照","take photos of sb/sth；photo 复数 photos"],["take care of","phr.","照顾","= look after；take good care of 好好照顾"],["take place","phr.","发生；举行","无被动语态；指按计划发生，happen 多指偶然"],["take a bus","phr.","乘公交车","= go by bus；take a taxi 乘出租车"],["take medicine","phr.","吃药","用 take，不用 eat：take the medicine three times a day"],["take a message","phr.","捎口信","电话用语：Can I take a message?"],["take notes","phr.","做笔记","note 用复数；take notes of sth"],["take one’s time","phr.","不着急；慢慢来","Take your time. 别急。"],["take it easy","phr.","别紧张；放轻松","安慰他人时用：Take it easy. Everything will be fine."],["have fun","phr.","玩得开心","= enjoy oneself = have a good time"],["have a look","phr.","看一看","have a look at sth"],["have a try","phr.","试一试","= try it；鼓励别人时常用"],["have a cold","phr.","感冒","cold 前用 a；have a headache 头痛"],["have breakfast","phr.","吃早餐","三餐前不加冠词：have breakfast / lunch / dinner"],["have lessons","phr.","上课","have an English lesson 上一节英语课"],["have a talk","phr.","谈话","have a talk with sb about sth"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["及物动词直接跟宾语；不及物动词要加介词才接宾语。","及物：enjoy sth；不及物：listen to sth","We arrived in Beijing late at night, and we listened to some music in the hotel.","我们深夜到达北京，在酒店里听了些音乐。\n只有 reach 后不加介词：reach Beijing 才是对的。"],["不及物动词不能用于被动语态。","happen / take place / appear / rise 无被动","The accident happened last night, and nobody was hurt.","事故发生在昨晚，没有人受伤。\n看到 was happened、was taken place 就直接排除，这是被动语态题最常见的错项。"],["短语动词的宾语是代词时必须放在动词与介词/副词之间。","pick up the pen = pick the pen up；pick it up","Your pen is on the floor. Please pick it up.","你的钢笔在地上，请把它捡起来。\n只有「动词 + 副词」结构的短语才能拆开，look after、listen to 这类「动词 + 介词」不能拆。"],["make 表「使、让」时接不带 to 的不定式，变被动要补回 to。","make sb do sth → sb be made to do sth","Our teacher made us read the text aloud, and we were made to read it three times.","老师让我们朗读课文，我们被要求读了三遍。\n主动语态漏 to 是常态，被动语态漏 to 就是错，写被动句时先检查 to。"],["只接动名词作宾语的动词要整串记：enjoy、finish、mind、keep、practise。","enjoy doing sth","I enjoy reading English stories, and I keep practising speaking every day.","我喜欢读英语故事，并且每天坚持练口语。\n写作里用 enjoy doing、finish doing 比用 want to do 更出彩，也是得分句型。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["A traffic accident was happened near our school yesterday.","A traffic accident happened near our school yesterday.","happen 是不及物动词，没有被动语态；同类还有 take place、appear、rise、come true。"],["We discussed about the plan for the school trip.","We discussed the plan for the school trip.","discuss 是及物动词，直接接宾语，不加 about；要说 about 就用 talk about the plan。"],["Your book is on the desk. Please pick up it.","Your book is on the desk. Please pick it up.","短语动词的宾语是代词时，代词要放在动词与副词之间，即 pick it up。"],["I did a few mistakes in yesterday’s English test.","I made a few mistakes in yesterday’s English test.","「犯错误」是 make a mistake，固定搭配；do 用于 do homework、do the dishes 这类事情性搭配。"]]}],"questions":[{"id":"eng-vocab-pos-3-q1","type":"choice","stem":"A traffic accident ______ near our school gate last Friday afternoon.","answer":"A","explain":"happen 是不及物动词，不能用于被动语态，排除 B、C 两项；句末有 last Friday afternoon，是一般过去时的标志，用 happened。D 项是现在完成时，与明确的过去时间状语连用是典型错误。","options":["happened","was happened","is happened","has happened"],"difficulty":2,"tags":["动词","不及物动词","被动语态"]},{"id":"eng-vocab-pos-3-q2","type":"choice","stem":"Please listen ______ the teacher carefully and take notes in class.","answer":"A","explain":"listen 是不及物动词，必须加介词 to 才能接宾语 the teacher。B 项 at 用于 look at（看）；C 项 for 用于 wait for、look for；D 项 with 用于 agree with、talk with。判断办法：listen 永远搭配 to，这是固定词块。","options":["to","at","for","with"],"difficulty":1,"tags":["动词","v.+prep.","固定搭配"]},{"id":"eng-vocab-pos-3-q3","type":"choice","stem":"We must ______ our best to help the old man who lives alone.","answer":"A","explain":"「尽最大努力」是 do one’s best to do sth，固定搭配用 do。B 项 make 的常见搭配是 make friends、make a decision、make progress；C 项 take 用于 take care of、take a walk；D 项 have 用于 have fun、have a rest。把名词与动词配成对背，这类题就不会犹豫。","options":["do","make","take","have"],"difficulty":1,"tags":["动词","do 的搭配","固定搭配"]},{"id":"eng-vocab-pos-3-q4","type":"choice","stem":"Don’t worry. I will ______ good care of your dog while you are away.","answer":"A","explain":"「好好照顾」是 take good care of sb / sth，等于 look after sb well。B 项 make 与 care 不搭配；C 项 do 的搭配是 do one’s best、do the dishes；D 项 have 的搭配是 have a look、have fun。注意 care 前可加 good、much 等修饰语。","options":["take","make","do","have"],"difficulty":2,"tags":["动词","take 的搭配","固定搭配"]},{"id":"eng-vocab-pos-3-q5","type":"choice","stem":"Your schoolbag is on the floor and the books are all over the place. Please ______.","answer":"A","explain":"「把书包捡起来」用 pick up，宾语是代词 it 时必须放在 pick 与 up 之间，即 pick it up。B 项把代词放在后面，位置错误；C 项 take up 意思是「开始从事、占据」，与语境不符；D 项 them 指代 the books，与前面 the schoolbag 不一致。","options":["pick it up","pick up it","take it up","pick up them"],"difficulty":3,"tags":["动词","短语动词","代词位置"]},{"id":"eng-vocab-pos-3-q6","type":"fill","stem":"The sports meeting will ______ (take) place next Monday morning.","answer":"take","explain":"will 后接动词原形，所以填 take。take place 表示「举行、发生」，是不及物动词短语，没有被动语态，也不能写成 be taken place。它与 happen 的区别是：take place 多指按计划发生，happen 多指偶然发生。","difficulty":2,"tags":["动词","动词形式","take place"]}]},{"id":"eng-vocab-pos-4","title":"词性索引·形容词：反义配对、-ed / -ing 与位置","subtitle":"词性索引 · Adjectives: Opposites, -ed / -ing Forms and Positions","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把形容词按「成对反义」和「-ed 修饰人、-ing 修饰物」两组分别记牢，再解决形容词作定语和作表语的位置问题，形容词题就能稳拿。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"-ed 形容词修饰人（感到……的），-ing 形容词修饰事物（令人……的），这是语法选择的高频陷阱。","explain":"The film is boring.（电影令人厌烦）与 I feel bored.（我感到厌烦）。快速判断：看空格后面的名词或句子的主语是人还是物——人用 -ed，物用 -ing；但 a surprising result 中结果虽是物，也用 -ing，因为它是「令人惊讶的」。"},{"level":"重点","text":"形容词作定语时放在名词前；修饰 something、anything、nothing 等不定代词时必须后置。","explain":"something important、nothing new、anything else。语法选择的设错方式就是把 important 放在 something 前，学生一读就顺口，恰恰是错的。"},{"level":"重点","text":"系动词后接形容词，不接副词；look、sound、smell、taste、feel、become、get、turn、seem 都是系动词。","explain":"The soup tastes delicious.（不能写 deliciously）；He looks happy.（不能写 happily）。但要区分：The man looked at me angrily. 这里 look 是实义动词「看」，所以用副词 angrily 修饰。"},{"level":"次重点","text":"表语形容词只作表语，不能放在名词前作定语：afraid、asleep、awake、alone、ill、glad、well。","explain":"可以说 The baby is asleep，不能说 the asleep baby（要用 the sleeping baby）；可以说 He is ill，但「生病的男孩」要说 the sick boy。写作里出现 the ill man 是明显的错。"},{"level":"次重点","text":"形容词与副词的转换是写作填空的固定考点：good→well、happy→happily、careful→carefully、easy→easily。","explain":"判断办法只有一句：看这个空修饰的是名词还是动词。修饰名词用形容词，修饰动词用副词。He is a careful driver. / He drives carefully."},{"level":"了解","text":"形容词比较级与 as ... as 结构里只能放形容词或副词的原级。","explain":"as careful as、not as tall as。语法选择常把 more careful 放进 as ... as 中间设错，看到 as ... as 就先检查中间是不是原级。"}]},{"type":"table","title":"成对反义形容词（一）：大小、长短、轻重","head":["单词","词性/音标","释义","考点"],"rows":[["big","adj.","大的","反义 small；big 多指体积、规模"],["small","adj.","小的","反义 big；small 也指年龄小"],["tall","adj.","高的（人、树）","反义 short；指建筑物高用 tall 或 high"],["short","adj.","矮的；短的","反义 tall（人或树）、long（长度）"],["long","adj.","长的","反义 short；how long 问长度与时间"],["heavy","adj.","重的；大量的","反义 light；heavy rain 大雨、heavy traffic 交通拥堵"],["light","adj.","轻的；明亮的","反义 heavy（重量）或 dark（明暗），要看语境"],["new","adj.","新的","反义 old；the new one 新的那个"],["old","adj.","旧的；年老的","反义 new 或 young；How old are you? 问年龄"],["young","adj.","年轻的","反义 old；the young 年轻人（整体）"],["fast","adj.","快的","作形容词与副词同形：a fast train / run fast"],["slow","adj.","慢的","反义 fast；副词 slowly"],["hot","adj.","热的；辣的","反义 cold；比较级 hotter（双写 t）"],["cold","adj.","冷的；冷淡的","反义 hot；作名词 have a cold 感冒"],["warm","adj.","温暖的","反义 cool；warm-hearted 热心的"],["cool","adj.","凉爽的；酷的","反义 warm；口语也表「很棒」"]]},{"type":"table","title":"情感与评价形容词","head":["单词","词性/音标","释义","考点"],"rows":[["happy","adj.","高兴的","反义 sad/unhappy；副词 happily"],["sad","adj.","伤心的","反义 happy；be sad about sth"],["angry","adj.","生气的","be angry with sb（对人）／be angry at sth（对事）"],["shy","adj.","害羞的","Don’t be shy. 别害羞；比较级 shier 或 shyer"],["brave","adj.","勇敢的","It is brave of sb to do sth 某人做某事很勇敢"],["kind","adj.","善良的；友好的","be kind to sb 对某人友好；It is kind of you to help."],["honest","adj.","诚实的","to be honest 说实话；h 不发音，前用 an"],["patient","adj.","有耐心的","be patient with sb 对某人有耐心"],["strict","adj.","严格的","be strict with sb 对人严格；be strict in sth 对事严格"],["serious","adj.","严肃的；认真的","be serious about sth 认真对待某事"],["proud","adj.","自豪的","be proud of sb/sth"],["nervous","adj.","紧张的","be nervous about the exam"],["lonely","adj.","孤独的","lonely 可作定语；alone 只作表语，见分组四"],["lucky","adj.","幸运的","be lucky to do sth；副词 luckily"],["careful","adj.","仔细的","be careful with sth；反义 careless"],["polite","adj.","有礼貌的","It is polite to do sth；副词 politely"],["friendly","adj.","友好的","以 -ly 结尾却是形容词：be friendly to sb"],["useful","adj.","有用的","反义 useless；It is useful to do sth"]]},{"type":"table","title":"-ed / -ing 分词形容词对照","head":["单词","词性/音标","释义","考点"],"rows":[["interesting","adj.","有趣的（令人感兴趣）","修饰事物：an interesting book"],["interested","adj.","感兴趣的（人）","be interested in；主语是人"],["exciting","adj.","令人激动的","an exciting match 令人激动的比赛"],["excited","adj.","激动的（人）","We were excited at the news."],["surprising","adj.","令人惊讶的","a surprising result 出人意料的结果"],["surprised","adj.","感到惊讶的（人）","I was surprised to see him."],["boring","adj.","令人厌烦的","The talk was boring."],["bored","adj.","感到厌烦的（人）","I felt bored during the talk."],["tiring","adj.","累人的","The trip was tiring but happy."],["tired","adj.","感到疲倦的（人）","We were tired after the trip."],["worrying","adj.","令人担忧的","worrying news 令人担忧的消息"],["worried","adj.","感到担忧的（人）","be worried about"],["moving","adj.","感人的","a moving story 感人的故事"],["moved","adj.","受感动的（人）","We were deeply moved."],["amazing","adj.","令人惊奇的","What an amazing view!"],["amazed","adj.","感到惊奇的（人）","be amazed at sth"],["relaxing","adj.","令人放松的","a relaxing weekend"],["relaxed","adj.","感到放松的（人）","feel relaxed 感到放松"]]},{"type":"table","title":"表语形容词与常见形容词后缀例词","head":["单词","词性/音标","释义","考点"],"rows":[["afraid","adj.","害怕的","只作表语：be afraid of；不说 an afraid boy"],["asleep","adj.","睡着的","只作表语：fall asleep；定语用 sleeping"],["awake","adj.","醒着的","只作表语：stay awake 保持清醒"],["alone","adj./adv.","独自（的）","live alone 独居（客观）；lonely 孤独（感受）"],["ill","adj.","生病的","作表语：be ill；定语用 sick，如 a sick boy"],["glad","adj.","高兴的","be glad to do sth 很高兴做某事"],["sorry","adj.","抱歉的；难过的","be sorry for／be sorry to do sth"],["ready","adj.","准备好的","be ready for sth／be ready to do sth"],["sure","adj.","确信的","be sure of／be sure to do sth"],["fond","adj.","喜爱的","be fond of sth 喜爱某物"],["helpful","adj.","有帮助的","后缀 -ful 表「充满」；be helpful to sb"],["careless","adj.","粗心的","后缀 -less 表「无」；反义 careful"],["dangerous","adj.","危险的","后缀 -ous；It is dangerous to swim here."],["healthy","adj.","健康的","后缀 -y；keep healthy 保持健康"],["active","adj.","积极的；活跃的","后缀 -ive；take an active part in 积极参加"],["comfortable","adj.","舒适的","后缀 -able；比较级 more comfortable"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["-ed 形容词表示人的感受，-ing 形容词表示事物给人的感受。","sb be interested in sth；sth is interesting","The film was so boring that most of us felt bored and left early.","这部电影太无聊了，我们大多数人感到厌烦，很早就离开了。\n看主语：主语是人用 -ed，主语是事或物用 -ing；但 a surprised look（惊讶的表情）也成立，因为表情反映人的感受。"],["形容词修饰不定代词时要后置。","something / anything / nothing / everything + 形容词","I have something important to tell you about the school trip.","关于这次学校旅行，我有重要的事情要告诉你。\n记住顺序「不定代词在前、形容词在后」，else 也要放后面：anything else。"],["系动词后接形容词作表语。","be / look / sound / smell / taste / feel / become / get / turn / seem + adj.","The soup tastes delicious, and the music sounds beautiful.","这汤味道很好，音乐听起来很美。\n只有 look at、listen to 这类实义动词才用副词修饰：He looked at me angrily."],["形容词作定语时的常见顺序：限定词—大小—新旧—颜色—国别—材料。","a big old brown wooden desk","There is a big old brown wooden desk in the corner of the room.","房间角落里有一张很大的旧棕色木桌。\n中考不会考很长的堆叠，只要记住大小在新旧、颜色之前即可。"],["表语形容词不作前置定语，需要时换用同义的定语形容词。","be asleep → a sleeping baby；be ill → a sick boy","The baby is asleep in the next room, so keep quiet.","宝宝在隔壁房间睡着了，所以请保持安静。\nalone（独自）与 lonely（孤独）一个说事实、一个说感受，作文里常常有区分价值。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["This English story is very interested.","This English story is very interesting.","主语是 story（事物），表示「令人感兴趣」，要用 -ing 形式 interesting；interested 只能形容人。"],["I am interesting in Chinese history.","I am interested in Chinese history.","主语是 I（人），表示「我自己感兴趣」，要用 -ed 形式，且固定搭配是 be interested in。"],["He sings very good, so he is popular in our class.","He sings very well, so he is popular in our class.","修饰动词 sing 要用副词 well，good 是形容词，只能修饰名词或作表语。"],["I have important something to do this afternoon.","I have something important to do this afternoon.","形容词修饰不定代词 something 时必须后置，不能放在前面，这与「形容词 + 名词」的顺序相反。"]]}],"questions":[{"id":"eng-vocab-pos-4-q1","type":"choice","stem":"The story is so ______ that all of us are ______ in it.","answer":"A","explain":"第一空主语是 the story（事物），用 -ing 形式 interesting，表示「令人感兴趣的」；第二空主语是 all of us（人），用 -ed 形式 interested，即 be interested in。B 项正好颠倒；C、D 两项没有区分「令人……」和「感到……」。","options":["interesting; interested","interested; interesting","interesting; interesting","interested; interested"],"difficulty":2,"tags":["形容词","-ed/-ing","系动词"]},{"id":"eng-vocab-pos-4-q2","type":"choice","stem":"I have ______ to tell you about our new English teacher.","answer":"A","explain":"肯定句用 something，形容词修饰不定代词时后置，所以要写 something important。B 项语序错误；C 项 anything 一般用于否定句与疑问句；D 项既用错词又用错语序。","options":["something important","important something","anything important","important anything"],"difficulty":1,"tags":["形容词","不定代词","语序"]},{"id":"eng-vocab-pos-4-q3","type":"choice","stem":"The soup ______ delicious. Would you like some?","answer":"A","explain":"taste 在此是系动词，后接形容词 delicious 作表语，主语 The soup 是第三人称单数，用 tastes。B 项系动词没有被动语态；C 项 well 是副词，不能作系动词的表语（作系动词表语时只能用形容词）；D 项主谓不一致。","options":["tastes","is tasted","tastes well","taste"],"difficulty":2,"tags":["形容词","系动词","主谓一致"]},{"id":"eng-vocab-pos-4-q4","type":"choice","stem":"We were all ______ at the ______ news that our team had won the match.","answer":"A","explain":"第一空主语 We 是人，用 surprised 表示「感到惊讶」；第二空修饰 news，用 surprising 表示「令人惊讶的」。B 项颠倒了两者的用法；C、D 两项没有区分人的感受与事物的性质。","options":["surprised; surprising","surprising; surprised","surprised; surprised","surprising; surprising"],"difficulty":2,"tags":["形容词","-ed/-ing","表语"]},{"id":"eng-vocab-pos-4-q5","type":"choice","stem":"The old man lives ______ in a small village, but he never feels ______.","answer":"A","explain":"alone 表示「独自一人」，是客观状态，可作副词修饰 lives；lonely 表示「孤独的」，是主观感受，作系动词 feel 的表语。B 项把两者颠倒；C 项第二空用 alone 只说「不感到独自」，与 but 引出的转折意味不搭；D 项第一空 lonely 不能作副词修饰 lives。","options":["alone; lonely","lonely; alone","alone; alone","lonely; lonely"],"difficulty":3,"tags":["形容词","易混词","alone/lonely"]},{"id":"eng-vocab-pos-4-q6","type":"fill","stem":"The two boys are ______ (interest) in Chinese history.","answer":"interested","explain":"主语是人，表示「对……感兴趣」，用 -ed 形式的 interested，固定搭配 be interested in。如果主语是物（如 The book is ...），才用 interesting。","difficulty":1,"tags":["形容词","-ed/-ing","词形变化"]}]},{"id":"eng-vocab-pos-5","title":"词性索引·副词：频率、方式、连接与易混副词","subtitle":"词性索引 · Adverbs: Frequency, Manner, Linking and Confusables","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把频率副词的位置、方式副词的构成、连接副词的逻辑作用，以及 hard/hardly 这类「形近义不同」的副词一次理清，副词题从靠语感变成靠规则。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"频率副词的位置：be 动词、助动词、情态动词之后，实义动词之前。","explain":"She is always late.（always 在 is 后）；He always gets up early.（always 在 gets 前）。语法选择最爱设的是 She always is late 和 He gets always up 这两种错位。"},{"level":"重点","text":"hard/hardly、late/lately、near/nearly、high/highly 等「形容词加 -ly 后意义大变」的副词是高频陷阱。","explain":"He works hard.（努力工作）与 He hardly works.（几乎不工作）意思完全相反。完形填空常靠这一对词设置语境反转：上文说「他很努力」，下文却用 hardly 表「几乎没有」，学生按 hard 理解就会选错逻辑关系。"},{"level":"重点","text":"形容词修饰名词，副词修饰动词、形容词和另一个副词。","explain":"写作填空的固定考法：a careful driver（形容词修饰名词）／drives carefully（副词修饰动词）。判断办法：这个空修饰的中心词是名词就用形容词，是动词就用副词。"},{"level":"次重点","text":"连接副词 however、therefore、besides、otherwise、instead 后面常加逗号，用来衔接两个句子。","explain":"完形填空靠它们判断逻辑：however 表转折、therefore 表结果、besides 表递进、otherwise 表「否则」。写作里用上一个 however 和一个 besides，是明显的加分点。"},{"level":"次重点","text":"already、yet、just、ever、never、before 多与现在完成时连用，位置在 have / has 之后。","explain":"I have already finished my homework. / Have you finished it yet? already 用于肯定句，yet 用于否定句和疑问句且放句末。语法选择里这两个词常与现在完成时捆在一起考。"},{"level":"了解","text":"多个副词同现时，顺序一般是「方式—地点—时间」。","explain":"She sang beautifully at the party last night. 方式副词紧挨动词，时间副词放最后。写作中若句子结尾堆了三个状语，按这个顺序排就不会错。"}]},{"type":"table","title":"频率副词与频率短语","head":["单词","词性/音标","释义","考点"],"rows":[["always","adv.","总是","频率最高；位置在 be 后、实义动词前"],["usually","adv.","通常","常与一般现在时连用，表示习惯"],["often","adv.","经常","How often 问频率；比较级 more often"],["sometimes","adv.","有时","注意与 some times（几次）区分：前者是频率副词，后者是名词短语"],["seldom","adv.","很少","半否定词，反意疑问句按否定句处理"],["never","adv.","从不","本身否定，不能再加 not"],["hardly ever","phr.","几乎从不","等于 almost never；注意 hardly 不是 hard 的副词"],["once a week","phr.","每周一次","How often 的常用答语；once、twice、three times"],["twice a month","phr.","每月两次","twice 不能用 two times 随意替换，虽同义但考试多用 twice"],["every day","phr.","每天","作时间状语；everyday 是形容词「日常的」"],["every other day","phr.","每隔一天","等于 every two days 的说法更清楚"],["now and then","phr.","偶尔","= from time to time = at times"],["from time to time","phr.","不时地","作文里替换 sometimes 的不错选择"],["again and again","phr.","反复地","强调重复，常与 try、read 连用"]]},{"type":"table","title":"方式副词","head":["单词","词性/音标","释义","考点"],"rows":[["quickly","adv.","迅速地","由 quick + ly 构成；修饰动词"],["slowly","adv.","缓慢地","反义 quickly"],["carefully","adv.","仔细地","listen carefully／read carefully，中考高频"],["carelessly","adv.","粗心地","反义 carefully；拼写注意 -lessly"],["quietly","adv.","安静地","由 quiet + ly；注意不是 quietely"],["loudly","adv.","大声地","speak loudly；loud 也可作副词，但 -ly 更常考"],["happily","adv.","快乐地","happy 变 y 为 i 加 -ly：happily"],["sadly","adv.","伤心地；遗憾的是","句首 Sadly, ... 表「遗憾的是」"],["easily","adv.","容易地","easy 变 y 为 i 加 -ly：easily"],["suddenly","adv.","突然","常与一般过去时连用：Suddenly it began to rain."],["finally","adv.","最后；终于","结尾段常用：Finally, I want to say thanks to ..."],["luckily","adv.","幸运的是","句首副词，后加逗号；= fortunately"],["badly","adv.","糟糕地；严重地","be badly hurt 伤得很重；比较级 worse"],["well","adv.","好地；健康地","good 的副词形式；比较级 better"],["politely","adv.","有礼貌地","ask politely 礼貌地询问"],["softly","adv.","轻柔地","speak softly 轻声说"],["properly","adv.","正确地；恰当地","由 proper + ly 构成，注意是 -erly 不是 -ely"],["successfully","adv.","成功地","由 successful + ly，注意中间有 -ful"]]},{"type":"table","title":"时间与地点副词","head":["单词","词性/音标","释义","考点"],"rows":[["now","adv.","现在","与现在进行时、一般现在时连用"],["then","adv.","那时；然后","叙述顺序用 then；与 now 对应"],["today","adv.","今天","可作名词与副词；today’s newspaper 今天的报纸"],["tomorrow","adv.","明天","与一般将来时连用"],["yesterday","adv.","昨天","与一般过去时连用"],["soon","adv.","不久；很快","as soon as possible 尽快"],["already","adv.","已经","用于肯定句，放在 have/has 之后"],["yet","adv.","还（没）；已经","用于否定句与疑问句，放句末"],["just","adv.","刚刚；只是","have just done 刚刚做完"],["still","adv.","仍然","强调持续；He is still waiting."],["ever","adv.","曾经","用于疑问句与现在完成时：Have you ever been to Beijing?"],["before","adv.","以前","放句末表示以前：I have seen it before."],["ago","adv.","以前","与一般过去时连用：two days ago"],["later","adv.","后来；以后","three days later 三天后；常用于故事叙述"],["everywhere","adv.","到处","= here and there"],["outside","adv.","在外面","作副词与介词：play outside／outside the door"]]},{"type":"table","title":"连接副词与句子副词","head":["单词","词性/音标","释义","考点"],"rows":[["however","adv.","然而","表转折；它连接两个句子时前面要用句号或分号，不能只用逗号"],["therefore","adv.","因此","表结果，常用于说明文、议论文"],["besides","adv.","此外","表递进，用于补充理由"],["otherwise","adv.","否则","= or else；表相反的后果"],["instead","adv.","反而；代替","instead of 是短语介词，后接名词或动名词"],["moreover","adv.","而且","书面语，等于 what is more"],["also","adv.","也","放在实义动词前、be 动词后"],["too","adv.","也；太","肯定句句末用 too；too ... to 太……而不能"],["either","adv.","也（不）","否定句句末用 either"],["perhaps","adv.","也许","= maybe，可放句首"],["actually","adv.","实际上","= in fact；口语与写作都常用"],["especially","adv.","尤其","especially in summer 尤其在夏天"]]},{"type":"table","title":"易混副词对照（形近义不同）","head":["单词","词性/音标","释义","考点"],"rows":[["hard","adv.","努力地；猛烈地","work hard 努力工作；rain hard 雨下得大"],["hardly","adv.","几乎不","半否定；He hardly knows me. 他几乎不认识我"],["late","adv.","晚；迟","get up late 起得晚；be late for 迟到"],["lately","adv.","最近","= recently；多与现在完成时连用"],["near","adv.","近","come near 靠近；也可作介词 near the school"],["nearly","adv.","几乎；将近","nearly ten years 将近十年"],["high","adv.","高高地","fly high（位置高）；不能用 highly 代替"],["highly","adv.","高度地；非常","think highly of sb 高度评价某人"],["deep","adv.","深深地（空间）","dig deep 挖得深；也可作形容词"],["deeply","adv.","深深地（情感）","be deeply moved 深受感动"],["wide","adv.","宽地；充分地","open the door wide 把门大开"],["widely","adv.","广泛地","English is widely used. 英语被广泛使用"],["close","adv.","近地","sit close to me 挨着我坐"],["closely","adv.","仔细地；密切地","watch closely 仔细观察"],["most","adv.","最；非常","most beautiful 最美；a most useful book 非常有用"],["mostly","adv.","主要地；大多","The students are mostly from Guangdong."],["free","adv.","免费地","作形容词「自由的、空闲的」更常见"],["freely","adv.","自由地；无拘束地","speak freely 畅所欲言"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["频率副词的位置：be 动词、助动词、情态动词之后，实义动词之前。","She is always ...；She always gets ...","She is always the first to come to school, and she always helps others.","她总是第一个到校，而且总是帮助别人。\n看到 always 前是实义动词（如 gets always up）就错了，位置比词义更容易考。"],["方式副词一般由形容词加 -ly 构成，注意 happy→happily、easy→easily、true→truly 这类拼写变化。","形容词 + ly","The old man walked slowly across the road and thanked us politely.","老人慢慢走过马路，礼貌地向我们道谢。\n以「辅音字母 + y」结尾的形容词，变 y 为 i 再加 -ly；true 去 e 加 ly 成 truly。"],["hard 与 hardly、late 与 lately 是两组意义相反的副词，不能互推。","work hard 努力工作 / hardly work 几乎不工作","He works hard every day, so he hardly has time to watch TV.","他每天努力工作，所以几乎没有时间看电视。\n完形填空里出现 hardly、seldom、never 就要把后半句的逻辑关系按否定来读。"],["连接副词后用逗号，衔接前后两句，表示转折、结果、递进或相反的后果。","However, ... / Therefore, ...","It was raining hard. However, we went to school on time as usual.","当时雨下得很大，然而我们照常按时到了学校。\nhowever 不等于 but：它不能只用逗号连接两个句子，要写成「句号 + However, 」或「分号 + however, 」。"],["多个状语同现时按「方式—地点—时间」排列。","动词 + 方式 + 地点 + 时间","The children sang happily in the classroom yesterday afternoon.","昨天下午孩子们在教室里愉快地唱歌。\n时间状语通常放最后；若要把时间提前强调，放在句首更自然。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["He works very hardly and never gives up.","He works very hard and never gives up.","hardly 意思是「几乎不」，与 never gives up（从不放弃）矛盾；表示「努力地」要用 hard，它本身就是副词。"],["She always is late for the morning reading.","She is always late for the morning reading.","频率副词 always 要放在 be 动词之后，不能放在 be 动词之前。"],["Please listen to the teacher careful in class.","Please listen to the teacher carefully in class.","修饰动词 listen 要用副词 carefully；careful 是形容词，只能修饰名词或作表语。"],["I got up lately this morning, so I missed the first bus.","I got up late this morning, so I missed the first bus.","lately 意思是「最近」，与「今天早上起得晚」不符；表示「迟、晚」要用 late。"]]}],"questions":[{"id":"eng-vocab-pos-5-q1","type":"choice","stem":"My father is ______ busy with his work, so he ______ has time to watch TV.","answer":"A","explain":"第一空要表示「总是很忙」，用 always，位置在 be 动词 is 之后；第二空由 so 引出的结果看，应是「几乎没有时间看电视」，用 hardly。B 项意思正好相反；C 项第二空 hard 是「努力地」，不表示否定；D 项第一空 hard 不能修饰 busy（修饰形容词要用副词，hard 在此不成立）。","options":["always; hardly","hardly; always","always; hard","hard; hardly"],"difficulty":3,"tags":["副词","频率副词","hard/hardly"]},{"id":"eng-vocab-pos-5-q2","type":"choice","stem":"She got up ______ this morning, so she was late for the first class.","answer":"A","explain":"表示「起得晚」用 late，它本身可作副词。B 项 lately 是「最近」，与 this morning 不搭配；C 项 later 是「后来、之后」，表示顺序而非时刻的晚；D 项 latest 意为「最新的」，不能修饰 got up。","options":["late","lately","later","latest"],"difficulty":2,"tags":["副词","late/lately","易混词"]},{"id":"eng-vocab-pos-5-q3","type":"choice","stem":"The old man thanked us ______ for helping him cross the road.","answer":"A","explain":"空处修饰动词 thanked，要用副词 politely。B 项 polite 是形容词，不能修饰动词；C 项 politeness 是名词，表示「礼貌」；D 项 impolite 是形容词「不礼貌的」，既词性不对，意思也与「道谢」的语境矛盾。","options":["politely","polite","politeness","impolite"],"difficulty":1,"tags":["副词","方式副词","词性判断"]},{"id":"eng-vocab-pos-5-q4","type":"choice","stem":"It was raining hard. ______, we still went to the park as we had planned.","answer":"A","explain":"前后是转折关系：「雨下得很大」但「仍然去了公园」，用 However。B 项 Therefore 表结果，与「仍然去」矛盾；C 项 Besides 表递进，用于补充；D 项 Otherwise 表「否则」，后应接相反的后果，而不是实际发生的事。","options":["However","Therefore","Besides","Otherwise"],"difficulty":3,"tags":["副词","连接副词","逻辑关系"]},{"id":"eng-vocab-pos-5-q5","type":"choice","stem":"My sister ______ does the dishes after dinner, and she never complains.","answer":"A","explain":"句中已有实义动词 does，频率副词 always 要放在实义动词之前，所以直接写 always does。B、C 两项多了 is，句子出现两个谓语；D 项把 always 放在助动词 does 之后，位置错误。","options":["always","is always","always is","does always"],"difficulty":2,"tags":["副词","频率副词","位置"]},{"id":"eng-vocab-pos-5-q6","type":"fill","stem":"Please listen to the teacher ______ (careful) in class.","answer":"carefully","explain":"空处修饰动词 listen，要用副词 carefully。判断办法：修饰名词用形容词，修饰动词用副词。careful 作形容词时可用于 be careful with sth。","difficulty":1,"tags":["副词","词形变化","形容词变副词"]}]},{"id":"eng-vocab-pos-6","title":"词性索引·代词：人称、物主、反身与不定代词","subtitle":"词性索引 · Pronouns: Personal, Possessive, Reflexive and Indefinite","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把代词按「主格作主语、宾格作宾语、形容词性物主代词后接名词、反身代词指回主语」四条线排好，再集中攻 both/either/neither/none/all 这组不定代词，代词题几乎不会再错。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"both / either / neither / none / all 的用法与谓语一致是语法选择的高频考点。","explain":"both 指两者都，谓语用复数；either 指两者中任一个，谓语用单数；neither 指两者都不，谓语用单数；none 指三者或以上都不，谓语可单可复；all 指三者或以上都，谓语看后面的名词。判断第一步永远是「数一数范围是几个」。"},{"level":"重点","text":"形容词性物主代词后必须接名词，名词性物主代词后不能接名词。","explain":"my book = mine；her bag = hers。写作填空常给出括号里的 I 或 she，让学生判断该填哪种形式。判断办法：空格后紧跟名词就用形容词性（my），空格后没有名词就用名词性（mine）。"},{"level":"重点","text":"反身代词用于主语与宾语所指同一人，并有大量固定搭配：enjoy oneself、help oneself to、by oneself。","explain":"Help yourself to some fish. / He taught himself English. 中考常考「主语是 you，反身代词用 yourself 还是 yourselves」：单数用 yourself，复数用 yourselves，这类细节在语法选择中常设错。"},{"level":"次重点","text":"it 除指代外，还可作形式主语和形式宾语。","explain":"It is important to learn English well.（形式主语）；I find it hard to finish the work on time.（形式宾语）。阅读里 it 的指代常是细节题的定位依据，要回到上一句找它指的是什么。"},{"level":"次重点","text":"some 用于肯定句与表示请求、建议的疑问句；any 用于否定句与普通疑问句。","explain":"Would you like some tea? 虽是疑问句却用 some，因为这是邀请；Do you have any questions? 才是真正的询问。语法选择里看到 Would you like、Could you please 就用 some。"},{"level":"了解","text":"another / other / the other / others / the others 的区别靠「剩下几个」判断。","explain":"两者剩下一个用 the other；三者以上再要一个用 another；泛指其他一些用 others；特指剩下的全部用 the others。作文里写「另一方面」是 on the other hand。"}]},{"type":"table","title":"人称代词（主格与宾格）","head":["单词","词性/音标","释义","考点"],"rows":[["I","pron.","我（主格）","作主语；宾格是 me"],["me","pron.","我（宾格）","作宾语、介词宾语：with me"],["you","pron.","你；你们（主宾格同形）","单复数同形，谓语看语境"],["he","pron.","他（主格）","宾格 him；物主代词 his"],["him","pron.","他（宾格）","give him a hand"],["she","pron.","她（主格）","宾格 her；物主代词 her/hers"],["her","pron.","她（宾格）；她的","既是宾格又是形容词性物主代词，靠后面有无名词区分"],["it","pron.","它","可作形式主语、形式宾语；指代前文的单数名词"],["we","pron.","我们（主格）","宾格 us；物主代词 our/ours"],["us","pron.","我们（宾格）","Let us = Let’s；介词后用宾格"],["they","pron.","他们（主格）","宾格 them；可指代复数名词"],["them","pron.","他们（宾格）","both of them；with them"]]},{"type":"table","title":"物主代词（形容词性与名词性）","head":["单词","词性/音标","释义","考点"],"rows":[["my","pron.","我的（形容词性）","后必须接名词：my book"],["mine","pron.","我的（名词性）","后不接名词：It is mine."],["your","pron.","你的（形容词性）","后接名词：your idea"],["yours","pron.","你的（名词性）","书信结尾 Yours sincerely"],["his","pron.","他的（形容词性与名词性同形）","his book = his"],["her","pron.","她的（形容词性）","后接名词：her pen"],["hers","pron.","她的（名词性）","后不接名词：The pen is hers."],["its","pron.","它的（形容词性）","注意与 it’s（it is）区分"],["our","pron.","我们的（形容词性）","our school 我们学校"],["ours","pron.","我们的（名词性）","This classroom is ours."],["their","pron.","他们的（形容词性）","their books；注意与 there、they’re 区分"],["theirs","pron.","他们的（名词性）","The bags are theirs."]]},{"type":"table","title":"反身代词与固定搭配","head":["单词","词性/音标","释义","考点"],"rows":[["myself","pron.","我自己","I did it myself. 我自己做的"],["yourself","pron.","你自己","Help yourself! 请自便（对一个人说）"],["yourselves","pron.","你们自己","对多人说：Help yourselves to some fruit."],["himself","pron.","他自己","He hurt himself."],["herself","pron.","她自己","She taught herself French."],["itself","pron.","它自己","The cat cleaned itself."],["ourselves","pron.","我们自己","We enjoyed ourselves at the party."],["themselves","pron.","他们自己","The children dressed themselves."],["enjoy oneself","phr.","玩得开心","= have a good time；注意 oneself 随主语变化"],["help oneself to","phr.","随便吃（喝）","招待客人常用：Help yourself to some fish."],["by oneself","phr.","独自；靠自己","= alone；He finished the work by himself."],["teach oneself","phr.","自学","= learn sth by oneself"],["look after oneself","phr.","照顾自己","He is old enough to look after himself."],["say to oneself","phr.","自言自语","阅读里常用来描写心理活动"],["make oneself at home","phr.","别拘束","= Please feel at home."],["hurt oneself","phr.","伤到自己","Be careful not to hurt yourself."]]},{"type":"table","title":"指示代词与 one / it 的指代","head":["单词","词性/音标","释义","考点"],"rows":[["this","pron.","这个","指近处或下文将要说的内容；电话中介绍自己用 This is ..."],["that","pron.","那个","指远处或上文已说的内容；电话中问对方用 Who is that?"],["these","pron.","这些","this 的复数，后接复数名词"],["those","pron.","那些","that 的复数；those who ... 那些人"],["one","pron.","一个（同类中的一个）","指代前面提到的同类可数名词单数：a red one"],["ones","pron.","一些（同类中的一些）","the big ones 那些大的"],["the one","phr.","（特指的）那一个","指代特定的人或物：the one in the blue coat 穿蓝外套的那个"],["other","pron.","别的；其他的","作形容词后接名词复数：other students"],["the other","pron.","（两者中的）另一个","I have two pens. One is red, the other is blue."],["another","pron.","（三者以上的）另一个","another + 单数名词；another three days 再三天"],["others","pron.","其他的（一些）","泛指，后不接名词：help others 帮助他人"],["the others","pron.","其余的全部","特指某一范围内的其余全部"]]},{"type":"table","title":"不定代词（含 both / either / neither / none / all）","head":["单词","词性/音标","释义","考点"],"rows":[["some","pron.","一些","肯定句与表示邀请的疑问句：Would you like some tea?"],["any","pron.","一些；任何","否定句与疑问句；也可表「任一」"],["no","adj.","没有","= not any，后直接接名词：no water；No one knows. 没有人知道"],["none","pron.","（三者以上）一个也没有","None of the students was/were late.；回答 How many 用 none"],["both","pron.","两者都","谓语用复数：Both of them are doctors."],["either","pron.","两者中任一个","谓语用单数：Either of the answers is right."],["neither","pron.","两者都不","谓语用单数：Neither of the twins likes fish."],["all","pron.","（三者以上）全都","All of us are here.；谓语看后面的名词"],["each","pron.","每个（强调个体）","谓语用单数：Each of them has a bike."],["every","adj.","每个（强调整体）","只作定语：every student，不能说 every of them"],["something","pron.","某事","形容词后置：something important"],["anything","pron.","任何事物","用于否定句与疑问句"],["nothing","pron.","没有什么","本身否定：Nothing is impossible."],["everything","pron.","一切","谓语用单数：Everything is ready."],["somebody","pron.","某人","= someone，谓语用单数"],["anybody","pron.","任何人","= anyone，用于否定与疑问"],["nobody","pron.","没有人","= no one，谓语用单数"],["everybody","pron.","每个人","= everyone，谓语用单数"],["many","pron.","许多（可数）","many of the students"],["much","pron.","许多（不可数）","How much 问价格与数量"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["主格作主语，宾格作宾语或介词宾语。","I / he / she / we / they 作主语；me / him / her / us / them 作宾语","Between you and me, he is the best player in our class.","你我私下说，他是我们班最棒的球员。\n介词后面一律用宾格，between you and me 不能写成 between you and I。"],["形容词性物主代词后必须接名词；名词性物主代词本身代替「物主代词 + 名词」。","my book = mine；our school = ours","This is my dictionary, and that thick one is hers.","这是我的词典，那本厚的是她的。\n空格后有名词就填 my/your/her，没有名词就填 mine/yours/hers。"],["反身代词表示动作又回到主语本身，单复数必须与主语一致。","enjoy oneself / help oneself to sth","Help yourselves to some fish, children. The soup is hot.","孩子们，随便吃点鱼，汤很烫。\n主语是 you 且指多人时用 yourselves，这一点常被设错。"],["both 谓语用复数；either、neither 谓语用单数；none 可单可复；all 看后面的名词。","Both of ... are；Neither of ... is","Both of my parents are teachers, and neither of them is at home at noon.","我父母都是老师，中午两人都不在家。\n先数范围：两者用 both/either/neither，三者以上用 all/none。"],["不定代词作主语视为单数，形容词修饰它时要后置。","Everyone is ...；something new","Everyone is here, and nobody has anything new to say.","人都到齐了，没有人有新的事情要说。\neverybody、everything、nobody、nothing 作主语都按单数处理，谓语用 is、has。"],["another 指三者以上的另一个，the other 指两者中的另一个。","another + 单数名词；the other + 单数名词","I have two brothers. One is a doctor, and the other is a teacher.","我有两个兄弟，一个是医生，另一个是老师。\n看到 two、both、a pair of 就用 the other；范围是三个以上就用 another。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["This is my book, and that is your.","This is my book, and that is yours.","your 是形容词性物主代词，后面必须有名词；此处句末没有名词，要用名词性物主代词 yours。"],["Between you and I, the plan needs changing.","Between you and me, the plan needs changing.","between 是介词，后面要接宾格，所以用 me 而不是主格 I。"],["Everyone in our class are interested in the game.","Everyone in our class is interested in the game.","everyone 是不定代词，作主语按单数处理，谓语用 is，即使后面跟着复数意义的 in our class。"],["I have two brothers. One is a doctor, another is a teacher.","I have two brothers. One is a doctor, the other is a teacher.","两者中剩下的那一个用 the other；another 表示三者以上中的「另一个」。"]]}],"questions":[{"id":"eng-vocab-pos-6-q1","type":"choice","stem":"Both of my parents ______ teachers, and neither of them ______ at home at noon.","answer":"A","explain":"both of ... 表示「两者都」，谓语用复数 are；neither of ... 表示「两者都不」，谓语用单数 is。B 项正好颠倒；C 项把 neither 当复数；D 项把 both 当单数。判断关键是 both 与 neither 分别按复数、单数处理。","options":["are; is","is; are","are; are","is; is"],"difficulty":2,"tags":["代词","both/neither","主谓一致"]},{"id":"eng-vocab-pos-6-q2","type":"choice","stem":"Help ______ to some fish, children. It is good for your health.","answer":"A","explain":"句子呼语是 children，说明对象是多人，对多人说「随便吃」用 Help yourselves to ...。B 项 yourself 是单数，只对一个人说；C 项 themselves 用于主语是 they 的句子；D 项 ourselves 用于主语是 we 的句子。","options":["yourselves","yourself","themselves","ourselves"],"difficulty":2,"tags":["代词","反身代词","固定搭配"]},{"id":"eng-vocab-pos-6-q3","type":"choice","stem":"— Is this your dictionary? — No, it is not ______. Mine is in my schoolbag.","answer":"A","explain":"答语说「我的那本在书包里」，说明这本不是「我的」，空后没有名词，用名词性物主代词 mine 作表语。B 项 my 是形容词性物主代词，后面必须接名词；C 项 me 是宾格，不能作表语；D 项 myself 是反身代词，与句意不符。","options":["mine","my","me","myself"],"difficulty":2,"tags":["代词","物主代词","名词性物主代词"]},{"id":"eng-vocab-pos-6-q4","type":"choice","stem":"I have two tickets for the concert. One is for my sister, and ______ is for me.","answer":"A","explain":"一共两张票，一张给姐姐，剩下的那一张就是「两者中的另一个」，用 the other。B 项 another 指三者以上中的另一个；C 项 other 作代词时不单独使用，后面要接名词；D 项 others 泛指「其他的人或物」，不能指两者中的剩余一个。","options":["the other","another","other","others"],"difficulty":2,"tags":["代词","other/the other","指代"]},{"id":"eng-vocab-pos-6-q5","type":"choice","stem":"______ of the three students has ever been to Beijing, so they know nothing about it.","answer":"A","explain":"范围是 the three students（三者），且后半句说「他们对此一无所知」，说明三个人都没去过，用 None，谓语用单数 has。B 项 Neither 只能指两者；C 项 Both 与「没人去过」矛盾，且谓语要用复数；D 项 All 表全都去过，与后半句矛盾。","options":["None","Neither","Both","All"],"difficulty":3,"tags":["代词","none","不定代词"]},{"id":"eng-vocab-pos-6-q6","type":"fill","stem":"The boy is old enough to look after ______ (he).","answer":"himself","explain":"主语是 The boy，动作 look after 的宾语又指主语本人，所以用反身代词 himself。look after oneself 意为「照顾自己」，是本句的固定搭配。","difficulty":1,"tags":["代词","反身代词","词形变化"]}]},{"id":"eng-vocab-pos-7","title":"词性索引·数词与时间表达：基数词、序数词、时刻与分数","subtitle":"词性索引 · Numerals and Time Expressions","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"把 hundred / thousand 的两种用法、序数词拼写、年月日与时刻的介词和读法、分数与百分数的构成一次理清，数词题和写作里的时间表达都能写准。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"hundred、thousand、million 前有具体数字时不加 -s，后接 of 时要加 -s 并接复数名词。","explain":"two hundred students（两百名学生）与 hundreds of students（数百名学生）。语法选择几乎年年出现这一对，判断办法：前面有 two、three 这类具体数字就写单数，前面没有数字就写 hundreds of。"},{"level":"重点","text":"序数词前一般加 the，拼写要记牢 fifth、ninth、twelfth、twentieth 这几个特殊形式。","explain":"日期、楼层、名次都用序数词：on May first、the twelfth floor、the first prize。写作里写「我的第十二次」错成 twelveth 是最常见的拼写失误。"},{"level":"重点","text":"年月日的介词搭配是固定考点：in 2025、in May、on May 1st、on Monday、at 8:00。","explain":"时间介词与数词是同一道题的两个考点：先判断时间范围的大小（年、月用 in，具体某天用 on，时刻用 at），再检查数词写得对不对。"},{"level":"次重点","text":"分数由「分子基数词 + 分母序数词」构成，分子大于 1 时分母加 -s；分数作主语的谓语看 of 后面的名词。","explain":"one third、two thirds、three quarters。Two thirds of the students are girls.（students 复数，谓语用 are）；Two thirds of the land is covered with trees.（land 不可数，谓语用 is）。"},{"level":"次重点","text":"时刻有顺读法与逆读法两种：7:15 读 seven fifteen 或 a quarter past seven；7:45 读 a quarter to eight。","explain":"超过半点用 to（差多少到下一个整点），半点以前用 past。听力填时间、听说复述时刻都用得上，听清 to 与 past 是关键。"},{"level":"了解","text":"次数与倍数用 once、twice、three times；倍数表达常用「数词 + times + as ... as」。","explain":"once a week、twice a month、three times a day。阅读图表题常给「每周两次」这类信息，要看懂 once、twice 而不是去找 two times。"}]},{"type":"table","title":"基数词（含易错拼写）","head":["单词","词性/音标","释义","考点"],"rows":[["one","num.","一","序数词 first"],["two","num.","二","序数词 second；twice 表「两次」"],["three","num.","三","序数词 third；thirteen 注意有 r"],["four","num.","四","序数词 fourth；forty 拼写不含 u"],["five","num.","五","序数词 fifth；fifteen、fifty 拼写变化"],["six","num.","六","序数词 sixth"],["seven","num.","七","序数词 seventh"],["eight","num.","八","序数词 eighth，只加 h 不加 t"],["nine","num.","九","序数词 ninth，去掉 e 再加 th"],["ten","num.","十","序数词 tenth"],["twelve","num.","十二","序数词 twelfth，拼写特殊"],["fifteen","num.","十五","five → fifteen，注意拼写"],["twenty","num.","二十","序数词 twentieth"],["thirty","num.","三十","序数词 thirtieth"],["forty","num.","四十","不是 fourty，这是最常见的拼写错"],["fifty","num.","五十","five → fifty"],["ninety","num.","九十","nine → ninety，去掉 e"],["hundred","num.","百","two hundred 不加 s；hundreds of 加 s"],["thousand","num.","千","three thousand 不加 s；thousands of 加 s"],["million","num.","百万","millions of people 数百万人"]]},{"type":"table","title":"序数词","head":["单词","词性/音标","释义","考点"],"rows":[["first","num.","第一","缩写 1st；first prize 一等奖"],["second","num.","第二","缩写 2nd；the second floor 二楼（英式）"],["third","num.","第三","缩写 3rd；其余多为 th"],["fourth","num.","第四","four + th，注意不是 forth"],["fifth","num.","第五","five → fifth，拼写特殊"],["sixth","num.","第六","six + th"],["seventh","num.","第七","seven + th"],["eighth","num.","第八","eight 只加 h，不写 eightth"],["ninth","num.","第九","nine 去 e 加 th"],["tenth","num.","第十","ten + th"],["eleventh","num.","第十一","eleven + th"],["twelfth","num.","第十二","twelve → twelfth，拼写特殊"],["thirteenth","num.","第十三","thirteen + th"],["twentieth","num.","第二十","twenty 变 y 为 ie 加 th"],["thirtieth","num.","第三十","thirty → thirtieth"],["fortieth","num.","第四十","forty → fortieth"],["fiftieth","num.","第五十","fifty → fiftieth"],["nineteenth","num.","第十九","nineteen + th"],["hundredth","num.","第一百","the hundredth anniversary 一百周年"],["thousandth","num.","第一千","thousand + th"]]},{"type":"table","title":"年月日与时刻表达","head":["单词","词性/音标","释义","考点"],"rows":[["in 2025","phr.","在 2025 年","年份用 in；读作 in twenty twenty-five"],["in May","phr.","在五月","月份用 in；月份首字母大写"],["on May 1st","phr.","在五月一日","具体某天用 on；读作 May the first"],["on Monday morning","phr.","在周一上午","星期与具体某天的上午用 on"],["in the morning","phr.","在上午","泛指的上午用 in；特指某天的上午用 on"],["at noon","phr.","在中午","固定搭配用 at；同类 at night"],["at eight o’clock","phr.","在八点","时刻用 at；也可省略 o’clock"],["half past seven","phr.","七点半","半点用 half past + 钟点"],["a quarter past six","phr.","六点一刻","半点前用 past"],["a quarter to nine","phr.","八点四十五（差一刻九点）","半点后用 to，指「差多少到下一整点」"],["ten to ten","phr.","九点五十","逆读法：分钟 + to + 下一个整点"],["seven fifteen","phr.","七点十五","顺读法：钟点 + 分钟，听力里最常见"],["the day after tomorrow","phr.","后天","与一般将来时连用"],["the day before yesterday","phr.","前天","与一般过去时连用"],["in two days","phr.","两天后","in + 一段时间表将来；after 后多接过去的时间点"],["for three years","phr.","三年（时间长度）","for 后接一段时间，与完成时或过去时连用"]]},{"type":"table","title":"分数、百分数与次数","head":["单词","词性/音标","释义","考点"],"rows":[["a half","phr.","一半","half an hour 半小时；half of the students"],["a quarter","phr.","四分之一","a quarter of the students"],["three quarters","phr.","四分之三","分子大于 1，分母加 -s"],["one third","phr.","三分之一","分子为 1 时分母不加 -s"],["two thirds","phr.","三分之二","Two thirds of the students are girls."],["one fifth","phr.","五分之一","分母 fifth 拼写特殊"],["two fifths","phr.","五分之二","分子大于 1 分母加 -s：fifths"],["ten percent","phr.","百分之十","percent 单复数同形，不加 -s"],["fifty percent","phr.","百分之五十","Fifty percent of the work has been done."],["one hundred percent","phr.","百分之百","口语里也表「完全同意」"],["once a week","phr.","每周一次","once 表「一次」，不是 one time"],["twice a month","phr.","每月两次","twice 表「两次」"],["three times a day","phr.","每天三次","三次以上用「基数词 + times」"],["once more","phr.","再一次","= one more time"],["twice as many as","phr.","是……的两倍（数量）","倍数 + as many/much as 结构"]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["hundred、thousand、million 前有具体数字时不加 -s；表示「数以……计」时用复数并接 of。","two hundred students；hundreds of students","There are about two thousand students in our school, and hundreds of them join the science club every year.","我们学校大约有两千名学生，其中每年有数百人加入科学社团。\n看到前面有数字就读到 hundred 为止，后面直接接名词；看到 of 就把 s 补上。"],["序数词表示顺序，前面一般加 the；拼写要单独记 fifth、ninth、twelfth、twentieth。","the + 序数词 + 名词","Our classroom is on the twelfth floor, so we take the lift every day.","我们教室在十二楼，所以我们每天乘电梯。\n「又一、再一」用 a + 序数词，如 a second try 再试一次。"],["年月日的介词形式固定：in + 年/月，on + 具体某天，at + 时刻。","in 2025 / on May 1st / at 7:30","The school sports meeting will be held on October 18th and begin at 8:00 a.m.","学校运动会将在十月十八日举行，上午八点开始。\n遇到「某天的上午／下午」也用 on：on the morning of May 1st。"],["分数由「基数词 + 序数词」构成，分子大于 1 时分母加 -s；分数作主语时谓语看 of 后的名词。","one third；two thirds","Two thirds of the students in our class are interested in science, but two thirds of the water in the river is polluted.","我们班三分之二的学生对科学感兴趣，但这条河三分之二的水被污染了。\n先看 of 后面的名词是可数还是不可数：students 用 are，water 用 is。"],["时刻逆读法：半点以前用 past，半点以后用 to。","a quarter past seven；a quarter to eight","The film begins at a quarter to eight, so we should set off at seven thirty.","电影七点四十五开始，所以我们应该七点半出发。\n注意 to 表示「差多少到下一个整点」：a quarter to eight 是七点四十五，不是八点一刻。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["There are two hundreds students in our grade.","There are two hundred students in our grade.","hundred 前有具体数字 two 时不加 -s；只有表示「数以百计」的 hundreds of 才用复数。"],["He lives on the fourty-fifth floor.","He lives on the forty-fifth floor.","forty 的拼写中没有 u，不能说 fourty；序数词是 fortieth、forty-fifth。"],["The meeting will be held in May 1st.","The meeting will be held on May 1st.","具体某一天（含某月某日）用介词 on；in 用于年份与月份，如 in May、in 2025。"],["One thirds of the students have joined the club.","One third of the students have joined the club.","分子是 1 时分母用单数 third，不加 -s；只有分子大于 1 才写 two thirds。"]]}],"questions":[{"id":"eng-vocab-pos-7-q1","type":"choice","stem":"There are about five ______ students in our school, and ______ them come from other cities.","answer":"A","explain":"第一空前有具体数字 five，hundred 用单数；第二空表示「数以百计的他们」中的一部分，用 hundreds of。B、D 两项在 five 后错用复数；C 项第二空缺 -s。这一题的两个考点正好覆盖 hundred 的两种用法。","options":["hundred; hundreds of","hundreds; hundred of","hundred; hundred of","hundreds; hundreds of"],"difficulty":2,"tags":["数词","hundred","语法选择"]},{"id":"eng-vocab-pos-7-q2","type":"choice","stem":"Our new reading room is on the ______ floor of that building.","answer":"A","explain":"表示「第十二层」要用序数词 twelfth，拼写是 twelve 变 ve 为 f 加 th。B、D 两项拼写不存在；C 项 twelve 是基数词「十二」，不能表示顺序。记住 twelfth 与 fifth、ninth 一样属于特殊拼写。","options":["twelfth","twelveth","twelve","twelvth"],"difficulty":2,"tags":["数词","序数词","拼写易错"]},{"id":"eng-vocab-pos-7-q3","type":"choice","stem":"Two ______ of the land in that area ______ covered with trees.","answer":"A","explain":"「三分之二」写作 two thirds，分子大于 1 时分母加 -s；land 是不可数名词，分数作主语时谓语与 of 后面的名词一致，所以用 is。B 项分母未加 -s 且谓语用复数；C 项谓语用复数错误；D 项把分数写成 three，不是分数形式。","options":["thirds; is","third; are","thirds; are","three; is"],"difficulty":3,"tags":["数词","分数","主谓一致"]},{"id":"eng-vocab-pos-7-q4","type":"choice","stem":"The film starts at 7:45, that is, ______.","answer":"A","explain":"7:45 是八点差一刻，逆读法用「分钟 + to + 下一个整点」，即 a quarter to eight。B 项表示八点一刻（8:15）；C 项表示七点一刻（7:15）；D 项表示六点四十五（6:45）。关键是 to 表示「还差多少到下一个整点」。","options":["a quarter to eight","a quarter past eight","a quarter past seven","a quarter to seven"],"difficulty":2,"tags":["数词","时刻表达","听力常用"]},{"id":"eng-vocab-pos-7-q5","type":"choice","stem":"The school sports meeting will be held ______ October 18th, and it will last ______ three days.","answer":"A","explain":"具体某一天（October 18th）用 on；表示持续时间「三天」用 for。B 项 in 用于月份或年份，不能用于某月某日；C 项 in three days 是「三天后」，与 last（持续）不搭配；D 项 at 用于时刻。","options":["on; for","in; for","on; in","at; for"],"difficulty":2,"tags":["数词","时间介词","年月日"]},{"id":"eng-vocab-pos-7-q6","type":"fill","stem":"请写出数词 nine 的序数词：______","answer":"ninth","explain":"nine 变序数词时去掉 e 再加 -th，写作 ninth，不写 nineth。同类需要特别注意的还有 five→fifth、twelve→twelfth、eight→eighth。","difficulty":1,"tags":["数词","序数词","拼写"]}]},{"id":"eng-vocab-pos-8","title":"词性索引·介词与连词：in/on/at 与关联连词配对","subtitle":"词性索引 · Prepositions and Conjunctions","grade":"all","tags":["词性索引"],"blocks":[{"type":"note","title":"学习要点","text":"用「大时间用 in、具体某天用 on、时刻用 at」三分法解决时间介词，再把 both…and / either…or / not only…but also 的谓语一致和 although 不与 but 连用这两条硬规则记死。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"时间介词三分法：in 用于年、月、季节、上午下午晚上；on 用于具体某天、星期、某天的上午；at 用于时刻与固定短语。","explain":"语法选择固定一题。判断办法：先看空格后的时间词是「大范围、具体一天还是点时刻」。特例要单独记：at noon、at night、at the weekend 用 at；on Sunday morning 用 on。"},{"level":"重点","text":"关联连词的谓语一致：both … and 用复数；either … or、neither … nor、not only … but also 遵循就近原则。","explain":"Both Tom and Jack are good at maths.（复数）；Either you or he is right.（靠近 is 的是 he）；Neither my parents nor I like fish.（靠近 like 的是 I，用复数动词）。先找离动词最近的那个主语，这是最快的一刀。"},{"level":"重点","text":"although 不与 but 连用，because 不与 so 连用，这是中式英语最典型的错误。","explain":"Although he was tired, he kept working.（不能再加 but）；Because it rained, we stayed at home.（不能再加 so）。写作里出现这两个错误，是评卷直接扣分的硬伤。"},{"level":"次重点","text":"介词后面接代词要用宾格，接动词要用动名词。","explain":"be good at swimming、look forward to seeing you、instead of going out。语法选择常把 to 当不定式符号设错：look forward to 的 to 是介词，后面必须接动名词。"},{"level":"次重点","text":"because of 后接名词、代词或动名词，because 后接完整的句子。","explain":"We stayed at home because of the heavy rain. = We stayed at home because it rained heavily. 写作里想用高级表达就用 because of / thanks to，但括号里给出的是名词时只能用 because of。"},{"level":"了解","text":"表示地点的介词各有空间含义：across 指从表面横过，through 指从内部穿过，over 指从上方越过。","explain":"walk across the road（横过马路）、walk through the forest（穿过森林）、jump over the wall（跳过墙）。阅读与听说里的方位描述靠这几个词定位。"}]},{"type":"table","title":"时间介词搭配","head":["单词","词性/音标","释义","考点"],"rows":[["in the morning","phr.","在上午","泛指用 in；某天的上午用 on the morning of ..."],["in May","phr.","在五月","月份用 in"],["in 2025","phr.","在 2025 年","年份用 in"],["in spring","phr.","在春天","季节用 in"],["in two days","phr.","两天后","in + 一段时间表将来"],["on Monday","phr.","在周一","星期用 on"],["on May 1st","phr.","在五月一日","具体某天用 on"],["on Sunday morning","phr.","在周日早上","某天的上午也用 on"],["on a cold winter morning","phr.","在一个寒冷的冬天早晨","被修饰的某天早晨仍用 on"],["at eight o’clock","phr.","在八点","时刻用 at"],["at noon","phr.","在中午","固定搭配"],["at night","phr.","在夜里","与 in the evening 对照记"],["at the age of","phr.","在……岁时","At the age of six, he began to learn the piano."],["at the moment","phr.","此刻","与现在进行时连用"],["at Christmas","phr.","在圣诞节期间","节日期间用 at；具体那天用 on Christmas Day"],["at the weekend","phr.","在周末","英式用 at the weekend，美式用 on the weekend"]]},{"type":"table","title":"地点与方位介词","head":["单词","词性/音标","释义","考点"],"rows":[["in","prep.","在……里；在大地点","in Guangzhou；arrive in + 大地点"],["on","prep.","在……上；在平面","on the desk；on the wall"],["at","prep.","在（小地点、经过点）","at the bus stop；arrive at + 小地点"],["under","prep.","在……下面","under the tree 在树下"],["behind","prep.","在……后面","behind the door；反义 in front of"],["beside","prep.","在……旁边","= next to"],["between","prep.","在两者之间","between A and B；between you and me"],["among","prep.","在三者以上之中","among the students 在学生当中"],["in front of","phr.","在……前面（外部）","in front of the classroom 在教室前面（教室外）"],["next to","phr.","紧挨着","= beside"],["near","prep.","在……附近","near the school 在学校附近"],["over","prep.","在……上方；越过","a bridge over the river；jump over the wall"],["above","prep.","在……上方（高于）","与 below 相对"],["below","prep.","在……下方","below zero 零度以下"],["across","prep.","横过（表面）","walk across the road"],["through","prep.","穿过（内部）","walk through the forest"],["around","prep.","在……周围；大约","around the world 世界各地；around ten 大约十"],["opposite","prep.","在……对面","opposite the post office 在邮局对面"]]},{"type":"table","title":"常用介词短语","head":["单词","词性/音标","释义","考点"],"rows":[["be good at","phr.","擅长","at 是介词，后接动名词：be good at drawing"],["be interested in","phr.","对……感兴趣","in 后接名词或动名词"],["be afraid of","phr.","害怕","of 后接名词或动名词：be afraid of making mistakes"],["be angry with","phr.","生（某人）的气","对人生气用 with，对事用 at／about"],["be proud of","phr.","为……感到自豪","= take pride in"],["be full of","phr.","充满","= be filled with"],["be late for","phr.","迟到","be late for school 上学迟到"],["be famous for","phr.","因……而闻名","be famous as 作……身份而闻名"],["be different from","phr.","与……不同","= be not the same as"],["by bus","phr.","乘公交车","by + 交通工具单数，不加冠词；on foot 步行是例外"],["with the help of","phr.","在……的帮助下","= with sb’s help"],["instead of","phr.","代替；而不是","后接名词或动名词：instead of watching TV"],["because of","phr.","因为","后接名词、代词或动名词，不接句子"],["thanks to","phr.","多亏；由于","多用于好结果；= because of"],["in order to","phr.","为了","后接动词原形；= so as to"],["according to","phr.","根据","阅读题常用：According to the passage, ..."]]},{"type":"table","title":"并列与从属连词","head":["单词","词性/音标","释义","考点"],"rows":[["and","conj.","和；并且","并列关系；A and B 作主语谓语用复数"],["but","conj.","但是","转折；不能与 although 同时出现"],["or","conj.","或者；否则","Hurry up, or you will be late."],["so","conj.","所以","表结果；不能与 because 同时出现"],["because","conj.","因为","后接句子；回答 Why 的问题"],["although","conj.","虽然","= though；不能与 but 连用"],["if","conj.","如果；是否","引导条件状语从句时「主将从现」"],["unless","conj.","除非","= if ... not；主句用将来时时从句用现在时"],["until","conj.","直到","not ... until 直到……才"],["when","conj.","当……时候","引导时间状语从句"],["while","conj.","当……的时候；然而","while 引导的从句常用进行时"],["since","conj.","自从；既然","since 引导的从句用过去时，主句用现在完成时"],["after","conj.","在……之后","after 与 before 引导时间状语从句"],["before","conj.","在……之前","主句用将来时时从句用现在时"],["as","conj.","当……时；因为","as soon as 一……就……"],["whether","conj.","是否","whether ... or not；引导宾语从句"]]},{"type":"table","title":"关联连词配对","head":["单词","词性/音标","释义","考点"],"rows":[["both ... and","conj.","……和……都","作主语谓语用复数：Both Tom and Jack are here."],["either ... or","conj.","要么……要么","就近原则：Either you or he is right."],["neither ... nor","conj.","既不……也不","就近原则：Neither Tom nor his parents are at home."],["not only ... but also","conj.","不仅……而且","就近原则；也可用于强调写作亮点"],["as soon as","conj.","一……就","主句将来时，从句用一般现在时"],["as long as","conj.","只要","引导条件状语从句"],["so that","conj.","以便；为了","后接目的状语从句，常与 can、could 连用"],["so ... that","conj.","如此……以至于","so + 形容词/副词 + that 从句"],["such ... that","conj.","如此……以至于","such + 名词短语 + that 从句"],["too ... to","conj.","太……而不能","= not ... enough to do；句中含否定意义"],["as ... as","conj.","和……一样","中间用原级：as careful as"],["not as ... as","conj.","不如……","= less ... than"],["even though","conj.","即使；虽然","= even if；同样不与 but 连用"],["whether ... or not","conj.","是否……","引导宾语从句：I do not know whether he will come or not."]]},{"type":"table","title":"语法规则","head":["规则","形式","例句","提示"],"rows":[["时间介词用 in 表大范围，on 表具体某天，at 表时刻与固定短语。","in 2025 / on May 1st / at 8:00","It often rains here in June, and our sports meeting is on June 2nd, starting at 8:00 a.m.","这里六月常下雨，我们的运动会定在六月二日，上午八点开始。\n记住三个例外：at noon、at night、at the weekend；而「某天的上午」要用 on。"],["arrive 的搭配：arrive in + 大地点，arrive at + 小地点；reach 后不加介词。","arrive in Beijing / arrive at the station / reach the station","They arrived in Guangzhou last night and reached the hotel at ten.","他们昨晚到达广州，十点到了酒店。\nget to 也表到达，后接地点；home、there 前不加 to。"],["关联连词的主谓一致：both ... and 用复数，either ... or、neither ... nor、not only ... but also 用就近原则。","Both A and B are ...；Either A or B is ...","Both my sister and I are fond of music, but neither my sister nor I can play the piano well.","我和姐姐都喜欢音乐，但我们俩钢琴都弹不好。\n把动词前面的那个主语圈出来，就近原则只看离动词最近的名词。"],["because of 接名词、代词或动名词，because 接句子，两者可互相改写。","because of + n. / doing；because + 句子","We stayed at home because of the heavy rain, and we stayed at home because it rained heavily.","因为大雨我们待在家里（两种说法意思相同）。\n括号里给的是名词或动名词就选 because of，给的是完整句子就选 because。"],["although 与 but、because 与 so 不能出现在同一个句子里。","Although ... , ... ；Because ... , ...","Although he was tired, he kept working until midnight.","虽然他很累，但他一直工作到午夜。\n中文习惯「虽然……但是……」「因为……所以……」，写英文时只能保留一个连词。"],["介词后面接代词用宾格，接动词用动名词。","be good at doing；look forward to doing","She is good at drawing, and she is looking forward to visiting the art museum.","她擅长画画，而且盼望着去参观美术馆。\nlook forward to 的 to 是介词，不是不定式符号，这是最容易掉进去的坑。"]]},{"type":"table","title":"易错点","head":["错误","正确","原因"],"rows":[["Although it was late, but he kept working.","Although it was late, he kept working.","although 已表示让步，不能再加 but；中文的「虽然……但是……」在英语里只能用一个连词。"],["Because it rained hard, so we stayed at home.","Because it rained hard, we stayed at home.","because 已表示原因，不能再加 so；去掉 so 或用 so 单独写一个句子。"],["Neither Tom nor his parents is at home now.","Neither Tom nor his parents are at home now.","neither ... nor 连接主语时遵循就近原则，离动词最近的是 his parents（复数），谓语用 are。"],["He is good at swim and he wants to join the swimming club.","He is good at swimming and he wants to join the swimming club.","at 是介词，后面接动词要用动名词形式 swimming，不能用动词原形。"],["I will be back after two days.","I will be back in two days.","表示「一段时间之后」用 in + 一段时间，与将来时连用；after 后多接过去的时间点或具体时刻。"]]}],"questions":[{"id":"eng-vocab-pos-8-q1","type":"choice","stem":"We usually have a class meeting ______ Friday afternoon, and it begins ______ 4:30.","answer":"A","explain":"Friday afternoon 是具体某一天的下午，用 on；4:30 是时刻，用 at。B 项 in 用于月份、年份或泛指的上午下午；C 项第二空 in 不能接具体时刻；D 项两项都错。这一题正好考「具体某天用 on、时刻用 at」这个固定判断。","options":["on; at","in; at","on; in","at; on"],"difficulty":2,"tags":["介词","时间介词","in/on/at"]},{"id":"eng-vocab-pos-8-q2","type":"choice","stem":"Neither Tom nor his parents ______ interested in that film, so they stayed at home.","answer":"A","explain":"neither ... nor 连接主语时谓语遵循就近原则，离动词最近的是 his parents（复数），用 are。B、C、D 三项都是单数形式，与 parents 不一致。判断口诀：把动词前面最近的名词圈出来，它的数就是谓语的数。","options":["are","is","was","has been"],"difficulty":3,"tags":["连词","neither...nor","主谓一致"]},{"id":"eng-vocab-pos-8-q3","type":"choice","stem":"______ he is only twelve years old, he knows a lot about space science.","answer":"A","explain":"前后是让步关系：「虽然只有十二岁，却懂得很多航天知识」，用 Although。B 项 Because 表原因，与后半句的转折意味不符；C 项 So 不能放句首引导从句来表让步；D 项 But 是并列连词，也不能与后面的分句这样搭配。注意句中已经用了 Although，就不能再加 but。","options":["Although","Because","So","But"],"difficulty":2,"tags":["连词","although","让步状语从句"]},{"id":"eng-vocab-pos-8-q4","type":"choice","stem":"She is looking forward to ______ her pen friend in Beijing next month.","answer":"A","explain":"look forward to 中的 to 是介词，后面要接名词或动名词，所以用 visiting。B 项把 to 当不定式符号是常见错误；C、D 两项形式与介词后接成分的要求不符。同类还有 be good at doing、be interested in doing。","options":["visiting","visit","visits","visited"],"difficulty":3,"tags":["介词","动名词","固定搭配"]},{"id":"eng-vocab-pos-8-q5","type":"choice","stem":"The old man was ill, ______ he still came to the meeting on time.","answer":"A","explain":"前后是转折关系，且中间是逗号连接的并列分句，用并列连词 but。B 项 although 引导从句，不能这样连接两个分句；C 项 because 表原因，与「仍然准时到会」的转折不符；D 项 so 表结果，前句并不能推出「准时到会」的结果。","options":["but","although","because","so"],"difficulty":2,"tags":["连词","but","并列句"]},{"id":"eng-vocab-pos-8-q6","type":"fill","stem":"He was late for school ______ (because / because of) the heavy rain.","answer":"because of","explain":"空后是名词短语 the heavy rain，所以用 because of。because 后面必须接完整的句子，如 because it rained heavily。同类短语还有 thanks to（多亏）、instead of（而不是）。","difficulty":2,"tags":["介词","because of","连词辨析"]}]},{"id":"eng-vocab-topic-1","title":"话题词汇·人与自我","subtitle":"话题词汇 · People and daily life","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"外貌与性格、兴趣与爱好、情绪与感受、日常作息五组词，专供「介绍自己」「我的日常生活」类书面表达与听力人物介绍题使用。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「介绍自己」类书面表达的骨架是四组词块：be good at、be interested in、get on well with、spend ... (in) doing。","explain":"广州中考书面表达多次考「自我介绍 / 我的日常」。先写外貌与性格，再写爱好与作息，每段用两三个词块，句子结构稳定，内容分与语言分都容易拿满。"},{"level":"重点","text":"描写人分两条路：「be + 性格形容词」与「with + 外貌名词」。","explain":"性格用 be 动词（He is honest and friendly.），外貌特征常用 with 介宾短语（the boy with short hair and glasses）。选择题常把 with 与 has 混设——主语后已有动词时只能用 with，不能再接 has。"},{"level":"重点","text":"情绪形容词 -ed 与 -ing 的选择看主语是人还是物。","explain":"excited/exciting、surprised/surprising、bored/boring 都要成对分清：主语是人用 -ed（I am excited about the trip.），主语是事或物用 -ing（The trip is exciting.）。这是单选几乎每年都设的干扰项。"},{"level":"次重点","text":"频率副词的位置：be 动词之后，实义动词之前。","explain":"He always gets up early. 与 He is always late. 两句话要都能写对。never、seldom、hardly 本身含否定，不能再与 not 连用。"},{"level":"次重点","text":"听力人物介绍题常以同义替换出现，要按「性格 + 爱好」两类词抓信息。","explain":"原文 hard-working，选项写 works hard；原文 be fond of，选项写 likes。听时只记这两类词，不必逐词听懂整句。"},{"level":"了解","text":"日常作息短语的冠词有规律：have breakfast、go to bed 不加冠词，have a rest、take a shower 要加 a。","explain":"语法填空与改错常在这一类短语上设点，背短语时把冠词一起背下来最稳。"}]},{"type":"table","title":"外貌与身材","head":["单词","词性/音标","释义","考点"],"rows":[["tall","adj.","高的","形容人高矮用 tall/short，不用 high/low"],["short","adj.","矮的；短的","一词两义，反义词是 tall 或 long"],["slim","adj.","苗条的","褒义，形容人瘦而匀称"],["thin","adj.","瘦的；薄的","形容人偏中性，形容物是「薄的」"],["strong","adj.","强壮的；浓的","strong tea 是「浓茶」，不是「强壮的茶」"],["handsome","adj.","英俊的","多形容男性"],["pretty","adj.","漂亮的","多形容女性或小孩，比 beautiful 口语化"],["lovely","adj.","可爱的","常形容小孩、动物；以 -ly 结尾但是形容词"],["young","adj.","年轻的","反义 old；比较级 younger"],["hair","n.","头发","不可数，a girl with long hair；说「几根头发」才用 hairs"],["glasses","n.","眼镜","常用复数，wear glasses；单数 glass 是玻璃或玻璃杯"],["smile","n., v.","微笑","smile at sb 朝某人微笑"],["weight","n.","体重；重量","lose weight 减肥，put on weight 增重"]]},{"type":"table","title":"性格与品质","head":["单词","词性/音标","释义","考点"],"rows":[["kind","adj.","友善的；和蔼的","be kind to sb 对某人友好"],["friendly","adj.","友好的","以 -ly 结尾但是形容词；比较级 friendlier"],["honest","adj.","诚实的","h 不发音，前面用 an：an honest boy"],["polite","adj.","有礼貌的","be polite to sb；反义词是 impolite"],["brave","adj.","勇敢的","It is brave of sb to do sth 是作文可用句型"],["careful","adj.","细心的","be careful with sth 小心某物"],["careless","adj.","粗心的","-less 表否定，与 careful 相对"],["shy","adj.","害羞的","比较级 shyer；反义 outgoing"],["quiet","adj.","安静的","与 quite（相当）只差一个字母，拼写高频错"],["outgoing","adj.","外向的","作文写性格时的加分词"],["active","adj.","积极的；活跃的","take an active part in 积极参加"],["patient","adj.","有耐心的","be patient with sb 对某人有耐心"],["lazy","adj.","懒惰的","反义 hard-working；比较级 lazier"],["hard-working","adj.","勤奋的","可用 works hard 同义替换"],["clever","adj.","聪明的","同义 smart；比较级 cleverer"],["strict","adj.","严格的","be strict with sb 对人严格，be strict in sth 对事严格"],["humorous","adj.","幽默的","名词是 humour/humor；写性格的加分词"]]},{"type":"table","title":"兴趣与爱好","head":["单词","词性/音标","释义","考点"],"rows":[["hobby","n.","爱好","复数 hobbies，词尾 y 变 ies"],["interest","n.","兴趣","show interest in sth 对……表现出兴趣"],["be interested in","phr.","对……感兴趣","in 是介词，后接名词或 doing"],["be good at","phr.","擅长","at 是介词，后接 doing；同义 do well in"],["enjoy","v.","享受；喜欢","enjoy doing sth，没有 enjoy to do 的说法"],["prefer","v.","更喜欢","prefer A to B；prefer to do rather than do"],["collect","v.","收集","collect stamps 集邮"],["draw","v.","画画；拉","过去式 drew；draw a picture 画一幅画"],["dance","v., n.","跳舞；舞蹈","go dancing 去跳舞"],["music","n.","音乐","不可数；listen to music"],["guitar","n.","吉他","弹奏乐器要加 the：play the guitar"],["piano","n.","钢琴","play the piano；复数 pianos"],["chess","n.","国际象棋","play chess 不加 the"],["cartoon","n.","卡通片；漫画","watch cartoons 看卡通片"],["join a club","phr.","加入社团","join 后接组织，不能加 in"],["free time","phr.","空闲时间","in your free time 在你的空闲时间"]]},{"type":"table","title":"情绪与感受","head":["单词","词性/音标","释义","考点"],"rows":[["happy","adj.","高兴的；幸福的","be happy to do sth 乐意做某事"],["glad","adj.","高兴的","be glad to do sth，多用于书信客套"],["excited","adj.","兴奋的","主语是人；形容事物用 exciting"],["exciting","adj.","令人兴奋的","an exciting match 一场激动人心的比赛"],["surprised","adj.","惊讶的","be surprised at sth；to one’s surprise 令人惊讶的是"],["angry","adj.","生气的","be angry with sb about sth，对人用 with"],["sad","adj.","难过的","比较级 sadder，双写 d"],["worried","adj.","担心的","be worried about sb/sth"],["nervous","adj.","紧张的","考试、演讲前常用，feel nervous"],["afraid","adj.","害怕的","be afraid of doing sth 怕做某事；be afraid to do sth 不敢做"],["tired","adj.","疲倦的","be tired of 是「厌烦」，与 be tired（累）不同"],["bored","adj.","感到无聊的","主语是人；形容事物用 boring"],["proud","adj.","自豪的","be proud of sb 为某人自豪"],["lonely","adj.","孤独的","alone 指独自一人（客观），lonely 指孤独（感受）"],["feeling","n.","感受；感觉","常用复数 feelings；hurt your feelings 伤你的感情"],["look forward to","phr.","盼望","to 是介词，后接名词或 doing"]]},{"type":"table","title":"日常作息","head":["单词","词性/音标","释义","考点"],"rows":[["get up","phr.","起床","与 get on（上车）拼写相近，别混"],["go to bed","phr.","上床睡觉","bed 前不加 the；go to sleep 强调「入睡」"],["brush teeth","phr.","刷牙","teeth 是 tooth 的复数，不能写 brush tooth"],["have breakfast","phr.","吃早饭","三餐前不加冠词"],["early","adv., adj.","早地；早的","既是形容词也是副词，没有 earlily 这个词"],["late","adv., adj.","晚地；迟的","be late for school 上学迟到"],["weekday","n.","工作日","on weekdays 在平日"],["weekend","n.","周末","英式 at the weekend，美式 on weekends"],["do homework","phr.","做作业","homework 不可数，不能说 homeworks"],["housework","n.","家务","不可数，do housework 做家务"],["take a shower","phr.","洗澡","也可说 have a shower"],["daily","adj.","每日的；日常的","daily life 日常生活，作文高频词"],["alarm clock","n.","闹钟","set the alarm clock 定闹钟"],["on time","phr.","准时","与 in time（及时）区别：in time 强调赶得上"],["hurry","v., n.","匆忙","hurry up 快点；in a hurry 匆忙地"],["stay up","phr.","熬夜","stay up late 熬夜到很晚"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["be good at (doing) sth","擅长（做）某事","at 是介词，后接 doing；同义 do well in，写作中换用可避免重复。"],["be interested in sth","对……感兴趣","主语必须是人，不能写成 be interesting in。"],["get on well with sb","与某人相处融洽","也可说 get along well with sb。"],["take part in an activity","参加活动","参加正式活动用 take part in，加入组织用 join。"],["spend your free time (in) doing sth","花空闲时间做某事","主语必须是人；介词 in 可以省略。"],["be proud of","为……感到自豪","of 是介词，后接名词或 doing。"],["hurry up","快点","用于催促别人；名词形式是 in a hurry。"],["stay up late","熬夜","后面不能再加 the homework 这类宾语。"]]},{"type":"list","title":"应试策略","items":["「自我介绍」类书面表达按「外貌 + 性格 + 爱好 + 作息」四句铺开，每句套一个词块，写够四句内容分就基本到手。","听力人物介绍题先记下性格词（kind、hard-working）与爱好词（be fond of、enjoy），答案往往就是这些词的改写。","情绪形容词的 -ed/-ing 是单选常设的干扰项，写作文时也要检查：I am excited 不能写成 I am exciting。","写「日常作息」段落时把频率副词与时间短语（every day、twice a week）一起用，同时保证全段用一般现在时。"]}],"questions":[{"id":"eng-vocab-topic-1-q1","type":"choice","stem":"Tom is ______ honest boy and he never tells lies.","answer":"A","explain":"honest 的 h 不发音，读音以元音音素开头，所以用 an。B 项 a 用于辅音音素开头的词前；C 项 the 表特指，本句是第一次提到且泛指「一个诚实的男孩」；D 项不填则单数可数名词 boy 前缺冠词。","options":["an","a","the","不填"],"difficulty":2,"tags":["话题词汇","性格","冠词"]},{"id":"eng-vocab-topic-1-q2","type":"choice","stem":"My sister is ______ in music and she practises the piano every day.","answer":"A","explain":"主语 My sister 是人，表示「对……感兴趣」用 be interested in。B 项 interesting 意为「令人感兴趣的」，主语应是事物；C 项 interest 是名词或动词，此处已有 be 动词作谓语；D 项 interests 是动词第三人称单数形式，同样与 be 动词重复。","options":["interested","interesting","interest","interests"],"difficulty":1,"tags":["话题词汇","爱好","-ed/-ing 形容词"]},{"id":"eng-vocab-topic-1-q3","type":"choice","stem":"— How do you like the trip to the science museum? — It is really ______.","answer":"A","explain":"答语中的 It 指 the trip，是事物，用 -ing 形容词说明「令人兴奋」。B 项 excited 用于人；C 项 excite 是动词，不能作 is 后的表语；D 项 excitement 是名词，也不能单独作表语。","options":["exciting","excited","excite","excitement"],"difficulty":2,"tags":["话题词汇","情绪","-ed/-ing 形容词"]},{"id":"eng-vocab-topic-1-q4","type":"choice","stem":"He ______ late for class, because he always gets up early and arrives on time.","answer":"A","explain":"never 是频率副词，放在 be 动词之后、实义动词之前，故用 is never。B 项把 never 放在 is 前，位置错误；C 项缺谓语动词，本句需要 be 动词；D 项 does never 不成立，never 已含否定，不需要助动词。","options":["is never","never is","never","does never"],"difficulty":2,"tags":["话题词汇","作息","频率副词"]},{"id":"eng-vocab-topic-1-q5","type":"fill","stem":"用括号内词的适当形式填空：He is good at ______ (draw) and he wants to join the art club.","answer":"drawing","explain":"be good at 中的 at 是介词，后接动名词，所以填 drawing。若填 draw，则是动词原形，介词后不能直接跟动词原形。","difficulty":1,"tags":["话题词汇","爱好","动名词"]}]},{"id":"eng-vocab-topic-2","title":"话题词汇·家庭与朋友","subtitle":"话题词汇 · Family and friends","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"家庭成员、亲戚称谓、朋友交往与日常礼貌用语四组词，用于「我的家庭」「我的朋友」类书面表达、听力人物关系题与补全对话。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「我的家庭」类书面表达按「人数 + 成员身份 + 职业 + 性格与相处」四步写。","explain":"常用开头 There are four people in my family.，再逐个写成员，配 be kind to、get on well with 收尾。结构固定，句子不易出错。"},{"level":"重点","text":"family 作主语时主谓一致要看意思：作为整体用单数，指全体成员用复数。","explain":"My family is a big one.（整体）与 My family are all fond of music.（成员）都要会写。句中出现 all、both 时 family 一定指成员，谓语用复数。"},{"level":"重点","text":"称谓词 Mr / Mrs / Ms / Miss 传递的信息不同，听力人物关系题常靠它判断。","explain":"Mr 指男士（不论婚否），Mrs 指已婚女士，Miss 指未婚女士，Ms 不说明婚姻状况。题问 Who is the woman? 时，听到 Mrs Green 就不能选 Miss Green。"},{"level":"次重点","text":"感谢与道歉的应答必须配对：Thank you 对 You’re welcome，Sorry 对 Never mind / That’s all right。","explain":"情景对话题（听力与单选）常把应答语错位设置——用 Never mind 答感谢、用 You’re welcome 答道歉都是错的，先判断语境再选句子。"},{"level":"次重点","text":"与朋友交往的搭配要连介词一起背：make friends with sb、get on well with sb、share sth with sb、be friendly to sb。","explain":"常见错误是 make friend with（少 s）、get on well to（介词错）、share sth to（应为 with），都是单选与语法填空的设点处。"},{"level":"了解","text":"介绍他人用 This is ...，不用 He is ...；电话中自我介绍也用 This is ... speaking。","explain":"这类语用规则在听力对话与补全对话里考，属于「得体表达」的给分点。"}]},{"type":"table","title":"家庭成员","head":["单词","词性/音标","释义","考点"],"rows":[["family","n.","家庭；家人","作整体时谓语用单数，指成员时用复数"],["parent","n.","父亲或母亲","复数 parents 指父母双方"],["grandparent","n.","祖父母；外祖父母","复数常指祖父母两人"],["grandfather","n.","祖父；外祖父","口语常用 grandpa"],["grandmother","n.","祖母；外祖母","口语常用 grandma"],["father","n.","父亲","口语用 dad"],["mother","n.","母亲","英式口语 mum，美式口语 mom"],["son","n.","儿子",""],["daughter","n.","女儿","gh 不发音，拼写易漏"],["brother","n.","兄弟","英语不分哥哥弟弟"],["sister","n.","姐妹","英语不分姐姐妹妹"],["child","n.","孩子","复数 children，不规则变化"],["baby","n.","婴儿","复数 babies，y 变 ies"],["twin","n.","双胞胎之一","复数 twins 常指一对双胞胎"],["only child","phr.","独生子女","作文写家庭情况时常用"],["member","n.","成员","a member of my family 我家的一员"]]},{"type":"table","title":"亲戚与称谓","head":["单词","词性/音标","释义","考点"],"rows":[["relative","n.","亲戚","可数名词，a close relative 一位近亲"],["uncle","n.","叔叔；伯伯；舅舅","英语不分父方母方"],["aunt","n.","姑姑；姨母","读音与 ant（蚂蚁）相同，注意语境"],["cousin","n.","堂（表）兄弟姐妹","不分男女、不分堂表，听力关系题高频"],["husband","n.","丈夫",""],["wife","n.","妻子","复数 wives，f 变 ves"],["married","adj.","已婚的","be married to sb，不能用 with"],["gentleman","n.","先生；绅士","复数 gentlemen"],["sir","n.","先生；长官","单独使用，不与姓连用：Yes, sir."],["madam","n.","夫人；女士","对陌生女性的礼貌称呼"],["Mr","n.","先生","用在姓氏前：Mr Green"],["Mrs","n.","夫人","指已婚女性，读音与拼写都易错"],["Ms","n.","女士","不说明婚姻状况，书信中对女性常用"]]},{"type":"table","title":"朋友与交往","head":["单词","词性/音标","释义","考点"],"rows":[["friend","n.","朋友","be friends with sb 与某人成为朋友，friends 用复数"],["friendship","n.","友谊","不可数，写朋友话题的主题词"],["classmate","n.","同班同学",""],["penfriend","n.","笔友","美式常说 pen pal"],["share","v.","分享；共用","share sth with sb 介词用 with"],["trust","v., n.","信任","trust sb 直接接人"],["invite","v.","邀请","invite sb to a party / to do sth"],["invitation","n.","邀请；请柬","an invitation 一封请柬"],["chat","v., n.","聊天","过去式 chatted，双写 t"],["argue","v.","争吵；争论","argue with sb about sth"],["understand","v.","理解","过去式 understood"],["help each other","phr.","互相帮助",""],["make friends with","phr.","与……交朋友","friends 必须用复数"],["get on well with","phr.","与……相处融洽","同义 get along well with"],["keep in touch","phr.","保持联系","接人时加 with：keep in touch with sb"],["be friendly to","phr.","对……友好","friendly 是形容词，介词用 to"],["together","adv.","一起","get together 团聚"]]},{"type":"table","title":"礼貌用语与日常应答","head":["单词","词性/音标","释义","考点"],"rows":[["please","adv.","请","放句末时前面加逗号：Sit down, please."],["thank you","phr.","谢谢你",""],["thanks to","phr.","多亏；由于","是短语介词，与 thank you 意思完全不同"],["sorry","adj.","抱歉的；难过的","be sorry for/about sth"],["Excuse me.","phr.","打扰一下","用于打扰别人之前；道歉用 I’m sorry."],["You're welcome.","phr.","不用谢","只用于回答感谢"],["Never mind.","phr.","没关系","回答道歉或安慰对方"],["Not at all.","phr.","不客气；一点也不","既可答感谢，也可表「完全不」"],["Would you like ...?","phr.","你想要……吗","后接名词或 to do；答语 Yes, please. / No, thanks."],["What about ...?","phr.","……怎么样","about 是介词，后接名词或 doing"],["Help yourself.","phr.","请自便；随便吃","招待客人吃饭时的客气话"],["Have a good time.","phr.","玩得开心","也可说 Enjoy yourself."],["Best wishes.","phr.","祝好","书信、贺卡结尾常用"],["get together","phr.","团聚；聚会","家人团聚常用 get together and have a big dinner"]]},{"type":"table","title":"家庭活动与情感","head":["单词","词性/音标","释义","考点"],"rows":[["dinner","n.","正餐；晚餐","have dinner 不加冠词"],["picnic","n.","野餐","go on a picnic 去野餐"],["birthday","n.","生日","celebrate your birthday 庆祝生日"],["present","n.","礼物","同义 gift；a birthday present"],["celebrate","v.","庆祝","后直接接节日或生日，不加介词"],["look after","phr.","照顾","同义 take care of"],["take care of","phr.","照顾；处理","care 前不加 the"],["do housework","phr.","做家务","housework 不可数"],["help","v., n.","帮助","help sb (to) do sth 或 help sb with sth"],["miss","v.","想念；错过","一词两义；miss doing sth 错过做某事"],["care","v., n.","在乎；关心","care about sb/sth 关心某人某物"],["love","v., n.","爱；喜爱","love doing sth 与 love to do sth 都可以"],["kind","adj.","友善的","be kind to sb 对人友好"],["proud","adj.","自豪的","be proud of sb"],["support","v.","支持；供养","support your family 养家"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["get on well with sb","与某人相处融洽","也可说 get along well with sb。"],["make friends with sb","与某人交朋友","friends 用复数，不能说 make friend with。"],["keep in touch with sb","与某人保持联系","写朋友分别的作文常用这句收尾。"],["take care of sb","照顾某人","同义 look after；care 前不加冠词。"],["share sth with sb","与某人分享某物","介词用 with，不用 to。"],["get together","团聚","We get together and have a big dinner. 是常用句。"],["be kind to sb","对某人友善","介词用 to，同义 be friendly to。"],["help sb with sth","帮某人做某事","也可说 help sb (to) do sth。"]]},{"type":"list","title":"应试策略","items":["写「我的家庭」先报人数再逐个介绍，用 There are ... people in my family. 起句最稳，后面每句只写一个成员。","介绍朋友时写「认识多久 + 共同爱好 + 相处的感受」三句，比只写 He is kind. 的内容分高得多。","听力人物关系题听到 cousin、uncle、classmate 这类词要立刻在草稿上写下关系，题目问的往往就是这层关系。","补全对话先判断语境属于「感谢」「道歉」还是「请求」，再选对应应答语，不要按中文直译去选。"]}],"questions":[{"id":"eng-vocab-topic-2-q1","type":"choice","stem":"My family ______ all fond of watching football matches on TV.","answer":"A","explain":"句中的 all 说明 family 指的是「全家人」，是复数概念，谓语用 are。B 项 is 把 family 当作一个整体，与 all 矛盾；C 项 be 不能单独作谓语；D 项 am 只能与 I 连用。","options":["are","is","be","am"],"difficulty":3,"tags":["话题词汇","家庭","主谓一致"]},{"id":"eng-vocab-topic-2-q2","type":"choice","stem":"— Thank you for helping me with my English. — ______","answer":"A","explain":"回答感谢用 You’re welcome.。B 项 Never mind 用于回答道歉或安慰别人；C 项用于听到不好的消息时表示同情；D 项用于回应对方的提议或询问，都不能回答感谢。","options":["You're welcome.","Never mind.","I'm sorry to hear that.","Yes, please."],"difficulty":1,"tags":["话题词汇","礼貌用语","情景交际"]},{"id":"eng-vocab-topic-2-q3","type":"choice","stem":"Lucy and I ______ on well with each other since we were in Grade Seven.","answer":"A","explain":"since 引导的时间状语从句要与现在完成时连用，表示从过去持续到现在，故用 have got。B 项是一般过去时，只说明过去，不能与 since 搭配；C 项一般现在时不能表示持续；D 项将来时与 since 引导的过去时间矛盾。","options":["have got","got","get","will get"],"difficulty":3,"tags":["话题词汇","朋友","现在完成时"]},{"id":"eng-vocab-topic-2-q4","type":"choice","stem":"The man over there is my ______, my father’s brother.","answer":"A","explain":"father’s brother 指父亲的兄弟，即叔叔、伯伯，用 uncle。B 项 aunt 指女性；C 项 parent 指父母；D 项 cousin 指堂（表）兄弟姐妹，都不符合「父亲的哥哥或弟弟」这一关系。","options":["uncle","aunt","parent","cousin"],"difficulty":1,"tags":["话题词汇","亲戚关系","听力高频"]},{"id":"eng-vocab-topic-2-q5","type":"fill","stem":"用括号内词的适当形式填空：Mr Green is a teacher and he is ______ (friend) to all his students.","answer":"friendly","explain":"be friendly to sb 表示「对某人友好」，friendly 以 -ly 结尾但仍是形容词，可以作表语。若填 friend 或 friendship，都是名词，不能与 is ... to 构成「友好」的表语结构。","difficulty":1,"tags":["话题词汇","交往","词性判断"]}]},{"id":"eng-vocab-topic-3","title":"话题词汇·学校生活","subtitle":"话题词汇 · School life","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"科目与课程、校园设施、师生同学、学习活动与考试五组词，覆盖「我的学校生活」书面表达与听力校园场景题的全部常用词。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「我的学校生活」书面表达的必备词块：take part in after-school activities、be good at、hand in、get on well with、make progress。","explain":"这类作文按「学校设施 + 课程 + 活动 + 感受」四句展开，每句一个词块即可。评分看内容完整与语言准确，不必硬写长难句。"},{"level":"重点","text":"explain / discuss / borrow 一类动词的介词不能丢：explain sth to sb、discuss sth with sb、borrow sth from sb。","explain":"单选与语法填空高频。没有 explain sb sth 的说法；discuss 后可直接接宾语，也可以接 with sb。"},{"level":"重点","text":"progress 不可数，improve 后直接接宾语，不再加 better。","explain":"make progress 不能说 make a progress；improve your English 不能说 improve your English better，因为 improve 已含「变得更好」的意思。"},{"level":"次重点","text":"学科名词作主语时谓语一般用单数，maths、physics 虽以 -s 结尾仍是单数。","explain":"Maths is my favourite subject. 不能写成 Maths are。物理、数学都是学科名，谓语用 is。"},{"level":"次重点","text":"听力校园场景题常考三件事：科目、时间表、考试安排。","explain":"听前先看题干问的是 subject、time 还是 place，听到 timetable、lab、exam、mark 时立刻定位，答案多是原文的改写（如 a quarter past eight 写成 8:15）。"},{"level":"了解","text":"称呼老师用 Mr / Mrs / Ms + 姓，不能写成 Teacher Li。","explain":"补全对话与书面表达中写 Teacher Wang 是常见失分点，英语里 teacher 不是称呼语。"}]},{"type":"table","title":"科目与课程","head":["单词","词性/音标","释义","考点"],"rows":[["subject","n.","科目；主题","问科目用 What's your favourite subject?"],["maths","n.","数学","英式 maths；作主语谓语用单数"],["science","n.","科学","不可数；scientist 是「科学家」"],["history","n.","历史","学科名在句中不大写；语言名 English、Chinese 必须大写"],["geography","n.","地理","拼写 g-e-o，容易漏字母"],["biology","n.","生物","拼写 b-i-o-l-o-g-y，容易少写 o"],["physics","n.","物理","以 -s 结尾但作单数"],["chemistry","n.","化学","chemist 是「化学家；药剂师」"],["PE","n.","体育课","physical education 的缩写，两个字母都大写"],["art","n.","美术；艺术","不可数，an art lesson 一节美术课"],["music","n.","音乐","不可数，a music lesson 一节音乐课"],["lesson","n.","课","have lessons 上课"],["class","n.","课；班级","in class 在课上，不加 the"],["timetable","n.","课程表","英式 timetable，美式 schedule"],["term","n.","学期","this term 作时间状语，常与一般现在时或现在完成时连用"]]},{"type":"table","title":"校园设施","head":["单词","词性/音标","释义","考点"],"rows":[["classroom","n.","教室",""],["playground","n.","操场","on the playground 在操场上"],["library","n.","图书馆","borrow books from the library"],["laboratory","n.","实验室","常缩写为 lab；do experiments in the lab"],["dining hall","n.","餐厅","也可说 dining room"],["gym","n.","体育馆","复数 gyms"],["teachers' office","n.","教师办公室","teachers 用复数所有格 teachers’"],["school gate","n.","校门","at the school gate 在校门口，约见地点高频"],["blackboard","n.","黑板","on the blackboard 在黑板上"],["computer room","n.","电脑房",""],["reading room","n.","阅览室","与 library 区别：阅览室的书不外借"],["hall","n.","礼堂；大厅","hold a meeting in the hall"],["sports field","n.","运动场","on the sports field 在运动场"]]},{"type":"table","title":"师生与同学","head":["单词","词性/音标","释义","考点"],"rows":[["teacher","n.","教师","称呼用 Mr/Ms + 姓，不直呼 teacher"],["student","n.","学生",""],["pupil","n.","小学生","多用于小学阶段"],["classmate","n.","同班同学",""],["monitor","n.","班长","作职务时前面不加冠词：He was made monitor."],["headmaster","n.","校长","女校长用 headmistress"],["respect","v., n.","尊重","respect sb 后直接接人，不加介词"],["discuss","v.","讨论","discuss sth with sb"],["explain","v.","解释","explain sth to sb，没有 explain sb sth"],["praise","v., n.","表扬","praise sb for sth 因某事表扬某人"],["be strict with","phr.","对……严格","对人用 with，对事用 in"],["take an active part in","phr.","积极参加","比 take part in 更强调主动"]]},{"type":"table","title":"学习活动","head":["单词","词性/音标","释义","考点"],"rows":[["study","v., n.","学习；研究","强调学习的过程；learn 强调「学会」的结果"],["learn","v.","学会；学习","learn to do sth；learn about sth 了解"],["practise","v.","练习","英式动词 practise，后接 doing"],["review","v., n.","复习；评论","review the lessons before an exam"],["preview","v.","预习","与 review 方向相反"],["recite","v.","背诵","recite a text 背课文"],["take notes","phr.","记笔记","notes 用复数"],["hand in","phr.","上交","与 hand out（分发）方向相反"],["hand out","phr.","分发","与 hand in（上交）方向相反，注意介词搭配 hand sth out"],["group work","phr.","小组合作","常与 in groups 换用"],["project","n.","课题；项目","do a project 做一个课题"],["dictation","n.","听写","have a dictation 听写"],["discussion","n.","讨论","have a discussion about sth"],["experiment","n.","实验","do an experiment 做实验"],["answer","v., n.","回答；答案","作动词直接接宾语：answer the question；名词后接 to"]]},{"type":"table","title":"考试与成绩","head":["单词","词性/音标","释义","考点"],"rows":[["exam","n.","考试","take an exam 参加考试；pass an exam 通过考试"],["test","n., v.","测验","have a test 测验"],["mark","n.","分数","get good marks，常用复数"],["score","n., v.","得分；比分","也可指比赛的比分"],["grade","n.","成绩；年级","in Grade Nine 在九年级"],["result","n.","结果；成绩","the result of the exam 考试结果"],["pass","v.","通过；传递","过去式 passed，与 past 拼写、读音都要分开"],["fail","v.","不及格；失败","fail the exam 不加 in；fail to do sth 未能做某事"],["mistake","n.","错误","make a mistake 犯错；by mistake 错误地"],["correct","v., adj.","改正；正确的","correct the mistakes 改正错误"],["progress","n.","进步","不可数，make progress 不能说 make a progress"],["improve","v.","提高；改善","improve your English，后面不再加 better"],["prepare for","phr.","为……做准备","prepare for an exam 备考"],["paper","n.","试卷；纸","试卷可数，a paper；纸张不可数"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["take part in after-school activities","参加课外活动","参加活动用 take part in，不用 join。"],["be good at sth","擅长某事","同义 do well in，作文中换用可避免重复。"],["hand in your homework","交作业","hand in 是上交，hand out 是分发。"],["make progress","取得进步","progress 不可数，不能说 make a progress。"],["explain sth to sb","向某人解释某事","介词只能用 to，不能用 for。"],["discuss sth with sb","与某人讨论某事","discuss 后直接接讨论的内容。"],["prepare for an exam","备考","prepare for 后接名词或 doing。"],["be strict with sb","对某人严格","对人用 with，对事用 in。"]]},{"type":"list","title":"应试策略","items":["写「我的学校生活」先写校园设施与课程，再写活动与感受，用 first、then、after that 串起来，段落就不会散。","听力前先圈出题干里的疑问词（What subject / When / Where），听时只抓对应信息，不必逐词翻译。","词形变化题先判断空格要名词还是形容词：the ______ of 后填名词（discussion、improvement），a ______ boy 前填形容词。","书面表达里「进步」用 make progress、「提高」用 improve 各写一次，避免同一个词重复出现。"]}],"questions":[{"id":"eng-vocab-topic-3-q1","type":"choice","stem":"Our teacher explained the difficult sentence ______ us again.","answer":"A","explain":"explain 的固定搭配是 explain sth to sb，介词用 to。B 项 for 表示「为某人」，不能与 explain 构成这一结构；C 项 with 用于 discuss sth with sb；D 项 at 不与 explain 搭配。","options":["to","for","with","at"],"difficulty":2,"tags":["话题词汇","学校生活","固定搭配"]},{"id":"eng-vocab-topic-3-q2","type":"choice","stem":"Maths ______ my favourite subject, but physics ______ hard for me.","answer":"A","explain":"maths 与 physics 虽然都以 -s 结尾，但都是学科名称，作主语时谓语用单数 is。B、C、D 三项都把其中一个或两个当成了复数，属于典型错误。","options":["is; is","are; are","is; are","are; is"],"difficulty":3,"tags":["话题词汇","科目","主谓一致"]},{"id":"eng-vocab-topic-3-q3","type":"choice","stem":"You had better ______ the mistakes in your homework before you hand it in.","answer":"A","explain":"had better 后接动词原形，所以填 correct。B 项是 V-ing 形式；C 项是动词不定式，had better 后不加 to；D 项是副词，不能作谓语。","options":["correct","correcting","to correct","correctly"],"difficulty":2,"tags":["话题词汇","考试","had better"]},{"id":"eng-vocab-topic-3-q4","type":"choice","stem":"I ______ my English dictionary to my classmate yesterday, so I can’t use it now.","answer":"A","explain":"lend sth to sb 表示「把某物借给别人」，主语是物主，与「现在自己用不了」相符。B 项 borrow 是「借入」，要用 borrow sth from sb；C 项 return 是「归还」，归还后自己就能用了；D 项 bring 是「带来」，与借词典无关。","options":["lent","borrowed","returned","brought"],"difficulty":2,"tags":["话题词汇","同学交往","借还方向"]},{"id":"eng-vocab-topic-3-q5","type":"fill","stem":"用括号内词的适当形式填空：Our English teacher often lets us have a ______ (discuss) in groups.","answer":"discussion","explain":"冠词 a 后需要名词，discuss 的名词形式是 discussion，have a discussion 意为「进行讨论」。若填 discuss，则是动词原形，不能放在 a 之后。","difficulty":1,"tags":["话题词汇","学习活动","词性转换"]}]},{"id":"eng-vocab-topic-4","title":"话题词汇·饮食与健康","subtitle":"话题词汇 · Food and health","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"食物饮料、味道烹饪、身体疾病、运动锻炼与健康习惯五组词，覆盖「健康生活」建议类书面表达与看病、点餐类听力对话。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"「健康生活」建议类作文的内容按三块写，每块有固定词块：keep a balanced diet、do exercise regularly、get enough sleep。","explain":"反面写 stay away from junk food、don’t stay up late。主体段写三句就够，句式统一用 We should ... 或 It is important to ...，内容分与语言分都稳。"},{"level":"重点","text":"三餐、疾病与药品的冠词用法要看可数性：have a fever / have a cough / have a headache 要加 a，have breakfast 不加冠词，take medicine 用零冠词。","explain":"单选与语法填空常考。medicine 不可数，不能说 a medicine；三餐前不加冠词是很固定的规则。"},{"level":"重点","text":"taste、smell、look、sound、feel 作系动词后接形容词，不能接副词。","explain":"The soup tastes good. 不能写成 tastes well。well 作形容词只表示「身体好」，所以 He looks well. 是「他看上去很健康」，不是「他看得很仔细」。"},{"level":"次重点","text":"ill 与 sick 的位置不同：ill 只作表语，sick 可以作定语。","explain":"语法填空里 a ______ boy 只能填 sick；He is ill 和 He is sick 都可以，但「住院生病」更常说 be ill in hospital。"},{"level":"次重点","text":"不可数名词的量化表达是听力价格题的关键：a piece of bread、two glasses of milk、three kilos of apples。","explain":"量词短语作主语时谓语与量词的单复数一致：Three kilos of apples are enough.。听价格时要同时记下数字与量词。"},{"level":"了解","text":"cook 是「厨师」，cooker 是「炊具」，一字之差是常见失分点。","explain":"My father is a good cook. 若写成 cooker，句意就变成了「我爸爸是个好炉子」。"}]},{"type":"table","title":"食物与饮料","head":["单词","词性/音标","释义","考点"],"rows":[["rice","n.","米饭；大米","不可数；a bowl of rice 一碗米饭"],["noodles","n.","面条","常用复数，a bowl of noodles"],["bread","n.","面包","不可数，a piece of bread 一片面包"],["meat","n.","肉","不可数"],["beef","n.","牛肉","不可数，不能说 a beef"],["chicken","n.","鸡肉；小鸡","指肉时不可数，指小鸡时可数"],["fish","n.","鱼；鱼肉","表鱼肉不可数；表条数时单复数同形"],["egg","n.","鸡蛋","可数，an egg"],["vegetable","n.","蔬菜","可数，常用复数 vegetables"],["fruit","n.","水果","通常不可数，表种类时可用 fruits"],["milk","n.","牛奶","不可数，a glass of milk"],["juice","n.","果汁","不可数，a bottle of orange juice"],["tea","n.","茶","不可数；a cup of tea"],["coffee","n.","咖啡","不可数；a coffee 表示「一杯咖啡」"],["soup","n.","汤","通常不可数，喝汤说 have soup"],["cake","n.","蛋糕","可数，a birthday cake"],["dumpling","n.","饺子","常用复数 dumplings"],["salad","n.","沙拉","可数或不可数都可"],["sugar","n.","糖","不可数；加糖说 with sugar"],["salt","n.","盐","不可数；add some salt 加点盐"]]},{"type":"table","title":"味道与烹饪","head":["单词","词性/音标","释义","考点"],"rows":[["taste","v., n.","尝起来；味道","作系动词后接形容词：It tastes good."],["delicious","adj.","美味的","本身已含「非常」义，一般不说 very delicious"],["sweet","adj.","甜的；可爱的","a sweet smile 甜甜的微笑"],["sour","adj.","酸的","元音字母组合 ou 读音易错"],["salty","adj.","咸的","由 salt 加 y 构成，注意 t 不变"],["spicy","adj.","辣的","比较级 spicier"],["fresh","adj.","新鲜的","fresh vegetables 新鲜蔬菜"],["cook","v., n.","烹饪；厨师","cook 是人，cooker 是炊具，别混"],["boil","v.","煮沸","boiled water 开水"],["fry","v.","油炸；煎","过去式 fried；fried rice 炒饭"],["mix","v.","混合","mix A with B 把 A 和 B 混合"],["dish","n.","菜肴；盘子","可数，a delicious dish 一道美味的菜"],["meal","n.","一餐","三餐的统称：three meals a day"],["snack","n.","小吃；零食","可数，eat snacks 吃零食"]]},{"type":"table","title":"身体健康与疾病","head":["单词","词性/音标","释义","考点"],"rows":[["health","n.","健康","不可数；in good health 身体健康"],["healthy","adj.","健康的","keep healthy 与 keep fit 同义"],["unhealthy","adj.","不健康的","un- 表否定"],["ill","adj.","生病的","只作表语，不能说 an ill boy"],["illness","n.","疾病","a serious illness 一种重病"],["sick","adj.","生病的；恶心的","可作定语：a sick boy"],["fever","n.","发烧","have a fever，必须加 a"],["cough","n., v.","咳嗽","读音与拼写差别大，have a cough"],["headache","n.","头痛","have a headache，必须加 a"],["stomachache","n.","胃疼；肚子疼","stomach + ache，ch 读 /k/"],["toothache","n.","牙疼","a toothache；复数 teeth 是 tooth 的复数"],["medicine","n.","药","不可数，take medicine 吃药"],["hospital","n.","医院","in hospital 住院；in the hospital 在医院里"],["hurt","v.","受伤；疼","hurt-hurt-hurt 三态同形；My leg hurts."],["rest","n., v.","休息","have a rest 休息一下"],["advice","n.","建议","不可数，give sb some advice；一条建议 a piece of advice"]]},{"type":"table","title":"运动与锻炼","head":["单词","词性/音标","释义","考点"],"rows":[["exercise","n., v.","锻炼；练习","表锻炼不可数；练习题 do exercises 可数"],["sport","n.","运动","do sports 做运动；sports meeting 运动会"],["run","v.","跑；经营","现在分词 running，双写 n"],["swim","v.","游泳","现在分词 swimming，双写 m；go swimming"],["jump","v.","跳","jump high 跳得高"],["basketball","n.","篮球","play basketball 不加 the"],["football","n.","足球","美式英语用 soccer 指足球"],["volleyball","n.","排球","拼写含 l-l-e-y"],["badminton","n.","羽毛球","拼写难度大，字母容易漏写"],["table tennis","n.","乒乓球","play table tennis 不加 the"],["skate","v.","滑冰","go skating 去滑冰"],["cycle","v.","骑自行车","cycle to school 与 ride a bike to school 同义"],["match","n.","比赛；火柴","英式常用 match，美式常用 game"],["team","n.","队；组","a member of the school team"],["train","v., n.","训练；火车","train hard 刻苦训练"],["keep fit","phr.","保持健康","同义 keep healthy"]]},{"type":"table","title":"健康习惯与饮食建议","head":["单词","词性/音标","释义","考点"],"rows":[["diet","n.","饮食","a balanced diet 均衡饮食"],["habit","n.","习惯","form a good habit 养成好习惯；eating habits 饮食习惯"],["regularly","adv.","有规律地；定期地","do exercise regularly 经常锻炼"],["enough","adj., adv.","足够的；足够地","修饰形容词时要后置：good enough"],["energy","n.","能量；精力","不可数"],["relax","v.","放松","relax yourself 放松自己"],["stress","n.","压力","不可数，under stress 在压力之下"],["weight","n.","体重；重量","lose weight 减肥；put on weight 增重"],["sleep","n., v.","睡眠；睡觉","get enough sleep 睡眠充足"],["plenty of","phr.","大量的","既可修饰可数名词复数，也可修饰不可数名词"],["junk food","phr.","垃圾食品","不可数，不能说 a junk food"],["become","v.","变得；成为","become + 形容词；过去式 became"],["give up","phr.","放弃；戒掉","后接 doing：give up eating junk food"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["keep a balanced diet","保持均衡饮食","balanced 是形容词，修饰 diet。"],["do exercise regularly","经常锻炼","exercise 表锻炼时不可数。"],["get enough sleep","保证充足睡眠","enough 修饰名词时放在名词前。"],["stay away from junk food","远离垃圾食品","同义 keep away from。"],["be good for","对……有益","反义 be bad for，主语常是食物或运动。"],["take medicine","吃药","用动词 take，不用 eat；medicine 不可数。"],["lose weight","减肥","反义 put on weight 增重。"],["have a fever","发烧","fever 前必须加 a。"]]},{"type":"list","title":"应试策略","items":["建议类作文写三条建议即可，分别落在「饮食、运动、作息」三块上，句式统一用 We should ... 或 It is important to ...。","写「看病」类补全对话，按 What’s wrong with you? → have a fever / have a headache → take medicine and have a rest 的顺序写三句就完整。","听力价格与数量题听到 a kilo of、two glasses of 时要记下量词，谓语动词的单复数往往就是考点。","系动词 taste、smell、look 后一定接形容词，这是单选与改错常设的陷阱。"]}],"questions":[{"id":"eng-vocab-topic-4-q1","type":"choice","stem":"The soup ______ delicious. Would you like some more?","answer":"A","explain":"主语 The soup 是第三人称单数，系动词用 tastes，后面接形容词 delicious 作表语。B 项与单数主语不一致；C 项是分词形式，不能单独作谓语；D 项 taste 是系动词，不用于被动语态。","options":["tastes","taste","tasting","is tasted"],"difficulty":2,"tags":["话题词汇","味道","系动词"]},{"id":"eng-vocab-topic-4-q2","type":"choice","stem":"He can’t go to school today because he has ______.","answer":"A","explain":"cold 表示「感冒」时是可数名词，have a cold 必须加不定冠词。B 项缺冠词；C 项 the 表特指，这里不需要特指；D 项复数与 have a cold 的固定说法不符。","options":["a bad cold","bad cold","the bad cold","bad colds"],"difficulty":1,"tags":["话题词汇","疾病","冠词"]},{"id":"eng-vocab-topic-4-q3","type":"choice","stem":"You had better take the ______ three times a day after meals.","answer":"A","explain":"medicine 表示「药」时是不可数名词，take medicine 是固定搭配，既不加冠词也不用复数。B、D 两项误加了复数；C 项 a medicine 表示「一种药」，与「一天三次按量服药」的语境不符。","options":["medicine","medicines","a medicine","some medicines"],"difficulty":2,"tags":["话题词汇","药品","不可数名词"]},{"id":"eng-vocab-topic-4-q4","type":"choice","stem":"Doing exercise every day ______ good for your health.","answer":"A","explain":"Doing exercise every day 是动名词短语作主语，谓语用单数 is，be good for 意为「对……有益」。B 项 are 与单数主语不一致；C 项 be 不能单独作谓语；D 项 being 是分词形式，也不能单独作谓语。","options":["is","are","be","being"],"difficulty":2,"tags":["话题词汇","运动","主谓一致"]},{"id":"eng-vocab-topic-4-q5","type":"fill","stem":"用括号内词的适当形式填空：If you want to keep ______ (health), you should eat more vegetables and do exercise every day.","answer":"healthy","explain":"keep 后接形容词作表语，keep healthy 意为「保持健康」。若填 health，则是名词，keep 后缺形容词，句子结构与意思都不成立。","difficulty":1,"tags":["话题词汇","健康","词性转换"]}]},{"id":"eng-vocab-topic-5","title":"话题词汇·购物与消费","subtitle":"话题词汇 · Shopping","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"商品价格、货币付款、店铺网购、退换投诉与购物对话五组词，用于购物类补全对话、听力信息获取与「理性消费」话题写作。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"价格有两种正确说法：The price is high/low，物品本身的贵贱才用 expensive/cheap。","explain":"不能说 The price is expensive，这是单选与改错的高频陷阱，可以改成 The price is too high 或 The bike is too expensive。"},{"level":"重点","text":"购物对话有固定应答链，补全对话与听力都按这条链命题。","explain":"Can I help you? → I’d like to buy ... / I’m just looking → How much is it? → I’ll take it. → Here you are.。记住顺序，听到问句就能预判答语。"},{"level":"重点","text":"数量与价格要顾主谓一致：How much are the shoes?；yuan、dollar 表价格时的复数形式不同。","explain":"twenty yuan 不能说 twenty yuans，而 ten dollars 要加 s。a pair of shoes 作主语时谓语与 pair 一致：This pair of shoes is nice."},{"level":"次重点","text":"try on 的宾语是代词时要放在中间：try it on。","explain":"不能说 try on it。同类结构还有 turn it off、pick it up，是单选题的固定考法。"},{"level":"次重点","text":"on sale 与 for sale 意思不同：on sale 指打折出售，for sale 指待售。","explain":"句中出现 at a low price、discount 时选 on sale；说某套房子要卖用 for sale。"},{"level":"了解","text":"「花钱」的三个动词分工：sb spends money on sth、sth costs sb money、sb pays money for sth。","explain":"做题先看主语是人还是物，再看介词是 on、for 还是没有，一步就能定答案。"}]},{"type":"table","title":"商品与价格","head":["单词","词性/音标","释义","考点"],"rows":[["shop","n., v.","商店；购物","go shopping 去购物"],["buy","v.","买","buy sb sth = buy sth for sb；过去式 bought"],["sell","v.","卖","sell-sold-sold；sell out 卖完"],["goods","n.","商品；货物","只有复数形式，作主语时谓语用复数"],["product","n.","产品","可数，a new product"],["price","n.","价格","说价格高低用 high/low，不用 expensive/cheap"],["cheap","adj.","便宜的","反义 expensive；比较级 cheaper"],["expensive","adj.","昂贵的","拼写 e-x-p-e-n-s-i-v-e，容易漏字母"],["cost","v.","花费","sth costs sb money；过去式与原形同形"],["size","n.","尺码；大小","What size do you take? 你穿多大码？"],["style","n.","款式；风格","in style 流行"],["model","n.","型号；模特","the latest model 最新款"],["sale","n.","出售；促销","on sale 打折出售；for sale 待售"],["discount","n.","折扣","at a discount 打折；10% discount 打九折"],["customer","n.","顾客","与 shop assistant 相对，注意拼写不是 costumer"]]},{"type":"table","title":"货币与付款","head":["单词","词性/音标","释义","考点"],"rows":[["money","n.","钱","不可数，a lot of money"],["yuan","n.","元（人民币）","复数不加 s：twenty yuan"],["dollar","n.","美元","复数加 s：ten dollars"],["pound","n.","英镑；磅","也可作重量单位：a pound of meat"],["coin","n.","硬币","可数，a ten-yuan coin"],["cash","n.","现金","不可数，pay in cash 用现金付款"],["card","n.","卡；卡片","pay by card 刷卡付款"],["wallet","n.","钱包","多指男士钱包，女式常用 purse"],["bank","n.","银行；河岸","in the bank 在银行"],["pay","v.","支付","pay-paid-paid；pay money for sth"],["change","n., v.","零钱；找零；改变","表零钱时不可数，keep the change 零钱不用找"],["spend","v.","花费","spend money on sth 或 (in) doing sth"]]},{"type":"table","title":"店铺与网购","head":["单词","词性/音标","释义","考点"],"rows":[["supermarket","n.","超市","go to the supermarket 去超市"],["market","n.","市场；集市","in the market 在市场上"],["shopping mall","n.","购物中心","也可简称 mall"],["bookstore","n.","书店","英式常说 bookshop"],["shop assistant","n.","售货员","也可说 sales assistant"],["basket","n.","篮子；购物篮","可数，a shopping basket"],["online","adv., adj.","在线地；在线的","shop online 网上购物"],["website","n.","网站","on the website 在网站上"],["Internet","n.","互联网","首字母大写，the Internet"],["order","v., n.","订购；订单","order sth online 网上订购"],["package","n.","包裹","英式常用 parcel"],["post","v., n.","邮寄；邮政","post sth to sb 把某物寄给某人"],["free","adj.","免费的；自由的；空闲的","for free 免费地"],["bill","n.","账单","pay the bill 付账"],["list","n.","清单；列表","make a shopping list 列购物清单"]]},{"type":"table","title":"退换与投诉","head":["单词","词性/音标","释义","考点"],"rows":[["return","v.","退还；返回","return sth to sb 把某物还给某人"],["exchange","v., n.","交换；调换","exchange A for B 用 A 换 B"],["wrong","adj.","错误的；不对的","the wrong size 尺码不对"],["broken","adj.","坏了的；破碎的","break 的过去分词；The cup is broken."],["complain","v.","投诉；抱怨","complain about sth to sb"],["manager","n.","经理","ask to see the manager 要求见经理"],["problem","n.","问题；难题","可数，solve the problem 解决问题"],["solve","v.","解决","solve a problem 与 work out a problem 都可"],["apologize","v.","道歉","apologize to sb for sth 因某事向某人道歉"],["repair","v.","修理","同义 fix；have sth repaired 请人修某物"],["check","v., n.","检查；核对","check the bill 核对账单"],["quality","n.","质量；品质","不可数，of good quality 质量好"],["agree","v.","同意","agree to do sth；agree with sb 同意某人"]]},{"type":"table","title":"购物对话常用语","head":["单词","词性/音标","释义","考点"],"rows":[["How much ...?","phr.","多少钱","主语是复数时谓语用 are：How much are the shoes?"],["What can I do for you?","phr.","需要我帮忙吗","售货员常用语，顾客答 I’d like to buy ..."],["I'd like ...","phr.","我想要……","后接名词或 to do"],["try on","phr.","试穿","宾语是代词时放中间：try it on"],["look for","phr.","寻找","强调找的过程；find 强调找到的结果"],["pay for","phr.","为……付款","pay money for sth"],["on sale","phr.","打折出售","与 for sale（待售）不同"],["a pair of","phr.","一双；一对","作主语时谓语与 pair 一致"],["some more","phr.","再要一些","Would you like some more? 还想再要点吗？"],["Anything else?","phr.","还要别的吗","答语 No, thanks. That’s all."],["Here you are.","phr.","给你","也可说 Here it is."],["I'll take it.","phr.","我买了","决定购买时的常用语"],["too expensive","phr.","太贵了","说价格高用 high，形容物品才用 expensive"],["shopping list","phr.","购物清单","make a shopping list 列购物清单"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["go shopping","去购物","同类还有 go swimming、go fishing，中间不加 to。"],["try on","试穿","宾语是代词时要放在中间：try it on。"],["pay for sth","为某物付款","主语是人；物作主语要用 cost。"],["on sale","打折出售","与 for sale（待售）不同。"],["a pair of shoes","一双鞋","作主语时谓语与 pair 一致：This pair of shoes is too small."],["How much ...?","多少钱","主语是复数时谓语用 are。"],["make a shopping list","列购物清单","写「理性消费」的作文可用。"],["in cash","用现金","与 by card（刷卡）相对。"]]},{"type":"list","title":"应试策略","items":["购物类补全对话先判断说话人是售货员还是顾客，再按「招呼—询问—报价—决定」的顺序选句。","听力价格题要同时记下数字与量词，twenty yuan for two kilos 这类信息常被拆在前后两句里。","「理性消费」话题作文可写 make a shopping list、buy what we really need、don’t waste money，三句即可成段。","价格表达是改错常考点：The price is expensive 必须改成 The price is high 或 The bike is expensive。"]}],"questions":[{"id":"eng-vocab-topic-5-q1","type":"choice","stem":"The price of the new bike is too ______ for a student like me.","answer":"A","explain":"价格的高低用 high 或 low，所以是 The price is too high。B 项 expensive 形容物品本身贵，不能形容 price；C 项 tall 形容身高；D 项 many 修饰可数名词复数，都不能与 price 搭配。","options":["high","expensive","tall","many"],"difficulty":2,"tags":["话题词汇","价格","搭配"]},{"id":"eng-vocab-topic-5-q2","type":"choice","stem":"This pair of shoes ______ too small. Could you show me a bigger one?","answer":"A","explain":"本句主语的中心词是 This pair，谓语用单数 is，shoes 只是 pair 的修饰成分。B 项 are 是误把 shoes 当主语；C 项 be 与 D 项 been 都不能单独作谓语。","options":["is","are","be","been"],"difficulty":3,"tags":["话题词汇","购物","主谓一致"]},{"id":"eng-vocab-topic-5-q3","type":"choice","stem":"— Can I help you? — ______ I’m just looking at the moment.","answer":"A","explain":"顾客暂时不需要帮助，用 No, thanks. 礼貌拒绝。B 项 Yes, please. 表示接受帮助；C 项是嫌东西贵；D 项是「给你」，都是别的情境下才说的话。","options":["No, thanks.","Yes, please.","That’s too expensive.","Here you are."],"difficulty":1,"tags":["话题词汇","购物","情景交际"]},{"id":"eng-vocab-topic-5-q4","type":"choice","stem":"The shirt looks nice on you. May I ______?","answer":"A","explain":"try on 的宾语是代词时要放在中间，shirt 是单数，所以用 try it on。B 项代词位置错误；C 项 them 与单数 shirt 不一致；D 项 try on 后缺宾语，句子不完整。","options":["try it on","try on it","try them on","try on"],"difficulty":2,"tags":["话题词汇","试穿","代词位置"]},{"id":"eng-vocab-topic-5-q5","type":"fill","stem":"用括号内词的适当形式填空：My father ______ (pay) 200 yuan for this pair of shoes last week.","answer":"paid","explain":"句中的 last week 表明动作发生在过去，谓语用过去式 paid；pay money for sth 意为「为某物付多少钱」。若填 pays，则时态与 last week 矛盾。","difficulty":1,"tags":["话题词汇","付款","一般过去时"]}]},{"id":"eng-vocab-topic-6","title":"话题词汇·旅行与交通","subtitle":"话题词汇 · Travel and transport","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"交通方式、问路指路、住宿景点、订票行程与出行安全五组词，覆盖「一次旅行」书面表达、问路补全对话与听力信息获取题。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"交通方式的两套表达不能混：by bus / by train 是「by + 单数名词，不加冠词」，on foot 用 on，take a bus / ride a bike 是动词短语。","explain":"句中已有谓语动词时用 by 短语作状语（I go to school by bus.）；没有动词时用 take a bus 作谓语。填空时先看句子结构再决定用哪一套。"},{"level":"重点","text":"arrive、reach、get to 的搭配不同：arrive in/at + 地点、reach + 地点、get to + 地点，没有 arrive to。","explain":"城市、国家等大地点用 arrive in，机场、车站等小地点用 arrive at；home、here、there 是副词，前面不加介词，所以是 get home、arrive home。"},{"level":"重点","text":"问路与指路的句型固定：Could you tell me the way to ...? / Go along this road and turn left at the second crossing.","explain":"问路用 Could/Would you ...? 更礼貌；指路先说方向再说地标，这类句子在听说「询问」部分能直接拿分。"},{"level":"次重点","text":"cross 是动词，across 是介词，through 表示从内部穿过。","explain":"cross the road 与 go across the road 意思相同，但不能说 cross across。walk through the forest 指穿过森林内部，walk across the road 指从路面横穿过去。"},{"level":"次重点","text":"in front of 指在某人或某物外部的前面，in the front of 指在某个空间内部的前部。","explain":"常见错误是把「教室前部」写成 in front of the classroom，那变成了教室外面；车头座位是 in the front of the bus。"},{"level":"了解","text":"听力信息获取题里时间与票价常换一种说法给出，需要转写而不是照抄。","explain":"a quarter past eight 就是 8:15，half an hour 是 30 分钟。题干问 How long does the trip take? 时，答案往往要用出发与到达时间相减。"}]},{"type":"table","title":"交通方式","head":["单词","词性/音标","释义","考点"],"rows":[["bus","n.","公共汽车","take a bus 或 by bus；by bus 不加冠词"],["bike","n.","自行车","ride a bike 骑车；by bike 不加冠词"],["taxi","n.","出租车","take a taxi 打车"],["train","n., v.","火车；训练","catch the train 赶上火车"],["subway","n.","地铁","英式常说 underground 或 the tube"],["plane","n.","飞机","by plane 与 by air 同义"],["ship","n.","轮船","by ship 与 by sea 同义"],["boat","n.","小船","take a boat 乘船"],["ride","v.","骑；乘","ride-rode-ridden；ride a bike to school"],["drive","v.","驾驶","drive-drove-driven；drive sb home 开车送某人回家"],["traffic","n.","交通","不可数，heavy traffic 交通拥堵"],["crowded","adj.","拥挤的","be crowded with 挤满了"],["road","n.","马路；道路","on the road 在路上"],["street","n.","街道","in the street 与 on the street 都可"],["safe","adj.","安全的","名词是 safety；keep safe 保持安全"],["on foot","phr.","步行","不能说 by foot"],["by bus","phr.","乘公交车","by + 交通工具单数，不加冠词"],["take a bus","phr.","乘公交车","take 是动词，在句中作谓语"]]},{"type":"table","title":"问路与指路","head":["单词","词性/音标","释义","考点"],"rows":[["way","n.","路；方法","Could you tell me the way to the museum?"],["turn left","phr.","向左转","反义 turn right"],["turn right","phr.","向右转",""],["go straight","phr.","直走","straight 中 tr 后没有 a，拼写易错"],["cross","v.","穿过；横过","是动词，直接接宾语：cross the road"],["crossing","n.","十字路口；人行横道","at the second crossing 在第二个路口"],["corner","n.","拐角","at the corner of the street 在街道拐角"],["opposite","prep., adj.","在……对面；对面的","opposite the bank 在银行对面"],["next to","phr.","紧靠；在……旁边","同义 beside"],["between","prep.","在……之间","between A and B；三者以上用 among"],["in front of","phr.","在……前面","指外部的前面，与 in the front of 不同"],["behind","prep.","在……后面","反义 in front of"],["along","prep.","沿着","go along the road 沿着这条路走"],["map","n.","地图","read a map 看地图"],["direction","n.","方向；指路说明","ask sb for directions 向某人问路，用复数"],["traffic lights","n.","红绿灯","常用复数，wait at the traffic lights"]]},{"type":"table","title":"住宿与景点","head":["单词","词性/音标","释义","考点"],"rows":[["hotel","n.","旅馆；酒店","stay at a hotel 住旅馆"],["room","n.","房间；空间","a single room 单人间，a double room 双人间"],["stay","v., n.","停留；住宿","stay at a hotel；stay for three days"],["guest","n.","客人；旅客","与 host（主人）相对"],["museum","n.","博物馆","拼写容易漏字母 e"],["park","n., v.","公园；停车","in the park 在公园里"],["zoo","n.","动物园","复数 zoos"],["beach","n.","海滩","复数 beaches，要加 es"],["mountain","n.","山；山脉","拼写中的 ai 读音特殊，容易拼错"],["lake","n.","湖","in the lake 在湖里"],["island","n.","岛","s 不发音，是中考高频读音题"],["temple","n.","寺庙","visit a temple 参观寺庙"],["tourist","n.","游客","重音在第一音节；tourist attraction 景点"],["place of interest","n.","名胜","复数 places of interest，s 加在 place 上"],["sightseeing","n.","观光","go sightseeing 去观光"]]},{"type":"table","title":"订票与行程","head":["单词","词性/音标","释义","考点"],"rows":[["ticket","n.","票","a ticket for the concert / to Beijing"],["book","v., n.","预订；书","book a ticket 订票，与名词「书」同形"],["flight","n.","航班；飞行","take a flight to Beijing"],["seat","n.","座位","take your seat 就座"],["trip","n.","旅行；短途出行","go on a trip 去旅行"],["journey","n.","旅程","多指长途陆路旅程"],["travel","v., n.","旅行","travel to + 地点；作名词时不可数"],["tour","n., v.","旅游；参观","a tour of the city 城市游览"],["plan","n., v.","计划","plan to do sth 计划做某事"],["arrive","v.","到达","arrive in/at，不能用 arrive to"],["leave","v.","离开；留下","leave for 动身去某地；leave sth somewhere 把东西落在某处"],["luggage","n.","行李","不可数，a piece of luggage"],["suitcase","n.","手提箱","可数，两个手提箱 two suitcases"],["guide","n., v.","导游；指南；引导","a tour guide 导游"],["return","v.","返回；归还","return to school 回学校"]]},{"type":"table","title":"出行安全与交通规则","head":["单词","词性/音标","释义","考点"],"rows":[["wait for","phr.","等待","wait for sb/sth 等某人某物"],["be late for","phr.","迟到","be late for school 上学迟到"],["miss","v.","错过；想念","miss the bus 错过公交车"],["slow down","phr.","减速","反义 speed up 加速"],["pay attention to","phr.","注意","to 是介词，后接名词或 doing"],["traffic rules","n.","交通规则","follow the traffic rules 遵守交通规则"],["safety","n.","安全","不可数，safety first 安全第一"],["cross the road","phr.","过马路","也可说 go across the road"],["get on","phr.","上车","大车用 get on，小汽车用 get in"],["get off","phr.","下车","与大车搭配，与 get on 相对"],["take off","phr.","起飞；脱下","一词两义，注意看语境判断"],["land","v., n.","降落；陆地","反义 take off 起飞"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["by bus","乘公交车","交通工具前不加冠词；步行要用 on foot。"],["on foot","步行","不能说 by foot。"],["go on a trip","去旅行","写「我的旅行」的作文常用这句开头。"],["wait for sb","等待某人","wait for 后接人或物。"],["be late for","迟到","for 后接场合或活动。"],["pay attention to","注意","to 是介词，后接名词或 doing。"],["ask sb for directions","向某人问路","directions 用复数。"],["arrive at/in","到达","大地点用 in，小地点用 at；home 前不加介词。"]]},{"type":"list","title":"应试策略","items":["「我的旅行」类书面表达按「时间—交通—住宿—活动—感受」写，用 Last summer I went to ... 起句，交通方式与景点各写一句就够充实。","问路与指路的补全对话要先看清自己是问路人还是指路人：问句用 Could you tell me ...?，指路用祈使句。","听说「角色扮演·询问」部分要主动提问，How far is it? / How long does it take? / How can I get there? 三个句型覆盖面最广，语调要上扬。","听力信息获取题里数字与时间常需要计算，听到 depart、arrive、How long 时立刻在草稿上写下两个时间再相减。"]}],"questions":[{"id":"eng-vocab-topic-6-q1","type":"choice","stem":"— ______ do you go to school? — By bike, but sometimes on foot.","answer":"A","explain":"答语 By bike 与 on foot 说的都是交通方式，问方式用 How。B 项 What 后面必须跟名词，不能单独问方式；C 项 Where 问地点；D 项 When 问时间，都与答语不符。","options":["How","What","Where","When"],"difficulty":1,"tags":["话题词汇","交通方式","疑问词"]},{"id":"eng-vocab-topic-6-q2","type":"choice","stem":"We will arrive ______ the airport at seven and then take a flight to Beijing.","answer":"A","explain":"机场是具体的小地点，用 arrive at。B 项 arrive in 用于城市、国家等大范围；C 项没有 arrive to 这个搭配，这是最常见的错误；D 项 on 不与 arrive 搭配。","options":["at","in","to","on"],"difficulty":2,"tags":["话题词汇","旅行","arrive 搭配"]},{"id":"eng-vocab-topic-6-q3","type":"choice","stem":"Look! The little boy is walking ______ the road alone. Let’s help him.","answer":"A","explain":"across 是介词，表示从表面横过，walk across the road 意为「横穿马路」。B 项 through 指从内部穿过，如 through the forest；C 项 cross 是动词，句中已有 is walking，不能再接动词；D 项 into 表示进入，与过马路不符。","options":["across","through","cross","into"],"difficulty":3,"tags":["话题词汇","指路","across/through"]},{"id":"eng-vocab-topic-6-q4","type":"choice","stem":"The library is ______ the post office and the bank, so it is easy to find.","answer":"A","explain":"between 用于两者之间，常见结构是 between A and B，本句指邮局与银行之间。B 项 among 用于三者或三者以上；C 项 in front of 表示在……前面，与「两者之间」不符；D 项 next 必须与 to 连用才能表示位置。","options":["between","among","in front of","next"],"difficulty":2,"tags":["话题词汇","指路","方位介词"]},{"id":"eng-vocab-topic-6-q5","type":"fill","stem":"用括号内词的适当形式填空：You had better ______ (book) the train tickets online, or there will be no seats left.","answer":"book","explain":"had better 后接动词原形，此处 book 是动词，意为「预订」。若填 booked，则 had better 后不能用过去式；若填 booking，也不符合 had better 的结构。","difficulty":1,"tags":["话题词汇","订票","had better"]}]},{"id":"eng-vocab-topic-7","title":"话题词汇·天气与环境","subtitle":"话题词汇 · Weather and environment","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"把天气现象、四季气候、自然景观、污染问题与环保行动五串词按「现象—原因—对策」串成一条线，听说天气问答、阅读环保短文和书面表达提建议都能直接调用。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"天气问答用形容词作答，名词不能顶替。","explain":"听说考试信息获取第一节常问 What's the weather like ...? 与 How is the weather ...?，答语必须用形容词（sunny / rainy / cloudy / foggy / windy）或 It is raining 这类句子；直接答 rain、cloud、wind 是典型错误。构词上名词加 -y 变形容词：sun → sunny、fog → foggy 要双写末尾辅音字母，wind → windy 不双写。"},{"level":"重点","text":"temperature 与 degree 的搭配及数字表达。","explain":"听力和阅读的数字题常考温度：The temperature is thirty degrees. / five degrees below zero。degree 可数，前面有具体数字时必须用复数；写作中写冬天的天气可用 The temperature often drops to five degrees below zero in the north."},{"level":"重点","text":"pollution 不可数，pollute 是及物动词。","explain":"语法选择与完形填空考词性转换：空前有 much / a lot of / serious 等修饰语时填名词 pollution，句中缺谓语时填动词 pollute（The factory pollutes the river.）。pollution 永远不加 s，也不加 a。"},{"level":"重点","text":"环保建议要成串用动词短语。","explain":"书面表达提建议时，save water and energy、recycle waste paper、reduce pollution、plant more trees、turn off the lights 每条一句排列，段落结构清楚；这些短语都跟在 We should / Let's / It is our duty to 后面，用动词原形，不要写成 -ing 形式。"},{"level":"次重点","text":"environment 前必须加 the，常与 protect、be good for 搭配。","explain":"protect the environment、care for the environment 中的 the 不能省；写作开头句 It is important for us to protect the environment. 是高频得分句，漏 the 会扣细节分。"},{"level":"了解","text":"季节词与方位词配合写气候差异。","explain":"比较类短文常用 In the south of China, it is warm in winter, while in the north it is much colder. 季节前用介词 in，方位表达是 in the south / north of ...；这类句子常作为作文的第二段开头。"}]},{"type":"table","title":"天气现象","head":["单词","词性/音标","释义","考点"],"rows":[["weather","n.","天气","不可数，问天气用 What's the weather like today?"],["sunny","adj.","晴朗的","由 sun 双写 n 加 -y 构成，注意拼写"],["cloudy","adj.","多云的","由 cloud 加 -y；听天气预报常与 sunny 一起出现"],["rainy","adj.","下雨的","答天气用形容词，不说 It is rain"],["windy","adj.","有风的","由 wind 直接加 -y，末尾辅音不双写"],["snowy","adj.","下雪的","snow 可作名词也可作动词：It snows in winter."],["foggy","adj.","有雾的","双写 g 再加 -y，是拼写易错点"],["storm","n.","暴风雨","a heavy storm 一场大暴风雨"],["shower","n.","阵雨；淋浴","a light shower 一场小雨；take a shower 洗澡"],["thunder","n.","雷；雷声","与 lightning 配对记忆：先闪电后打雷"],["lightning","n.","闪电","不可数，不加 s；不要与 lighting（照明）混淆"],["rainbow","n.","彩虹","a rainbow appears after the rain"],["cloud","n.","云","名词，作表语要改成 cloudy"],["rain","n./v.","雨；下雨","名词不可数；动词常用 It is raining."],["snow","n./v.","雪；下雪","名词不可数：heavy snow 大雪"],["wind","n.","风","the wind is blowing hard 风刮得很大"],["sunshine","n.","阳光","不可数，in the sunshine 在阳光下"],["temperature","n.","温度","常用 the temperature is / drops to ...；拼写注意 era"]]},{"type":"table","title":"四季与气候","head":["单词","词性/音标","释义","考点"],"rows":[["season","n.","季节","four seasons 四季，常说 in all seasons"],["spring","n.","春季","in spring 前不加 the；Spring Festival 指春节"],["summer","n.","夏季","summer holiday 暑假，是常考搭配"],["autumn","n.","秋季","英式 autumn，美式 fall；末尾 n 不发音"],["winter","n.","冬季","in winter 在冬天；winter vacation 寒假"],["climate","n.","气候","a warm climate 温暖的气候，谈一个地方长期天气用 climate"],["warm","adj.","温暖的","get warmer 变暖；warm up 是「热身」"],["hot","adj.","炎热的；辣的","比较级 hotter 双写 t"],["cool","adj.","凉爽的；酷的","与 cold 分工：cool 是舒服的凉，cold 是冷"],["cold","adj.","寒冷的","catch a cold 感冒，此处 cold 是名词"],["dry","adj.","干燥的","比较级 drier，改 y 为 i；反义词 wet"],["wet","adj.","潮湿的","比较级 wetter 双写 t"],["degree","n.","度；程度","有具体数字时用复数：thirty degrees"],["north","n./adj.","北方（的）","in the north of China 在中国北方"],["south","n./adj.","南方（的）","southern 是形容词「南方的」"],["forecast","n./v.","预报","the weather forecast 天气预报，听力开头常出现"]]},{"type":"table","title":"自然景观","head":["单词","词性/音标","释义","考点"],"rows":[["nature","n.","大自然","in nature 在自然界；natural 是形容词"],["environment","n.","环境","前面必须加 the，拼写注意 iron 在中间"],["mountain","n.","山；山脉","climb the mountain 爬山"],["hill","n.","小山；山丘","比 mountain 小，常指村庄附近的小山"],["river","n.","河流","the river is polluted 河被污染了"],["lake","n.","湖","by the lake 在湖边"],["sea","n.","海","go to the sea 去海边；by the sea 在海边"],["ocean","n.","海洋","the Pacific Ocean 太平洋，专有名称首字母大写"],["forest","n.","森林","cut down the forests 砍伐森林，环保话题高频"],["field","n.","田野；场地","on the sports field 在操场上"],["island","n.","岛屿","s 不发音，是朗读易错词"],["beach","n.","海滩","复数 beaches，加 -es"],["desert","n.","沙漠","重音在前；dessert 是「甜点」，一词之差"],["grass","n.","草；草地","不可数，不说 a grass；keep off the grass 勿踏草坪"],["tree","n.","树","plant trees 植树，环保作文必写"],["flower","n.","花","可数：pick flowers 摘花"],["sky","n.","天空","the sky is blue，通常用单数加 the"],["moon","n.","月亮","the moon 前加 the；the Mid-Autumn Festival 赏月"]]},{"type":"table","title":"污染与问题","head":["单词","词性/音标","释义","考点"],"rows":[["pollution","n.","污染","不可数，air / water / noise pollution 都用它"],["pollute","v.","污染","及物动词，后直接接宾语：pollute the river"],["rubbish","n.","垃圾","英式不可数，pick up rubbish 捡垃圾"],["waste","n./v.","废物；浪费","作名词不可数；waste water 废水"],["smoke","n./v.","烟；吸烟","不可数；No smoking 禁止吸烟"],["noise","n.","噪音","可数名词，make a noise 发出噪音"],["noisy","adj.","吵闹的","形容词，反义词 quiet；勿与 noise 混用词性"],["plastic","n./adj.","塑料；塑料的","plastic bags 塑料袋，环保话题必用"],["harmful","adj.","有害的","be harmful to 对……有害，介词只能用 to"],["serious","adj.","严重的；严肃的","a serious problem 严重的问题"],["problem","n.","问题；难题","solve the problem 解决问题，动词用 solve"],["cause","v./n.","引起；原因","cause sth 直接接结果：cause air pollution"],["energy","n.","能源；精力","不可数，save energy 节约能源"],["gas","n.","气体；燃气","不可数；greenhouse gas 温室气体"],["oil","n.","石油；油","不可数，oil is running out 石油快用完了"],["cut down","phr.","砍倒；削减","cut down trees 砍树，宾语是代词时要放中间"]]},{"type":"table","title":"环保行动","head":["单词","词性/音标","释义","考点"],"rows":[["protect","v.","保护","protect ... from ... 保护……免受……"],["save","v.","节约；拯救","save water / energy / time 都可用"],["recycle","v.","回收利用","recycle waste paper 回收废纸，宾语是具体物品"],["reuse","v.","再利用","与 recycle 区别：reuse 是重复使用，recycle 是加工再用"],["reduce","v.","减少","reduce pollution 减少污染，后接不可数名词"],["plant","v./n.","种植；植物","plant more trees 多种树"],["clean","v./adj.","打扫；干净的","clean up 打扫干净，up 不能省"],["turn off","phr.","关掉（电器、水龙头）","宾语是代词时写成 turn it off"],["pick up","phr.","捡起；接人","pick up rubbish 捡垃圾，写作常用"],["throw away","phr.","扔掉","扔进垃圾桶常说 throw ... into the bin"],["instead of","phr.","代替；而不是","后接名词或动名词：instead of using plastic bags"],["green","adj./n.","绿色的；环保的","green life 绿色生活，作文可作标题词"],["action","n.","行动","take action 采取行动，action 用单数"],["take action","phr.","采取行动","take action to do sth 采取行动做某事"],["care for","phr.","关心；照顾","care for the environment 爱护环境"],["tap","n.","水龙头","turn off the tap 关水龙头"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["protect the environment","保护环境","environment 前必须加 the，写作开头句高频。"],["save water and energy","节约水和能源","两者都不可数，不用复数。"],["reduce pollution","减少污染","reduce 后接不可数名词，pollution 不加 s。"],["recycle waste paper","回收废纸","recycle 后接具体物品，比笼统说 recycle rubbish 更得分。"],["plant more trees","多植树","比较级 more 位置在名词前；也可说 plant trees every year。"],["turn off the lights","关灯","宾语用代词时写成 turn them off。"],["the weather report","天气预报","听力材料常用 It says in the weather report that ... 开头。"],["What's the weather like today?","今天天气怎么样？","与 How is the weather today? 同义，答语用形容词。"]]},{"type":"list","title":"应试策略","items":["天气类听说题先抓形容词与温度数字：题干问天气时，答语必须由形容词（sunny / rainy / foggy）或 It is raining / snowing 构成，用名词 rain、cloud 作答是典型错误。","环保类作文按「现象（pollution、rubbish）—原因（cut down trees、waste water）—建议（save、recycle、reduce）」三段展开，每段两到三句，结构分稳拿。","阅读环保短文时先判断词性再看搭配：pollution 不可数、environment 前加 the、recycle 后接具体物品，这三条能解决大部分细节题与词义猜测题。","拼写细节：sunny、foggy 要双写末尾辅音字母再加 -y，windy 不双写；temperature 共 11 个字母，中间是 era，别写成 temperture。"]}],"questions":[{"id":"eng-vocab-topic-7-q1","type":"choice","stem":"— What's the weather like today?\n— It's ______, so remember to take an umbrella with you.","answer":"A","explain":"is 后面作表语要用形容词，且「要带伞」提示是雨天，故选 rainy。B 项 rain 是名词或动词，不能直接作 is 的表语（说下雨要用 It is raining）；C 项 cloud 是名词「云」；D 项 sun 是名词「太阳」，与带伞的语境也不相符。","options":["rainy","rain","cloud","sun"],"difficulty":1,"tags":["话题词汇","天气与环境","形容词作表语"]},{"id":"eng-vocab-topic-7-q2","type":"choice","stem":"The weather report says the temperature will drop to five ______ below zero tonight.","answer":"A","explain":"degree 是可数名词，前面有具体数字 five 时要用复数 degrees，below zero 表示「零下」。B 项 degree 是单数，与 five 不一致；C 项 times 表示倍数或次数；D 项 metres 是长度单位，不能用来描述温度。","options":["degrees","degree","times","metres"],"difficulty":2,"tags":["话题词汇","天气与环境","名词单复数"]},{"id":"eng-vocab-topic-7-q3","type":"choice","stem":"Too much ______ has made the river dirty and the fish have died.","answer":"A","explain":"空前有 Too much 修饰，句子主语位置需要不可数名词 pollution。B 项 pollute 是动词，不能作主语；C 项 polluted 与 D 项 polluting 都是分词形式，也不能单独承担主语。注意 pollution 永远不加 s，也不加 a。","options":["pollution","pollute","polluted","polluting"],"difficulty":2,"tags":["话题词汇","天气与环境","词性判断"]},{"id":"eng-vocab-topic-7-q4","type":"choice","stem":"We can ______ water by turning off the tap while brushing our teeth.","answer":"A","explain":"by turning off the tap（靠关掉水龙头）说明是节约用水的做法，故选 save。B 项 waste 是「浪费」，与关水龙头的行为相反；C 项 drink 是「喝」；D 项 pollute 是「污染」，都不能与 by turning off the tap 构成合理的因果关系。","options":["save","waste","drink","pollute"],"difficulty":1,"tags":["话题词汇","天气与环境","语境选词"]},{"id":"eng-vocab-topic-7-q5","type":"choice","stem":"Our city is getting ______ because people have planted thousands of trees.","answer":"A","explain":"get 后接形容词表示「变得……」，句中有 have planted thousands of trees 说明正在发生变化，所以用比较级 greener 表示「越来越绿」。B 项 green 是原级，不能表示变化趋势；C 项 greenest 是最高级，需要 in / of 给出比较范围；D 项 more green 是错误形式，单音节形容词 green 的比较级是 greener。","options":["greener","green","greenest","more green"],"difficulty":2,"tags":["话题词汇","天气与环境","形容词比较级"]},{"id":"eng-vocab-topic-7-q6","type":"fill","stem":"The weather report says it will be ______ tomorrow, so we can go hiking.（晴朗的）","answer":"sunny|Sunny","explain":"「晴朗的」是 sunny，由名词 sun 双写 n 再加 -y 构成，在 be 动词后作表语。答题时注意双写 n，写成 suny 或 sunney 都算错。","difficulty":1,"tags":["话题词汇","天气与环境","拼写"]}]},{"id":"eng-vocab-topic-8","title":"话题词汇·科技与网络","subtitle":"话题词汇 · Technology and the Internet","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"按「设备—网络—操作—利弊」四层整理科技类词汇，让手机电脑类听说题不丢词、科技利弊类作文既有话说又有固定句型。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"情态动词后只能接动词原形。","explain":"语法选择常这样出题：We can ______ information online. 四个选项分别给 search（动词原形）、searching（分词）、search 的名词形式、searched（过去式）。判断办法：空前是 can / should / must / may 时直接选动词原形，其余三项一律排除。"},{"level":"重点","text":"形容词加固定介词的搭配要成对记。","explain":"be harmful to（对……有害）、be popular with（受……欢迎）、be useful to / for、be convenient for 是阅读和完形的高频搭配。题干给出介词时优先想形容词，如 ... is harmful to our eyes 只能填 harmful，填 harm 或 harmless 都不成立。"},{"level":"重点","text":"科技话题作文必须写「利与弊」两面。","explain":"书面表达常考「手机 / 网络的利与弊」：好处用 make our life easier、help us learn more、save time；坏处用 spend too much time on screens、be bad for our eyes、lose interest in study。先两面再给建议，段落完整、不跑题，只写一面会被扣内容分。"},{"level":"重点","text":"spend 句型的同义替换。","explain":"spend time (in) doing sth 与 spend money on sth 的主语是人；听力信息获取题常用 It takes sb some time to do sth 来替换 spend。听到 It takes me two hours to finish 时，选项里往往写成 spend two hours finishing，能对上就是答案。"},{"level":"次重点","text":"the Internet 首字母大写，online 是副词或形容词。","explain":"特指互联网时写 the Internet，首字母必须大写；泛指「在网上」用 online，如 go online、shop online、take online lessons，不能说 on online。写作里大小写错误属于细节扣分。"},{"level":"了解","text":"turn on / off 管开关，turn up / down 管大小。","explain":"听力指令题常考「打开、关掉、调高、调低」四组动作：on 与 off 控制电源，up 与 down 控制音量或温度。听到 turn it down 要能对应「把声音调小」。"}]},{"type":"table","title":"电脑与手机","head":["单词","词性/音标","释义","考点"],"rows":[["computer","n.","电脑","on the computer 在电脑上；play computer games 玩电脑游戏"],["screen","n.","屏幕","screen time 屏幕使用时间，利弊类作文常用"],["keyboard","n.","键盘","重音在前；按键盘用 type on the keyboard"],["mouse","n.","鼠标；老鼠","复数 mice，指鼠标时也可用 mouses，考试按语境理解"],["printer","n.","打印机","由 print 直接加 -er 构成，print 末尾不双写"],["laptop","n.","笔记本电脑","lap + top 合成词，与 desktop 相对"],["smartphone","n.","智能手机","也可写成 smart phone，作文中写手机常用 mobile phone"],["mobile phone","n.","手机","英式说法，美式是 cell phone；不能写成 mobile telephone"],["camera","n.","照相机","take photos with a camera 用相机拍照"],["program","n.","程序；节目","英式拼写 programme 指电视节目，美式 program 通用"],["message","n.","信息；短信","可数名词：send a message to sb"],["file","n.","文件","copy the file 复制文件"],["password","n.","密码","forget the password 忘记密码，注意 pass + word"],["machine","n.","机器","a washing machine 洗衣机"],["robot","n.","机器人","科技类阅读中常作主语：Robots can help us do housework."],["app","n.","应用程序","application 的缩写，阅读中常见，注意首字母不大写"]]},{"type":"table","title":"互联网与社交","head":["单词","词性/音标","释义","考点"],"rows":[["Internet","n.","互联网","特指互联网时首字母大写并加 the：surf the Internet"],["website","n.","网站","visit a website 访问网站"],["network","n.","网络","social network 社交网络"],["email","n./v.","电子邮件","send an email to sb 给某人发邮件"],["blog","n.","博客","write a blog 写博客，中考常见拓展词"],["chat","v./n.","聊天","chat with sb 与某人聊天，过去式 chatted 双写 t"],["communicate","v.","交流","communicate with sb 与某人交流，介词必须是 with"],["share","v.","分享；共用","share sth with sb；share a room 合住"],["connect","v.","连接","connect A with / to B 把 A 与 B 连接起来"],["download","v.","下载","download music from the Internet"],["upload","v.","上传","与 download 方向相反，注意 up / down 的分工"],["search","v.","搜索","search the Internet for information 在网上搜索信息"],["information","n.","信息；资料","不可数，不说 an information 或 informations"],["video","n.","视频","watch a video 看视频；video call 视频通话"],["online","adv./adj.","在线地（的）","go online 上网，前面不加介词 on"],["WeChat","n.","微信","专有名词首字母大写，借词不加引号"]]},{"type":"table","title":"常用操作动词","head":["单词","词性/音标","释义","考点"],"rows":[["click","v.","点击","click on the icon 点击图标"],["type","v.","打字；输入","type on the keyboard；type 也可作名词「类型」"],["print","v.","打印","print out the paper 把文件打印出来"],["save","v.","保存；节约","save the file 保存文件；save energy 节约能源"],["delete","v.","删除","delete the file 删除文件，重音在后"],["copy","v./n.","复制；副本","copy the file 复制文件；copy sth to a USB stick 把某物复制到 U 盘"],["turn on","phr.","打开（电器）","宾语是代词时写成 turn it on"],["turn off","phr.","关掉（电器）","与 turn on 相反；不要与 close 混用（close 用于门窗书）"],["open","v./adj.","打开；开着的","open the app 打开应用；开电脑多用 turn on"],["close","v.","关闭","close the window 关窗；关电器不用 close"],["start","v.","开始；启动","start the computer 启动电脑；start to do / doing 都可"],["log in","phr.","登录","log in with a password 用密码登录，过去式 logged in"],["send","v.","发送","过去式 sent；send sb sth = send sth to sb"],["receive","v.","收到","receive an email 收到邮件，强调客观收到，不强调主动"],["pay","v.","支付","pay for sth 为某物付钱；pay by phone 用手机支付"],["repair","v.","修理","repair the computer 修电脑；have sth repaired 请人修"]]},{"type":"table","title":"科技利弊表达","head":["单词","词性/音标","释义","考点"],"rows":[["technology","n.","技术；科技","不可数；science and technology 科技"],["convenient","adj.","方便的","主语不能是人：不说 I am convenient；常用 It is convenient for sb to do"],["modern","adj.","现代的","modern life 现代生活，利弊类作文常用"],["useful","adj.","有用的","be useful to / for sb"],["helpful","adj.","有帮助的","be helpful to sb，听力中常同义替换为 of great help"],["popular","adj.","受欢迎的","be popular with / among sb，介词不用 by"],["invent","v.","发明","invent the telephone 发明电话"],["invention","n.","发明（物）","可数：one of the greatest inventions"],["develop","v.","发展；开发","develop a habit 养成习惯；科技发展用 develop technology"],["development","n.","发展","不可数；with the development of technology 作文万能开头"],["change","v./n.","改变","change our lives 改变我们的生活，利弊类作文必用"],["improve","v.","改善；提高","improve our English 提高英语水平"],["safe","adj.","安全的","keep safe 保持安全，反义词 dangerous"],["dangerous","adj.","危险的","It is dangerous to do sth 做某事很危险"],["depend on","phr.","依靠；取决于","Don't depend on your phone too much. 别太依赖手机"],["spend","v.","花费（时间、金钱）","主语是人：spend time on sth / (in) doing sth"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["search for information online","在网上搜索信息","也可说 search the Internet for information，search 后接地点或范围。"],["take online lessons","上网课","lesson 用复数表示课程，online 作定语。"],["protect personal information","保护个人信息","information 不可数，不加 s。"],["spend too much time on screens","在屏幕前花太多时间","on 后接名词；说打游戏可用 on computer games。"],["log in with a password","用密码登录","介词是 with，表示工具。"],["turn off the computer","关掉电脑","关电器用 turn off，不用 close。"],["send an email to sb","给某人发电子邮件","也可说 send sb an email。"],["be harmful to our eyes","对我们的眼睛有害","介词是 to；划线部分常被换成 do harm to our eyes。"]]},{"type":"list","title":"应试策略","items":["科技类阅读的细节题常靠同义替换设置：原文 use the Internet 对应选项 go online，原文 helpful 对应 of great help，做题先定位原句再比对选项用词。","写「科技利弊」作文时两面都要写：先两到三句好处，再两到三句坏处，最后用一两条建议收尾，只写一面会被扣内容分。","语法选择里 can / should / must / may 后面的空只填动词原形，选项中出现名词或 -ing 形式可先排除。","注意区分 online（副词 / 形容词，不能说 on online）与 the Internet（名词，必须加 the）；写作中大小写与冠词错误是最常见的细节扣分点。"]}],"questions":[{"id":"eng-vocab-topic-8-q1","type":"choice","stem":"Nowadays we can ______ with friends far away by video call.","answer":"A","explain":"can 是情态动词，后面必须接动词原形，故选 communicate。B 项 communication 是名词「交流」；C 项 communicative 是形容词；D 项 communicating 是动名词或现在分词形式，都不能直接跟在情态动词后面。","options":["communicate","communication","communicative","communicating"],"difficulty":1,"tags":["话题词汇","科技与网络","情态动词"]},{"id":"eng-vocab-topic-8-q2","type":"choice","stem":"Online shopping is very ______ because we don't need to go to the shops.","answer":"A","explain":"is 后面作表语要用形容词 convenient。B 项 convenience 是名词「方便」；C 项 conveniently 是副词，不能作表语；D 项 conveniences 是名词复数，同样不能作表语。还要注意 convenient 不能以人作主语，不说 I am convenient。","options":["convenient","convenience","conveniently","conveniences"],"difficulty":2,"tags":["话题词汇","科技与网络","形容词作表语"]},{"id":"eng-vocab-topic-8-q3","type":"choice","stem":"Playing computer games for hours is ______ to our eyes.","answer":"A","explain":"be harmful to 是「对……有害」的固定搭配，空格在 is 后面作表语，要用形容词 harmful。B 项 harm 是名词或动词；C 项 harmless 意为「无害的」，与长时间玩游戏的事实相反；D 项 harmed 是过去分词，无法构成这一搭配。","options":["harmful","harm","harmless","harmed"],"difficulty":2,"tags":["话题词汇","科技与网络","固定搭配"]},{"id":"eng-vocab-topic-8-q4","type":"choice","stem":"Don't ______ your personal information with strangers online.","answer":"A","explain":"share sth with sb 是「与某人分享某物」，句中已有 with strangers，选 share 最贴切。B 项 say 常用 say sth to sb；C 项 speak 是不及物动词或接语言作宾语；D 项 tell 的结构是 tell sb sth，都不与 with 搭配。","options":["share","say","speak","tell"],"difficulty":2,"tags":["话题词汇","科技与网络","动词搭配"]},{"id":"eng-vocab-topic-8-q5","type":"choice","stem":"The Internet has ______ our lives a lot in the past twenty years.","answer":"A","explain":"in the past twenty years 是现在完成时的标志，has 后面要接过去分词 changed。B 项 change 是动词原形；C 项 changing 用于进行时；D 项 changes 是第三人称单数形式，都不能跟在 has 后面。","options":["changed","change","changing","changes"],"difficulty":2,"tags":["话题词汇","科技与网络","现在完成时"]},{"id":"eng-vocab-topic-8-q6","type":"choice","stem":"Please ______ the computer when you leave the room. It wastes electricity.","answer":"A","explain":"离开房间、还提到浪费电，说明应当「关掉」电脑，turn off 表示关闭电源。B 项 turn on 是打开；C 项 turn up 与 D 项 turn down 用于调高、调低音量或温度，与「省电」的语境不符。","options":["turn off","turn on","turn up","turn down"],"difficulty":1,"tags":["话题词汇","科技与网络","动词短语"]}]},{"id":"eng-vocab-topic-9","title":"话题词汇·文化与节日","subtitle":"话题词汇 · Culture and festivals","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"中外节日名称、习俗活动、礼仪动作与跨文化交流四组词一起记，既能答听说礼仪题，也能撑起「介绍中国传统节日」这篇高频作文。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"节日名称前加 the，实词首字母大写。","explain":"the Spring Festival、the Mid-Autumn Festival、the Dragon Boat Festival 中的 the 不能漏，festival、dragon、boat 等实词首字母都要大写。写作与语法填空题里漏 the 或小写是常见细节错；表示「在春节」用 at / during the Spring Festival，不用 in the Spring Festival。"},{"level":"重点","text":"celebrate 后直接接节日，hold 后接活动。","explain":"写作可轮换三种表达：celebrate the Spring Festival（庆祝节日）、hold a party（举办聚会）、have a big dinner（吃团圆饭）。注意 celebrate 是及物动词，后面不加 with 或 for：不说 celebrate with the Spring Festival。"},{"level":"重点","text":"礼仪话题用一般现在时 + 动词短语。","explain":"听说「角色扮演·回答」常问初次见面该怎么做，答语用 We usually shake hands and say hello. 一般现在时表示习惯做法。shake hands 中 hands 必须用复数，hug、bow、kiss 都只作参考。"},{"level":"次重点","text":"culture / cultural 的词性转换。","explain":"语法选择题里，修饰名词用形容词 cultural（cultural exchange、cultural differences），作主语或宾语用名词 culture（Chinese culture is ...）。判断办法：空格后紧跟名词就选形容词。"},{"level":"次重点","text":"介绍节日用一般现在时，讲经历用一般过去时。","explain":"说明节日习俗用一般现在时：People eat mooncakes and watch the moon.；写自己去年过节用一般过去时：Last year we visited my grandparents.。同一篇作文里两种时态混用是最常见的失分点。"},{"level":"了解","text":"传统节日与食物的对应关系是文化常识题常考点。","explain":"春节—dumplings、元宵节—tangyuan（the Lantern Festival）、端午节—zongzi、中秋节—mooncakes、感恩节—turkey、万圣节—pumpkin。中考阅读与听力的文化常识题常以此设置搭配题。"}]},{"type":"table","title":"中国传统节日","head":["单词","词性/音标","释义","考点"],"rows":[["the Spring Festival","n.","春节","必须加 the，实词首字母大写；也可说 Chinese New Year"],["the Lantern Festival","n.","元宵节","lantern 是灯笼；这天吃 tangyuan 汤圆"],["the Dragon Boat Festival","n.","端午节","dragon boat 是龙舟，这天吃 zongzi"],["the Mid-Autumn Festival","n.","中秋节","Mid-Autumn 中间有连字符且都大写"],["the Double Ninth Festival","n.","重阳节","农历九月初九，常与爬山搭配"],["celebrate","v.","庆祝","及物动词，后直接接节日：celebrate the festival"],["celebration","n.","庆祝活动","可数：hold a celebration 举办庆祝活动"],["dumpling","n.","饺子","常用复数 dumplings，春节食物"],["mooncake","n.","月饼","中秋节食物，一个词不加空格"],["zongzi","n.","粽子","借词，单复数同形，端午节食物"],["lantern","n.","灯笼","hang lanterns 挂灯笼，元宵节常用"],["dragon boat","n.","龙舟","dragon boat races 龙舟赛"],["race","n.","比赛；赛跑","可数；龙舟赛、赛跑都用它，与 match 分工见运动话题"],["tradition","n.","传统","可数，an old Chinese tradition"],["traditional","adj.","传统的","比 tradition 多 al，修饰 food / festival / culture"],["red packet","n.","红包","英式说法，美式常用 red envelope；give sb a red packet"],["relative","n.","亲戚","常用复数 relatives；visit relatives 走亲戚"],["lucky","adj.","幸运的","lucky money 压岁钱，可与 red packet 同义替换"]]},{"type":"table","title":"西方节日","head":["单词","词性/音标","释义","考点"],"rows":[["Christmas","n.","圣诞节","at Christmas 在圣诞节期间；Merry Christmas!"],["Christmas tree","n.","圣诞树","put up a Christmas tree 装圣诞树"],["Santa Claus","n.","圣诞老人","专有名词，两个词都大写"],["Halloween","n.","万圣节前夕","10 月 31 日，孩子会 go trick-or-treating"],["pumpkin","n.","南瓜","make a pumpkin lantern 做南瓜灯"],["Easter","n.","复活节","前面不加 the；Easter eggs 复活节彩蛋"],["Thanksgiving","n.","感恩节","Thanksgiving Day 感恩节，美国家庭吃 turkey"],["New Year's Day","n.","元旦","有撇号，注意别漏 -'s"],["gift","n.","礼物","与 present 同义；send gifts to sb"],["card","n.","卡片","send a Christmas card 寄圣诞卡"],["candle","n.","蜡烛","light a candle 点蜡烛；生日蛋糕上也用"],["decorate","v.","装饰","decorate the room with flowers 用花装饰房间"],["party","n.","聚会","hold / have a party 举办聚会"],["wish","v./n.","祝愿；希望","wish sb a happy festival 祝某人节日快乐"],["greeting","n.","问候；贺词","常用复数 greetings；send greetings to sb"],["turkey","n.","火鸡","Thanksgiving 的传统食物，也是国家名 Turkey 的另一种含义"]]},{"type":"table","title":"文化习俗与礼仪","head":["单词","词性/音标","释义","考点"],"rows":[["custom","n.","风俗；习俗","社会性的风俗，与个人的 habit 分工不同"],["culture","n.","文化","可数或不可数：Chinese culture、different cultures"],["cultural","adj.","文化的","修饰名词：cultural exchange、cultural differences"],["manners","n.","礼貌；礼仪","表示「礼貌」时用复数：have good manners"],["polite","adj.","有礼貌的","be polite to sb 对某人有礼貌"],["impolite","adj.","不礼貌的","It is impolite to do sth 做某事不礼貌"],["shake hands","phr.","握手","hands 必须用复数；shake hands with sb"],["hug","v./n.","拥抱","过去式 hugged 双写 g"],["bow","v.","鞠躬","bow to sb 向某人鞠躬；发音 /baʊ/，与 ball 不同音"],["guest","n.","客人","receive a guest 接待客人"],["host","n./v.","主人；主持","与 guest 相对；host a party 举办聚会"],["chopsticks","n.","筷子","永远用复数，a pair of chopsticks 一双筷子"],["respect","v./n.","尊重","respect sb = show respect for sb"],["behaviour","n.","行为；举止","英式拼写 behaviour，美式 behavior；不可数"],["greet","v.","问候；迎接","greet sb with a smile 微笑着迎接某人"],["accept","v.","接受","accept a gift 接受礼物，与 receive（收到）区别在主观意愿"]]},{"type":"table","title":"中外交流","head":["单词","词性/音标","释义","考点"],"rows":[["exchange","n./v.","交流；交换","cultural exchange 文化交流；exchange students 交换生"],["foreign","adj.","外国的","g 不发音；foreign language 外语"],["foreigner","n.","外国人","由 foreign 加 -er 构成，注意别漏 e"],["abroad","adv.","在国外","副词，go abroad 前不加 to"],["international","adj.","国际的","inter- 表「在……之间」，首字母小写即可"],["language","n.","语言","可数：learn a foreign language"],["introduce","v.","介绍","introduce A to B 把 A 介绍给 B，介词是 to"],["understand","v.","理解；明白","过去式 understood；understand each other 互相理解"],["difference","n.","差别；不同","可数：the differences between A and B"],["different","adj.","不同的","be different from 与……不同，介词是 from"],["similar","adj.","相似的","be similar to 与……相似，注意与 different from 的介词差别"],["experience","n.","经历；经验","作「经历」可数，作「经验」不可数"],["visit","v./n.","参观；拜访","及物动词，visit a museum 后不加 to"],["welcome","v./adj.","欢迎","welcome sb to China 欢迎某人来中国"],["bridge","n.","桥梁","a bridge between cultures 文化之间的桥梁，作文可用"],["learn from","phr.","向……学习","learn from each other 互相学习，介词是 from"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["the Spring Festival","春节","节日前必须加 the，实词首字母大写。"],["the Lantern Festival","元宵节","常与 eat tangyuan、hang lanterns 连用。"],["the Dragon Boat Festival","端午节","常与 dragon boat races、eat zongzi 连用。"],["the Mid-Autumn Festival","中秋节","常与 eat mooncakes、watch the moon 连用。"],["celebrate a festival","庆祝节日","celebrate 后直接接节日，不加 with。"],["follow traditional customs","遵循传统习俗","custom 指社会风俗；个人的习惯用 habit。"],["cultural exchange","文化交流","写作中常作主语，后接 helps us understand ...。"],["shake hands with sb","与某人握手","hands 用复数，介词是 with。"],["table manners","餐桌礼仪","manners 用复数，前面可加 good。"]]},{"type":"list","title":"应试策略","items":["节日名称是专有名词，写作中每个实词首字母都要大写；四大传统节日前必须加 the，这是最容易忽略的细节分。","介绍中国节日统一用一般现在时；写自己去年过节则整段用一般过去时，不要在同一段里混用两种时态。","听说「角色扮演」问礼仪时，答语先给做法再给原因，如 We usually shake hands because it shows respect. 这样答够两点，得分更稳。","中外交流类作文可用 Cultural exchange helps us understand ... 或 Learning about other cultures is ... 开头，把 traditional、custom、respect 用进去，词汇分与内容分都有保障。"]}],"questions":[{"id":"eng-vocab-topic-9-q1","type":"choice","stem":"Chinese families eat ______ at the Mid-Autumn Festival.","answer":"A","explain":"中秋节的传统食物是月饼 mooncakes。B 项 dumplings 是饺子，多在春节吃；C 项 turkeys 是感恩节的食物；D 项 zongzi 是端午节的粽子，三项与 Mid-Autumn Festival 都不对应。","options":["mooncakes","dumplings","turkeys","zongzi"],"difficulty":1,"tags":["话题词汇","文化与节日","文化常识"]},{"id":"eng-vocab-topic-9-q2","type":"choice","stem":"Dragon boat ______ are held on the Dragon Boat Festival every year.","answer":"A","explain":"主语表示的是「龙舟赛」这一复数概念，谓语 are held 也是复数形式，所以用复数名词 races。B 项 race 是单数，与 are 不一致；C 项 racing 是动名词；D 项 raced 是动词过去式，都不能作主语。","options":["races","race","racing","raced"],"difficulty":2,"tags":["话题词汇","文化与节日","名词单复数"]},{"id":"eng-vocab-topic-9-q3","type":"choice","stem":"It is ______ for Chinese people to have a big dinner with their family on New Year's Eve.","answer":"A","explain":"It is + 形容词 + for sb to do sth 是固定句型，空格处要用形容词 traditional。B 项 tradition 是名词；C 项 traditionally 是副词，不能作表语；D 项 traditions 是名词复数，同样不能填入该句型。","options":["traditional","tradition","traditionally","traditions"],"difficulty":2,"tags":["话题词汇","文化与节日","词性转换"]},{"id":"eng-vocab-topic-9-q4","type":"choice","stem":"When Chinese people meet someone for the first time, they usually ______ hands.","answer":"A","explain":"shake hands 是「握手」的固定搭配，也是中国人初次见面最常见的做法。B 项 hug 是「拥抱」，C 项 kiss 是「亲吻」，都不符合一般社交场合；D 项 bow 是「鞠躬」，多见于日本、韩国等国家。","options":["shake","hug","kiss","bow"],"difficulty":1,"tags":["话题词汇","文化与节日","固定搭配"]},{"id":"eng-vocab-topic-9-q5","type":"choice","stem":"Cultural ______ helps us understand people from other countries better.","answer":"A","explain":"cultural exchange 意为「文化交流」，是本话题的固定表达，与后面的 understand people from other countries 呼应。B 项 change 是「改变」；C 项 excuse 是「借口」；D 项 example 是「例子」，都不能与 cultural 构成「交流」的意思。","options":["exchange","change","excuse","example"],"difficulty":2,"tags":["话题词汇","文化与节日","固定搭配"]},{"id":"eng-vocab-topic-9-q6","type":"choice","stem":"We should ______ the customs of the country we visit.","answer":"A","explain":"尊重所访问国家的习俗，用 respect，与 customs 搭配最恰当。B 项 refuse 是「拒绝」；C 项 repeat 是「重复」；D 项 report 是「报告」，三者与 customs 搭配都不表示「尊重」。","options":["respect","refuse","repeat","report"],"difficulty":1,"tags":["话题词汇","文化与节日","语境选词"]}]},{"id":"eng-vocab-topic-10","title":"话题词汇·体育运动","subtitle":"话题词汇 · Sports","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"球类项目、比赛规则、健身锻炼与运动精神四组词一起记，既能听懂赛事类听力材料，也能写出结构清楚的「我最喜欢的运动」作文。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"play 后接球类不加 the，接乐器要加 the。","explain":"play football、play basketball、play table tennis 中间不加 the；play the piano、play the violin 必须加 the。这是语法选择与写作细节的高频考点，判断办法：先看后面是球还是乐器。"},{"level":"重点","text":"win / beat / lose 的宾语分工。","explain":"win 后接比赛或奖项（win the game、win the first prize），beat 后接对手（beat Class Two），lose 后接比赛（lose the match）。完形填空看空格后的宾语类型判断：宾语是队名、人名就选 beat。"},{"level":"重点","text":"do、go、play 三种「做运动」的动词搭配。","explain":"do sports 做运动、do exercise 锻炼、go swimming 去游泳（go + doing）、play basketball 打篮球。写作中并列三句时轮换使用，句子有变化，比反复说 I like playing 更得分。"},{"level":"次重点","text":"系动词后接形容词：keep fit、stay healthy。","explain":"keep / stay 后作表语的必须是形容词，所以 keep fit、stay healthy 都对，而 keep health、stay healthily 都错。语法填空给出 keep、stay 时优先考虑形容词形式。"},{"level":"次重点","text":"描述运动习惯用一般现在时，描述比赛结果用一般过去时。","explain":"every day、often、twice a week 配一般现在时；last week、yesterday、in the match 配一般过去时。写作中写「我每周打两次篮球，上周赢了一场比赛」需要两种时态，时间状语是判断依据。"},{"level":"了解","text":"运动精神类句子可作作文结尾。","explain":"Never give up.、Teamwork is important.、Practice makes perfect. 三句都能直接用在运动类作文的结尾段，句子短、语法稳、立意积极。"}]},{"type":"table","title":"球类与项目","head":["单词","词性/音标","释义","考点"],"rows":[["sport","n.","运动；体育","do sports 做运动；a sports meeting 运动会"],["football","n.","足球","play football 不加 the；美式用 soccer"],["basketball","n.","篮球","play basketball 不加 the"],["volleyball","n.","排球","拼写注意 volley 中双写 l，再加 ball"],["baseball","n.","棒球","base + ball 合成词"],["tennis","n.","网球","play tennis 不加 the；table tennis 是乒乓球"],["table tennis","n.","乒乓球","也可说 ping-pong，是中国最普及的项目之一"],["badminton","n.","羽毛球","注意拼写 bad-min-ton，中间有 d 和 t"],["ball","n.","球","可数：kick the ball 踢球"],["match","n.","比赛","英式常用 match，美式用 game；a football match"],["team","n.","队；队伍","作整体时谓语可用单数，强调队员时用复数"],["player","n.","运动员；选手","由 play 加 -er 构成，注意不双写"],["coach","n.","教练","也作动词「训练」；发音 /kəʊtʃ/"],["swimming","n.","游泳","go swimming 去游泳，重读闭音节要双写 m"],["running","n.","跑步","run 双写 n 加 -ing；go running 去跑步"],["skating","n.","滑冰","go skating 去滑冰"],["chess","n.","国际象棋","play chess 不加 the，棋类与球类同一规则"]]},{"type":"table","title":"比赛与规则","head":["单词","词性/音标","释义","考点"],"rows":[["game","n.","比赛；游戏","ball games 球类运动；watch a game 看比赛"],["race","n.","赛跑；比赛","a running race 赛跑；win the race 赢得比赛"],["win","v.","赢；获胜","过去式 won；win 后接比赛或奖项"],["winner","n.","获胜者","双写 n 加 -er，拼写易错"],["lose","v.","输；丢失","过去式 lost；lose the match 输掉比赛"],["beat","v.","打败；击败","过去式 beat，过去分词 beaten；后接对手"],["score","n./v.","得分；比分","score a goal 进球得分；the final score 最终比分"],["goal","n.","球门；进球；目标","score a goal 进一球；也可表「目标」"],["rule","n.","规则","follow / break the rules 遵守 / 违反规则"],["pass","v.","传球；传递","pass the ball to sb 把球传给某人"],["kick","v.","踢","kick the ball 踢球，重读短音 /kɪk/"],["throw","v.","扔；投","不规则变化 throw - threw - thrown"],["catch","v.","接住；抓住","不规则变化 catch - caught - caught"],["hit","v.","打；击中","hit - hit - hit，原形、过去式同形"],["train","v./n.","训练；火车","train hard 刻苦训练；by train 乘火车"],["practice","n./v.","练习","名词写法 practice；英式动词是 practise，注意区分"]]},{"type":"table","title":"健身与锻炼","head":["单词","词性/音标","释义","考点"],"rows":[["exercise","n./v.","锻炼；练习","表锻炼时不可数：do exercise；表练习题时用复数 exercises"],["health","n.","健康","不可数名词：good health 身体健康"],["healthy","adj.","健康的","stay healthy；反义词 unhealthy"],["fit","adj.","健康的；合适的","keep fit 保持健康，固定搭配不加 the"],["strong","adj.","强壮的","比较级 stronger；strong will 坚强的意志"],["tired","adj.","疲倦的","be tired of 对……厌倦，与 be tired from 意思不同"],["relax","v.","放松","relax myself 放松自己；形容词 relaxed / relaxing"],["jog","v.","慢跑","过去式 jogged 双写 g；go jogging 去慢跑"],["walk","v./n.","走；散步","take a walk 散步；walk to school 走路上学"],["run","v.","跑","不规则变化 run - ran - run；双写 n 加 -ing"],["ride","v.","骑（车、马）","不规则变化 ride - rode - ridden"],["swim","v.","游泳","不规则变化 swim - swam - swum"],["climb","v.","攀登；爬","b 不发音；climb the mountain 爬山"],["warm up","phr.","热身","运动前必做：We should warm up before running."],["habit","n.","习惯","个人的习惯用 habit；form a good habit 养成好习惯"],["energy","n.","精力；能量","不可数；full of energy 精力充沛"]]},{"type":"table","title":"运动精神","head":["单词","词性/音标","释义","考点"],"rows":[["spirit","n.","精神","the spirit of sports 体育精神；不可数名词"],["teamwork","n.","团队合作","不可数；Teamwork is very important. 常作作文结尾句"],["brave","adj.","勇敢的","be brave enough to do sth 勇敢到能做某事"],["confident","adj.","自信的","be confident of / about sth"],["confidence","n.","自信","不可数；build up confidence 建立自信"],["hard-working","adj.","勤奋的","复合形容词带连字符，作定语修饰人"],["never give up","phr.","永不放弃","give up 后接名词或动名词：give up trying"],["try one's best","phr.","尽某人最大努力","one's 要随主语变化：try my best、try his best"],["fail","v.","失败；不及格","fail to do sth 未能做某事；fail the exam 考试不及格"],["success","n.","成功","不可数；也可作可数名词指「成功的人或事」"],["successful","adj.","成功的","be successful in doing sth"],["succeed","v.","成功","succeed in doing sth，介词是 in"],["cheer","v.","欢呼；加油","cheer sb on 为某人加油"],["support","v./n.","支持","support sb 支持某人；with one's support"],["encourage","v.","鼓励","encourage sb to do sth，是作文高频句型"],["proud","adj.","自豪的","be proud of sb / sth 为……感到自豪"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["play football","踢足球","球类前不加 the。"],["do sports","做运动","sports 用复数；也可说 do exercise。"],["keep fit","保持健康","fit 是形容词，不能说 keep fitness。"],["take part in a match","参加比赛","take part in 强调参加活动，join 强调加入组织。"],["win the first prize","获得一等奖","win 后接奖项，不接对手。"],["break the rules","违反规则","反义表达是 follow the rules。"],["cheer sb on","为某人加油","宾语是人时 on 不能省。"],["never give up","永不放弃","give up 后接动名词：give up trying。"]]},{"type":"list","title":"应试策略","items":["球类前不加 the（play football），乐器前加 the（play the piano），这是中考高频细节，语法选择和写作检查都要看一遍。","写运动类作文按「我喜欢的运动—练习时间与地点—它给我的好处」三段写，好处段直接用 keep fit、make friends、relax myself 这些现成表达。","牢记 win / beat / lose 的分工：赢比赛或奖项用 win，赢对手用 beat，输比赛用 lose，完形填空按空格后的宾语类型判断。","描述经常性的运动用一般现在时，描述上周的比赛用一般过去时，先圈出 every day、last week 这类时间状语再定时态。"]}],"questions":[{"id":"eng-vocab-topic-10-q1","type":"choice","stem":"Our team ______ the match yesterday and the players were very excited.","answer":"A","explain":"yesterday 说明用一般过去时，球员很兴奋说明赢了比赛，win 的过去式是 won。B 项 win 是原形，与 yesterday 不符；C 项 beaten 是过去分词，不能单独作谓语；D 项 lose 是原形，且与 were very excited 的语境矛盾。","options":["won","win","beaten","lose"],"difficulty":1,"tags":["话题词汇","体育运动","动词时态"]},{"id":"eng-vocab-topic-10-q2","type":"choice","stem":"Doing sports every day can help you stay ______.","answer":"A","explain":"stay 在这里是系动词，后面接形容词作表语，healthy 符合「每天运动」的语境。B 项 health 是名词；C 项 healthily 是副词，不能作表语；D 项 unhealthy 意为「不健康的」，与语境相反。","options":["healthy","health","healthily","unhealthy"],"difficulty":1,"tags":["话题词汇","体育运动","形容词作表语"]},{"id":"eng-vocab-topic-10-q3","type":"choice","stem":"Every player must ______ the rules of the game.","answer":"A","explain":"follow the rules 是「遵守规则」，与 must（必须）的语气一致。B 项 break the rules 是「违反规则」，C 项 forget 是「忘记」，D 项 lose 是「失去」，都不符合「每位球员都必须……」的要求。","options":["follow","break","forget","lose"],"difficulty":1,"tags":["话题词汇","体育运动","固定搭配"]},{"id":"eng-vocab-topic-10-q4","type":"choice","stem":"He ______ his best and won the first prize in the running race.","answer":"A","explain":"后半句 won 说明叙述的是过去的事，前半句也要用过去式 tried；try 变过去式要先改 y 为 i 再加 -ed。B 项 try 与 C 项 tries 时态不符，D 项 trying 是现在分词，不能单独作谓语。","options":["tried","try","tries","trying"],"difficulty":2,"tags":["话题词汇","体育运动","动词时态","拼写"]},{"id":"eng-vocab-topic-10-q5","type":"choice","stem":"In a football match, the player who ______ the ball into the goal scores a point.","answer":"A","explain":"定语从句的先行词 the player 是第三人称单数，从句谓语要用 kicks；句子讲的是比赛中的一般规则，所以用一般现在时。B 项 kick 与主语不一致；C 项 kicked 是过去式，与「一般规则」的时态不符；D 项 kicking 不是谓语形式。","options":["kicks","kick","kicked","kicking"],"difficulty":3,"tags":["话题词汇","体育运动","主谓一致","定语从句"]},{"id":"eng-vocab-topic-10-q6","type":"choice","stem":"Our coach often tells us never to ______ up, even when we lose.","answer":"A","explain":"give up 是「放弃」，与 never 连用表示「永不放弃」，符合教练鼓励队员的语境。put up 是「举起、搭建」，look up 是「查阅、抬头看」，take up 是「开始从事、占用」，都与 lose 的语境不符。","options":["give","put","look","take"],"difficulty":2,"tags":["话题词汇","体育运动","动词短语"]}]},{"id":"eng-vocab-topic-11","title":"话题词汇·职业与工作","subtitle":"话题词汇 · Jobs and work","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"职业名称、工作场所、求职理想与劳动责任四组词配套记，让「我的理想职业」这类中考高频作文既有准确词汇，又有可用句型。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"job 可数，work 不可数。","explain":"空前有 a / a good 时要用 job（find a good job、a part-time job）；泛指工作、劳动时用 work（hard work、go to work、after work）。语法选择常以 a good ______ 的形式考这一条，看到 a 就不能选 work。"},{"level":"重点","text":"职业名词靠后缀构成。","explain":"词形转换题给动词或名词要求填职业名词：teach → teacher、drive → driver、act → actor、science → scientist、art → artist、report → reporter。判断办法：-er / -or 多表示人，-ist 表示从事某专业的人；nurse、farmer、lawyer 这类词考的是拼写而非转换。"},{"level":"重点","text":"表达理想用 want to be，不能丢 be。","explain":"写作开头句常用 When I grow up, I want to be a doctor. 注意 want 后接 to be + 职业名词，职业名词前要有 a / an；不说 I want to be become a doctor，也不说 I want to a doctor。"},{"level":"次重点","text":"be responsible for 与 It is our duty to ...","explain":"写「责任」类作文时，用 Everyone should be responsible for ... 或 It is our duty to ...。responsible 是形容词，responsibility 是名词，语法填空按空前是 be 动词还是冠词来判断填哪一种。"},{"level":"次重点","text":"patient 作形容词是「有耐心的」，作名词是「病人」。","explain":"be patient with sb 对某人有耐心，是固定搭配；a patient 指一名病人。阅读中要按上下文判断词义，不要一律译成「病人」，否则细节题容易选错。"},{"level":"了解","text":"问职业的两种句型可以互相替换。","explain":"What does your father do? 与 What is your father's job? 同义，回答都用 He is a / an + 职业。听说信息获取题常考这一组同义转换，听到一个要能对应另一个。"}]},{"type":"table","title":"常见职业","head":["单词","词性/音标","释义","考点"],"rows":[["job","n.","工作；职业","可数名词：find a good job；问职业 What's your job?"],["doctor","n.","医生","前面用 a；也可说 see a doctor 看医生"],["nurse","n.","护士","拼写注意末尾有 e：n-u-r-s-e"],["teacher","n.","教师","teach 加 -er 构成；发音 /ˈtiːtʃə(r)/，注意长音 /iː/"],["engineer","n.","工程师","以元音音素开头，前面用 an；拼写是 -eer 结尾"],["worker","n.","工人","work 加 -er 构成"],["farmer","n.","农民","farm 加 -er 构成；也要注意 farm 是农场"],["policeman","n.","警察（男）","复数 policemen；女警察是 policewoman"],["driver","n.","司机","drive 去 e 加 -r 构成"],["cook","n./v.","厨师；烹饪","cook 是厨师，cooker 是炊具，别混用"],["waiter","n.","服务员（男）","女服务员是 waitress；在餐馆工作"],["scientist","n.","科学家","science 变 scientist，注意 -tist 结尾"],["artist","n.","艺术家；画家","art 加 -ist 构成"],["writer","n.","作家","write 去 e 加 -r 构成"],["reporter","n.","记者","report 直接加 -er，report 末尾不双写"],["lawyer","n.","律师","注意拼写是 -yer，发音 /ˈlɔːjə(r)/"],["manager","n.","经理","manage 加 -r；公司里的负责人"],["postman","n.","邮递员","复数 postmen，把 man 改成 men"]]},{"type":"table","title":"工作内容与场所","head":["单词","词性/音标","释义","考点"],"rows":[["work","v./n.","工作；劳动","表示工作时不可数：hard work、go to work"],["office","n.","办公室","in the office 在办公室；office worker 职员"],["factory","n.","工厂","复数 factories，改 y 为 ies"],["hospital","n.","医院","in hospital 住院；in the hospital 在医院里"],["company","n.","公司","复数 companies；work for a company"],["restaurant","n.","餐馆","拼写易错：rest-au-rant，美音重音在后"],["bank","n.","银行；河岸","名词多义，按上下文判断"],["hotel","n.","旅馆；酒店","stay at a hotel 住酒店"],["farm","n.","农场","on the farm 在农场；farmer 是农民"],["library","n.","图书馆","复数 libraries；借书用 borrow books from the library"],["lab","n.","实验室","laboratory 的缩写，in the lab 在实验室"],["teach","v.","教；讲授","teach sb sth；过去式 taught"],["serve","v.","服务；招待","serve the people 为人民服务；名词 service"],["design","v./n.","设计","design a car 设计汽车；designer 是设计师"],["repair","v.","修理","repair the bike 修自行车"],["look after","phr.","照顾；照料","与 take care of 同义；after 是介词，宾语只能放在后面"]]},{"type":"table","title":"求职与理想","head":["单词","词性/音标","释义","考点"],"rows":[["dream","n./v.","梦想；做梦","achieve one's dream 实现梦想"],["future","n.","未来","in the future 将来，常作作文结尾时间状语"],["hope","v./n.","希望","hope to do sth / hope that ...，不说 hope sb to do"],["want to be","phr.","想成为","want 后接 to be + 职业名词，be 不能省"],["grow up","phr.","长大","When I grow up 是理想类作文的经典开头"],["interview","n./v.","面试；采访","have an interview 参加面试"],["experience","n.","经验；经历","作「经验」不可数，作「经历」可数"],["skill","n.","技能；技巧","可数：learn some new skills"],["ability","n.","能力","the ability to do sth 做某事的能力"],["choose","v.","选择","choose - chose - chosen；choose to do sth"],["decide","v.","决定","decide to do sth 决定做某事"],["decision","n.","决定","make a decision 做出决定"],["plan","n./v.","计划","make a plan 制定计划；plan to do sth"],["interest","n.","兴趣","show great interest in sth 对……表现出兴趣"],["be interested in","phr.","对……感兴趣","interested 修饰人，interesting 修饰事物"],["in the future","phr.","在将来","将来时间状语，句子常用一般将来时"]]},{"type":"table","title":"劳动与责任","head":["单词","词性/音标","释义","考点"],"rows":[["duty","n.","责任；义务","It is our duty to do sth 做某事是我们的责任"],["responsible","adj.","有责任的","be responsible for sth 对某事负责，介词是 for"],["responsibility","n.","责任","名词形式；take responsibility for sth"],["work hard","phr.","努力工作；努力学习","hard 是副词，不写成 hardly（几乎不）"],["help others","phr.","帮助他人","others 泛指他人，others 前不加 the"],["service","n.","服务","不可数：good service 优质服务"],["task","n.","任务","finish the task 完成任务"],["finish","v.","完成","finish doing sth 完成后接动名词，不接不定式"],["complete","v./adj.","完成；完整的","complete the work 完成工作"],["careful","adj.","仔细的；小心的","be careful with sth 对某物小心"],["patient","adj./n.","有耐心的；病人","be patient with sb 对某人有耐心"],["honest","adj.","诚实的","h 不发音，前面用 an：an honest boy"],["take care of","phr.","照顾；照料","与 look after 同义，可互相替换"],["on time","phr.","准时","与 in time（及时）区别：on time 是不迟到的意思"],["share","v.","分享；分担","share the housework 分担家务"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["find a good job","找到一份好工作","job 可数，前面必须有 a。"],["work as a teacher","当老师","work as + 职业，表示「从事……工作」。"],["go to work","去上班","work 前不加 the；go to work by bus。"],["be responsible for","对……负责","介词固定用 for，不要用 of。"],["be patient with sb","对某人有耐心","介词用 with，不要用 to。"],["grow up","长大","When I grow up 是理想类作文开头。"],["in the future","在将来","与句子用一般将来时搭配。"],["take care of","照顾","可与 look after 互相替换。"]]},{"type":"list","title":"应试策略","items":["职业名词拼写是写作细节分：engineer、scientist、reporter、waiter、lawyer 最容易拼错，交卷前专门检查一遍。","写「我的理想职业」按「是什么—为什么—怎么做」三段：第一段 I want to be a ... when I grow up，第二段给两个理由，第三段写现在该怎么做（study hard、learn English well）。","语法填空遇到 be responsible ______、be patient ______ 这类结构，先记固定介词（for、with），介词写错整题丢分。","问职业的问答在听说信息获取里常出现，注意 What does he do? 与 What is his job? 的互换，回答时职业名词前要加 a / an。"]}],"questions":[{"id":"eng-vocab-topic-11-q1","type":"choice","stem":"My aunt works in a hospital and looks after sick people. She is a ______.","answer":"A","explain":"在医院里照顾病人的是护士 nurse。B 项 driver 是司机，C 项 farmer 是农民，D 项 waiter 是餐厅服务员，三者的工作场所与工作内容都与句中的 hospital、look after sick people 不符。","options":["nurse","driver","farmer","waiter"],"difficulty":1,"tags":["话题词汇","职业与工作","语境选词"]},{"id":"eng-vocab-topic-11-q2","type":"choice","stem":"When I ______ up, I want to be a scientist.","answer":"A","explain":"grow up 是「长大」，When I grow up 是表达理想的常用开头。B 项 get up 是「起床」，C 项 put up 是「举起、搭建」，D 项 make up 是「编造、化妆」，都不能与 When I ... up 构成「长大以后」的意思。","options":["grow","get","put","make"],"difficulty":1,"tags":["话题词汇","职业与工作","动词短语"]},{"id":"eng-vocab-topic-11-q3","type":"choice","stem":"It is not easy for young people to find a good ______ in a big city.","answer":"A","explain":"空前有 a，需要一个可数名词，job 意为「工作、职位」，可以加 a 并变复数。B 项 work 表示「工作」时不可数，不能说 a good work；C 项 task 是「任务」；D 项 matter 是「事情、问题」，都与「找工作」的意思不符。","options":["job","work","task","matter"],"difficulty":2,"tags":["话题词汇","职业与工作","名词可数性"]},{"id":"eng-vocab-topic-11-q4","type":"choice","stem":"A good doctor should be ______ with his patients.","answer":"A","explain":"be patient with sb 是「对某人有耐心」的固定搭配，空格在 be 后面作表语，要用形容词 patient。B 项 patience 是名词；C 项 patiently 是副词，不能作表语；D 项 impatient 意为「不耐烦的」，与 a good doctor 的语境相反。","options":["patient","patience","patiently","impatient"],"difficulty":2,"tags":["话题词汇","职业与工作","固定搭配"]},{"id":"eng-vocab-topic-11-q5","type":"choice","stem":"Everyone should be ______ for their own work.","answer":"A","explain":"be responsible for 是「对……负责」的固定搭配，空格在 be 后面要用形容词 responsible。B 项 responsibility 是名词；C 项 responsibly 是副词；D 项 response 是名词「回答、反应」，都不能与 be ... for 搭配。","options":["responsible","responsibility","responsibly","response"],"difficulty":2,"tags":["话题词汇","职业与工作","词性转换"]},{"id":"eng-vocab-topic-11-q6","type":"fill","stem":"The man whose job is to design buildings and machines is an ______.（工程师）","answer":"engineer|Engineer","explain":"「工程师」是 engineer，以元音音素开头，所以前面用 an。拼写注意结尾是 -eer，不是 -er，不要写成 enginer。","difficulty":2,"tags":["话题词汇","职业与工作","拼写"]}]},{"id":"eng-vocab-topic-12","title":"话题词汇·社会与规则","subtitle":"话题词汇 · Society and rules","grade":"all","tags":["话题词汇"],"blocks":[{"type":"note","title":"学习要点","text":"公共场所、交通规则、法律秩序与志愿服务四组词连成「守规则、做好事」的表达网络，覆盖安全类听说题与社会责任类作文。"},{"type":"points","title":"考点分层","items":[{"level":"重点","text":"keep + 宾语 + 形容词 表示「使……保持某种状态」。","explain":"keep our voice low、keep the classroom clean、keep the city tidy 都是公共场所话题的高频表达。形容词作宾语补足语，不能用副词，所以 keep our voice lowly 是典型错误。语法选择与写作都会考这一结构。"},{"level":"重点","text":"规则语气分三层：must、have to、should。","explain":"must 表示说话人认为必须（You must obey the rules.），have to 表示客观上不得不（We have to wear a helmet.），should 表示建议（We should keep quiet.），mustn't 表示禁止。语法选择按语气强弱判断，写作中三层各写一句，逻辑清楚。"},{"level":"重点","text":"交通与安全表达要成串记。","explain":"写作与听说安全提示常用 cross the road at the zebra crossing、wait for the green light、wear a helmet、obey the traffic rules。这些短语考的是完整性，漏掉 the 或介词写错就丢分，建议整块背。"},{"level":"次重点","text":"raise 及物，rise 不及物。","explain":"raise 后面必须接宾语（raise money、raise your hand），rise 后面不能接宾语（The sun rises in the east.；Prices are rising.）。语法填空先看后面有没有宾语即可定答案，过去式分别是 raised 与 rose。"},{"level":"次重点","text":"volunteer 既可作名词也可作动词。","explain":"作名词是「志愿者」（work as a volunteer），作动词是「自愿做」（volunteer to do sth）。作文中 work as a volunteer、do voluntary work、take part in voluntary activities 三种表达都可轮换使用。"},{"level":"了解","text":"in public 前不加 the。","explain":"in public 意为「在公共场合」，是固定短语，前面不加 the 也不加 a；in public places 则指具体的公共场所，places 通常用复数。两者常在同一篇作文里出现，要分清楚。"}]},{"type":"table","title":"公共场所与设施","head":["单词","词性/音标","释义","考点"],"rows":[["public","adj.","公共的；公开的","in public 当众，前不加 the；public places 公共场所"],["place","n.","地方；地点","可数名词；take place 发生，是不及物短语"],["park","n./v.","公园；停放（车）","No parking 禁止停车"],["museum","n.","博物馆","visit a museum 参观博物馆，前面用 a"],["cinema","n.","电影院","英式 cinema，美式 movie theater"],["theatre","n.","剧院","英式拼写 theatre，美式 theater"],["zoo","n.","动物园","复数 zoos，直接加 s"],["post office","n.","邮局","两个词都小写，指具体某家时加 the"],["police station","n.","警察局","police 是复数概念，作主语时谓语用复数"],["bus stop","n.","公共汽车站","at the bus stop 在公交站"],["subway","n.","地铁","美式说法，英式常用 underground / tube"],["square","n.","广场；正方形","Tian'anmen Square 天安门广场"],["market","n.","市场","at the market 在市场；supermarket 是超市"],["supermarket","n.","超市","可数名词，go to the supermarket"],["sign","n.","标志；牌子","a No Smoking sign 禁止吸烟标志"],["notice","n./v.","通知；告示；注意到","put up a notice 张贴通知"],["seat","n.","座位","take a seat 坐下；give one's seat to sb 让座"],["toilet","n.","洗手间","英式常用 toilet，美式常用 restroom"]]},{"type":"table","title":"交通规则与安全","head":["单词","词性/音标","释义","考点"],"rows":[["traffic","n.","交通；来往车辆","不可数；traffic rules 交通规则"],["obey","v.","遵守；服从","obey the traffic rules 遵守交通规则"],["follow","v.","遵守；跟随","follow the rules 与 obey the rules 同义"],["cross","v.","穿过；横过","cross the road 过马路，及物动词不加 across"],["crossing","n.","十字路口；人行横道","zebra crossing 斑马线，是固定搭配"],["traffic lights","n.","红绿灯","常用复数；wait for the green light 等绿灯"],["zebra crossing","n.","斑马线","英式说法；美式是 crosswalk"],["road","n.","路；公路","on the road 在路上；by the road 在路边"],["street","n.","街道","in the street 在街上（英式常用 in）"],["fast","adj./adv.","快的；快地","既可作形容词也可作副词，不说 fastly"],["slow","adj.","慢的","副词 slowly；Slow down! 慢一点！"],["danger","n.","危险","in danger 处于危险中；形容词是 dangerous"],["dangerous","adj.","危险的","It is dangerous to do sth 做某事有危险"],["safe","adj.","安全的","keep safe 保持安全；名词是 safety"],["safety","n.","安全","不可数：traffic safety 交通安全"],["accident","n.","事故；意外","have a traffic accident 发生交通事故"],["hurt","v.","使受伤；疼痛","hurt - hurt - hurt，原形与过去式同形"],["helmet","n.","头盔","wear a helmet 戴头盔，骑车安全话题必用"]]},{"type":"table","title":"法律与秩序","head":["单词","词性/音标","释义","考点"],"rows":[["law","n.","法律","可数：obey the law 遵守法律"],["order","n./v.","秩序；命令；点（菜）","keep order 维持秩序，作「秩序」不可数"],["police","n.","警察","单复数同形，作主语时谓语用复数"],["right","n./adj.","权利；正确的","have the right to do sth 有权做某事"],["wrong","adj.","错误的；不对的","What's wrong with you? 你怎么了"],["punish","v.","惩罚","punish sb for sth 因某事惩罚某人"],["allow","v.","允许","allow sb to do sth；被动 be allowed to do sth"],["warn","v.","警告；提醒","warn sb not to do sth 提醒某人别做某事"],["break","v.","违反；打破","break the rules 违反规则；break - broke - broken"],["against","prep.","违反；反对；靠着","be against the rules 违反规则"],["fair","adj.","公平的","It is not fair. 不公平；反义词 unfair"],["society","n.","社会","常用单数加 the：in modern society"],["duty","n.","责任；义务","It is everyone's duty to ... 每个人都有责任……"],["protect","v.","保护","protect sb from danger 保护某人免受危险"],["honest","adj.","诚实的","h 不发音，前面用 an：an honest man"]]},{"type":"table","title":"志愿服务与公益","head":["单词","词性/音标","释义","考点"],"rows":[["volunteer","n./v.","志愿者；自愿做","work as a volunteer 当志愿者；volunteer to do sth"],["service","n.","服务","不可数；community service 社区服务"],["donate","v.","捐赠","donate sth to sb 把某物捐给某人，介词是 to"],["raise","v.","筹集；举起；提高","及物动词：raise money 筹钱；过去式 raised"],["money","n.","钱","不可数；raise money for ... 为……筹钱"],["poor","adj.","贫穷的；可怜的","the poor 表示「穷人」，指一类人"],["care","v./n.","关心；照顾","care about sb 关心某人；take care 保重"],["kind","adj./n.","善良的；种类","It is kind of sb to do sth 某人做某事真好"],["friendly","adj.","友好的","be friendly to sb 对某人友好，是形容词不是副词"],["community","n.","社区","复数 communities；in our community 在我们社区"],["activity","n.","活动","复数 activities，改 y 为 ies；take part in activities"],["organize","v.","组织","organize an activity 组织活动；英式也写 organise"],["join","v.","加入；参加","join 后接组织或人；join us 加入我们"],["take part in","phr.","参加（活动）","强调参加活动并在其中起作用"],["the old","n.","老人","the + 形容词表示一类人，如 the old、the young"],["meaningful","adj.","有意义的","a meaningful activity 有意义的活动，作文常用"]]},{"type":"table","title":"高频搭配","head":["搭配","释义","提示"],"rows":[["obey the traffic rules","遵守交通规则","也可说 follow the traffic rules。"],["cross the road at the zebra crossing","走斑马线过马路","cross 是及物动词，后面不加 across。"],["wait for the green light","等绿灯","wait for 后接等待的对象。"],["in public places","在公共场所","places 用复数；in public 是固定短语，不加 the。"],["keep our voice low","说话小声","keep + 宾语 + 形容词，不能用副词 lowly。"],["keep order","维持秩序","order 作「秩序」时不可数，不用复数。"],["take part in voluntary activities","参加志愿活动","take part in 后接活动，join 后接组织。"],["raise money for the poor","为穷人筹钱","raise 及物；the poor 表示「穷人」这一群体。"]]},{"type":"list","title":"应试策略","items":["规则类话题按「必须—应该—禁止」三层写句子：You must ...、We should ...、We mustn't ...，语气清楚、得分稳。","公共场所话题的形容词成对记：clean / dirty、quiet / noisy、safe / dangerous，完形填空常以反义对比出题。","志愿活动类作文不要只写 I am happy，要写出具体行动（pick up rubbish、help old people cross the road、raise money），才有内容分。","交通安全短语搭配固定（obey the traffic rules、wait for the green light、wear a helmet），写作前先列短语再连成句，能有效避免中式英语。"]}],"questions":[{"id":"eng-vocab-topic-12-q1","type":"choice","stem":"We should cross the road at the zebra ______.","answer":"A","explain":"zebra crossing 是「斑马线」的固定说法，crossing 是名词，指供行人过街的地方。B 项 cross 是动词；C 项 crossed 是过去式；D 项 crosses 是第三人称单数形式，都不能与 zebra 构成名词短语。","options":["crossing","cross","crossed","crosses"],"difficulty":1,"tags":["话题词汇","社会与规则","固定搭配"]},{"id":"eng-vocab-topic-12-q2","type":"choice","stem":"It is ______ to ride a bike without a helmet on a busy road.","answer":"A","explain":"It is + 形容词 + to do sth 是固定句型，空格处要用形容词；在车多的路上骑车不戴头盔是危险的，故选 dangerous。B 项 danger 是名词；C 项 dangerously 是副词，不能作表语；D 项 safe 意为「安全的」，与语境相反。","options":["dangerous","danger","dangerously","safe"],"difficulty":2,"tags":["话题词汇","社会与规则","形容词作表语"]},{"id":"eng-vocab-topic-12-q3","type":"choice","stem":"The students ______ money to help the children in the mountain village last month.","answer":"A","explain":"raise 是及物动词，raise money 表示「筹集钱」，过去式是 raised，与 last month 一致。B 项 rose 与 C 项 risen 都是不及物动词 rise（上升）的形式，不能带宾语 money；D 项 took 与 money 搭配不表示「筹集」。","options":["raised","rose","risen","took"],"difficulty":3,"tags":["话题词汇","社会与规则","易混动词"]},{"id":"eng-vocab-topic-12-q4","type":"choice","stem":"In public places, we should keep our voice ______.","answer":"A","explain":"keep + 宾语 + 形容词表示「使……保持某种状态」，low 是形容词，keep our voice low 意为「说话小声」。B 项 loudly 与 C 项 aloud 都是副词，不能作宾语补足语；D 项 noisy 是「吵闹的」，与公共场所应保持安静的要求相反。","options":["low","loudly","aloud","noisy"],"difficulty":3,"tags":["话题词汇","社会与规则","宾语补足语"]},{"id":"eng-vocab-topic-12-q5","type":"choice","stem":"Laws are made to keep ______ in society.","answer":"A","explain":"keep order 是「维持秩序」，order 作「秩序」讲时不可数，不用复数。B 项 orders 通常指「命令、订单」；C 项 orderly 是形容词，不能作 keep 的宾语；D 项 ordered 是动词过去式，同样不能作宾语。","options":["order","orders","orderly","ordered"],"difficulty":3,"tags":["话题词汇","社会与规则","固定搭配"]},{"id":"eng-vocab-topic-12-q6","type":"choice","stem":"We mustn't ______ the rules of the school.","answer":"A","explain":"mustn't 表示禁止，与 break the rules（违反规则）搭配才合理。B 项 keep 与 C 项 follow 都是「遵守」，语义与 mustn't 的禁令矛盾；D 项 make the rules 是「制定规则」，不是学生被禁止做的事情，与语境不符。","options":["break","keep","follow","make"],"difficulty":1,"tags":["话题词汇","社会与规则","语境选词"]}]}];
